INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'opening credits', 'Opening Credits', 0, NULL, 'This is White Nights, a poignant tale of love, loneliness, and dreams, written by Fyodor Dostoyevsky, translated by Tim Zengerink, narrated by Zeke Ring.', '', NULL, NULL, NULL, NULL, 'white nights opening credits', 'this is white nights a poignant tale of love loneliness and dreams written by fyodor dostoyevsky translated by tim zengerink narrated by zeke ring', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'the book in brief', 'The Book in Brief', 0, NULL, 'The narrator of this story has no name, and that is fitting, for he has almost no life to attach a name to. He is twenty-six years old and has lived in Petersburg for eight years without making a single friend. Having no people to be intimate with, he has grown intimate with things and with strangers: he forms attachments to the houses along the streets, greeting them as acquaintances, and invents whole histories for the passers-by he will never address. He calls himself, without much apology and without much pride, a dreamer. His real existence being empty, he lives instead upon invented romances, and the rare moments in which something actually happens to him he carries home and relives in fantasy until they are worn thin. The immediate cause of his sadness at the opening is small and precise: everyone in Petersburg is departing for the summer villas, and he is left behind, with nowhere to go and no one to invite him. It is out of this particular loneliness — the city emptying, the dreamer remaining — that everything else proceeds.', '', NULL, NULL, NULL, NULL, 'white nights the book in brief', 'the narrator of this story has no name and that is fitting for he has almost no life to attach a name to he is twenty six years old and has lived in petersburg for eight years without making a single friend having no people to be intimate with he has grown intimate with things and with strangers he forms attachments to the houses along the streets greeting them as acquaintances and invents whole histories for the passers by he will never address he calls himself without much apology and without much pride a dreamer his real existence being empty he lives instead upon invented romances and the rare moments in which something actually happens to him he carries home and relives in fantasy until they are worn thin the immediate cause of his sadness at the opening is small and precise everyone in petersburg is departing for the summer villas and he is left behind with nowhere to go and no one to invite him it is out of this particular loneliness the city emptying the dreamer remaining that everything else proceeds', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'the book in brief', 'The Book in Brief', 1, NULL, 'After a joyful day spent walking in the countryside outside the city, he returns at ten at night along a deserted canal embankment, and there he sees a young woman leaning upon the railing and crying. He does not dare speak to her. She notices him and hurries away; and here chance intervenes, for a drunken man begins to follow her, and the narrator, who would never have found the courage on his own account, drives the man off with his walking stick. That act of protection is what gives him the right to walk beside her, and thus the whole acquaintance rests upon an accident.', '', NULL, NULL, NULL, NULL, 'white nights the book in brief', 'after a joyful day spent walking in the countryside outside the city he returns at ten at night along a deserted canal embankment and there he sees a young woman leaning upon the railing and crying he does not dare speak to her she notices him and hurries away and here chance intervenes for a drunken man begins to follow her and the narrator who would never have found the courage on his own account drives the man off with his walking stick that act of protection is what gives him the right to walk beside her and thus the whole acquaintance rests upon an accident', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'the book in brief', 'The Book in Brief', 2, NULL, 'He does not court her. He confesses. Immediately and completely, without being asked, he tells her that he is shy, that he has never in his life had a relationship with a woman, that he falls in love only with imagined ideals, and that he does not know how to speak to a living one. What is remarkable, and what turns the encounter from an incident into a story, is that she does not mock him. She answers with warmth. She tells him that she too has no one in whom to confide, and that she feels as though she has known him twenty years already. She agrees to meet him at the same spot at ten the following night — but she insists that she must be there in any case, for a private reason of her own, which she will not disclose. And she sets one condition upon their friendship: he must not fall in love with her.', '', NULL, NULL, NULL, NULL, 'white nights the book in brief', 'he does not court her he confesses immediately and completely without being asked he tells her that he is shy that he has never in his life had a relationship with a woman that he falls in love only with imagined ideals and that he does not know how to speak to a living one what is remarkable and what turns the encounter from an incident into a story is that she does not mock him she answers with warmth she tells him that she too has no one in whom to confide and that she feels as though she has known him twenty years already she agrees to meet him at the same spot at ten the following night but she insists that she must be there in any case for a private reason of her own which she will not disclose and she sets one condition upon their friendship he must not fall in love with her', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'the book in brief', 'The Book in Brief', 3, NULL, 'He accepts the condition, which is the only way he could have been given the friendship at all. He cannot go home. He walks the whole night through, declaring to himself that in two minutes she has made him happy forever, and has perhaps reconciled him with himself. In that declaration the tension of the whole story is already set: the happiness of a dreamer built upon two minutes of borrowed reality, and the question, not yet asked aloud, of what will be left of him when the loan is called in.', '', NULL, NULL, NULL, NULL, 'white nights the book in brief', 'he accepts the condition which is the only way he could have been given the friendship at all he cannot go home he walks the whole night through declaring to himself that in two minutes she has made him happy forever and has perhaps reconciled him with himself in that declaration the tension of the whole story is already set the happiness of a dreamer built upon two minutes of borrowed reality and the question not yet asked aloud of what will be left of him when the loan is called in', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'the book in brief', 'The Book in Brief', 4, NULL, 'On the second night she returns and insists that they proceed sensibly. Before anything else, she demands that he tell her his whole story, for she does not yet know him. He answers that he has no story, because he has lived utterly alone: he has seen people all his life and has never truly spoken to any of them. Since he cannot give her events, he gives her a description of himself instead, and he gives it as though he were describing a species rather than a man. He is a type, he says: a dreamer, a creature who hides in a dim Petersburg corner as a snail hides in its shell, and who drives away his acquaintances one by one until there is no one left to drive away. He tries to make her understand the peculiar wealth of that condition — that the dreamer''s joy is real, an inner richness fed by fantasy, so intense and so obedient to his wishes that ordinary life afterwards seems dull, lifeless and slow by comparison. But he does not present this as a good bargain. He warns that a day arrives when the dreamer would give away every dream he has ever had for one moment of real, imperfect life. And he confesses that for him the day has come: his fancy has worn itself out, he has begun to celebrate the anniversaries of feelings that never occurred and of events that never took place, and he is afraid of growing old with nothing real behind him, not even anything worth regretting.', '', NULL, NULL, NULL, NULL, 'white nights the book in brief', 'on the second night she returns and insists that they proceed sensibly before anything else she demands that he tell her his whole story for she does not yet know him he answers that he has no story because he has lived utterly alone he has seen people all his life and has never truly spoken to any of them since he cannot give her events he gives her a description of himself instead and he gives it as though he were describing a species rather than a man he is a type he says a dreamer a creature who hides in a dim petersburg corner as a snail hides in its shell and who drives away his acquaintances one by one until there is no one left to drive away he tries to make her understand the peculiar wealth of that condition that the dreamers joy is real an inner richness fed by fantasy so intense and so obedient to his wishes that ordinary life afterwards seems dull lifeless and slow by comparison but he does not present this as a good bargain he warns that a day arrives when the dreamer would give away every dream he has ever had for one moment of real imperfect life and he confesses that for him the day has come his fancy has worn itself out he has begun to celebrate the anniversaries of feelings that never occurred and of events that never took place and he is afraid of growing old with nothing real behind him not even anything worth regretting', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'the book in brief', 'The Book in Brief', 5, NULL, 'He expects laughter. What he receives is tears. Nastenka — she gives him her name — weeps, and tells him that she recognizes herself in what he has said, because she felt precisely the same thing during the two years in which she sat pinned to her grandmother. She reveals that she lives with a blind grandmother who, two years earlier, pinned Nastenka''s dress to her own so that she could not run off. That single detail explains her: a girl kept literally fastened to an old woman''s side, whose only escape has been the same one he has taken.', '', NULL, NULL, NULL, NULL, 'white nights the book in brief', 'he expects laughter what he receives is tears nastenka she gives him her name weeps and tells him that she recognizes herself in what he has said because she felt precisely the same thing during the two years in which she sat pinned to her grandmother she reveals that she lives with a blind grandmother who two years earlier pinned nastenkas dress to her own so that she could not run off that single detail explains her a girl kept literally fastened to an old womans side whose only escape has been the same one he has taken', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'the book in brief', 'The Book in Brief', 6, NULL, 'He tells her that she has made him stop despising himself, and that these two evenings have given him the only real happiness he has known — and that he dreads, even while saying so, the moment when it will end. She will not hear of an ending. She vows that they will never part, and asks him to be to her like an elder brother, one who gives her warm advice. They clasp hands upon it, as though sealing a pact, and then, the pact being sealed, Nastenka begins to tell her own story.', '', NULL, NULL, NULL, NULL, 'white nights the book in brief', 'he tells her that she has made him stop despising himself and that these two evenings have given him the only real happiness he has known and that he dreads even while saying so the moment when it will end she will not hear of an ending she vows that they will never part and asks him to be to her like an elder brother one who gives her warm advice they clasp hands upon it as though sealing a pact and then the pact being sealed nastenka begins to tell her own story', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'the book in brief', 'The Book in Brief', 7, NULL, 'She is seventeen and an orphan, raised by the blind grandmother who pinned her dress to her own to keep her from misbehaving. The house has a top floor which is let to lodgers, and at a certain point a new lodger arrived: a young man, pleasant to look at, about whom the grandmother at once warned Nastenka to get no ideas. The bond between them began not with a declaration but with an act of tact. The lodger came upon Nastenka pinned to the old woman, saw her humiliation, said nothing at all, bowed silently and withdrew. He afterwards lent her books — French novels, Walter Scott, Pushkin — and these replaced her childish daydreams with a fuller imaginative life, which is to say that he made her, in a smaller way, what the narrator already was.', '', NULL, NULL, NULL, NULL, 'white nights the book in brief', 'she is seventeen and an orphan raised by the blind grandmother who pinned her dress to her own to keep her from misbehaving the house has a top floor which is let to lodgers and at a certain point a new lodger arrived a young man pleasant to look at about whom the grandmother at once warned nastenka to get no ideas the bond between them began not with a declaration but with an act of tact the lodger came upon nastenka pinned to the old woman saw her humiliation said nothing at all bowed silently and withdrew he afterwards lent her books french novels walter scott pushkin and these replaced her childish daydreams with a fuller imaginative life which is to say that he made her in a smaller way what the narrator already was', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'the book in brief', 'The Book in Brief', 8, NULL, 'Then he invited her to the theatre. She refused, because she would not deceive her grandmother; whereupon he took a box at The Barber of Seville for all three of them, so that the old woman might come too. Nastenka understood only later that the invitation had been a test of her character, and that she had passed it. After the opera season, however, he withdrew from them entirely. Nastenka grew restless and began to waste away, and concluded that what she had taken for love had been nothing but pity.', '', NULL, NULL, NULL, NULL, 'white nights the book in brief', 'then he invited her to the theatre she refused because she would not deceive her grandmother whereupon he took a box at the barber of seville for all three of them so that the old woman might come too nastenka understood only later that the invitation had been a test of her character and that she had passed it after the opera season however he withdrew from them entirely nastenka grew restless and began to waste away and concluded that what she had taken for love had been nothing but pity', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'the book in brief', 'The Book in Brief', 9, NULL, 'Then she learned that he was to leave for Moscow for a year. That knowledge broke her. She made up a bundle of her things and went to his room at night, and offered, in so many words, to go away with him. He did not take her. He refused because he was poor and had no right to bind her to himself; but he swore that if in a year''s time she still loved him, he would come back and marry her. They kept the promise secret from the grandmother, and Nastenka waited.', '', NULL, NULL, NULL, NULL, 'white nights the book in brief', 'then she learned that he was to leave for moscow for a year that knowledge broke her she made up a bundle of her things and went to his room at night and offered in so many words to go away with him he did not take her he refused because he was poor and had no right to bind her to himself but he swore that if in a years time she still loved him he would come back and marry her they kept the promise secret from the grandmother and nastenka waited', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'the book in brief', 'The Book in Brief', 10, NULL, 'The year is now up. He has been back in Petersburg three days, and he has not come to the bench where they agreed to meet at ten o''clock. That is the private reason she would not disclose; that is why she was standing at the railing weeping when the narrator first saw her; and that is why she has been at the same place each night since.', '', NULL, NULL, NULL, NULL, 'white nights the book in brief', 'the year is now up he has been back in petersburg three days and he has not come to the bench where they agreed to meet at ten oclock that is the private reason she would not disclose that is why she was standing at the railing weeping when the narrator first saw her and that is why she has been at the same place each night since', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'the book in brief', 'The Book in Brief', 11, NULL, 'The narrator, who has by this time begun to love her, does the thing that seals his own fate. He advises her to write. He dictates a letter for her — a letter which asserts her right to write without reproach and without pleading, neither accusing the man nor begging him — and Nastenka, laughing, produces the letter already written, sealed and carried about with her all the while. She entrusts it to the narrator to deliver, and asks him to bring any answer to the bench at ten the next night. So he becomes the agent of his rival''s return, and does it willingly. They laugh together over Rosina, part with "Till tomorrow," and he is left standing in the street elated and wholly in love.', '', NULL, NULL, NULL, NULL, 'white nights the book in brief', 'the narrator who has by this time begun to love her does the thing that seals his own fate he advises her to write he dictates a letter for her a letter which asserts her right to write without reproach and without pleading neither accusing the man nor begging him and nastenka laughing produces the letter already written sealed and carried about with her all the while she entrusts it to the narrator to deliver and asks him to bring any answer to the bench at ten the next night so he becomes the agent of his rivals return and does it willingly they laugh together over rosina part with till tomorrow and he is left standing in the street elated and wholly in love', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'the book in brief', 'The Book in Brief', 12, NULL, 'It is on the third night that the truth of his position becomes clear to him. He understands that all the warmth Nastenka has shown him — the vow never to part, the brotherhood, the tears — has been the overflow of a joy that was meant for another man, spilling onto whoever stood nearest. It was never love for him. She arrives radiant and early, certain that her lover will answer that night, and she tells the narrator, with perfect frankness and no cruelty at all, that she likes him precisely because he has not fallen in love with her, and that once she is married they will be friends closer than brother and sister.', '', NULL, NULL, NULL, NULL, 'white nights the book in brief', 'it is on the third night that the truth of his position becomes clear to him he understands that all the warmth nastenka has shown him the vow never to part the brotherhood the tears has been the overflow of a joy that was meant for another man spilling onto whoever stood nearest it was never love for him she arrives radiant and early certain that her lover will answer that night and she tells the narrator with perfect frankness and no cruelty at all that she likes him precisely because he has not fallen in love with her and that once she is married they will be friends closer than brother and sister', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'the book in brief', 'The Book in Brief', 13, NULL, 'The lover does not come. Footsteps approach along the embankment, raise their hopes and then carry someone else past; and Nastenka''s gaiety collapses into anxiety. The narrator tries, obliquely, to say what he feels, reaching for the image of a forgotten melody suddenly reawakening in a man who thought he had lost the capacity for it; but Nastenka guesses his meaning before he can arrive at it and hushes him. So he swallows it, and turns instead to comforting her: he invents reasons why the letter may have been delayed, and promises to go and ask for a reply at first light. Weeping, she compares the two men aloud. The narrator, she says, is the better man, kinder and more thoughtful — and yet she loves the other more. She feels, too, that he is sacrificing something for her sake, and thanks him for it, telling him that he is no longer the isolated dreamer he described himself as being. They part with her promise to come the day after tomorrow whatever happens, and with her question: they will always be together, will they not?', '', NULL, NULL, NULL, NULL, 'white nights the book in brief', 'the lover does not come footsteps approach along the embankment raise their hopes and then carry someone else past and nastenkas gaiety collapses into anxiety the narrator tries obliquely to say what he feels reaching for the image of a forgotten melody suddenly reawakening in a man who thought he had lost the capacity for it but nastenka guesses his meaning before he can arrive at it and hushes him so he swallows it and turns instead to comforting her he invents reasons why the letter may have been delayed and promises to go and ask for a reply at first light weeping she compares the two men aloud the narrator she says is the better man kinder and more thoughtful and yet she loves the other more she feels too that he is sacrificing something for her sake and thanks him for it telling him that he is no longer the isolated dreamer he described himself as being they part with her promise to come the day after tomorrow whatever happens and with her question they will always be together will they not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'the book in brief', 'The Book in Brief', 14, NULL, 'The fourth day is rainy, and she does not come. The narrator wanders to their bench, and then as far as her door, and turns back in shame at the last moment, and the day ends in the old loneliness. No reply to the letter has arrived either, and he concludes bitterly that the lovers must already be together.', '', NULL, NULL, NULL, NULL, 'white nights the book in brief', 'the fourth day is rainy and she does not come the narrator wanders to their bench and then as far as her door and turns back in shame at the last moment and the day ends in the old loneliness no reply to the letter has arrived either and he concludes bitterly that the lovers must already be together', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'the book in brief', 'The Book in Brief', 15, NULL, 'But on the following night she is at the canal at nine, and he must tell her that there is no letter and that her lover has not come. It destroys her last hope. She collapses into sobbing, calling three days of complete silence cruel and inhuman, and tormenting herself above all with the shame of it — that she was the one who went to him first, that she carried her bundle to his room, that she begged to be loved. She refuses the narrator''s offer to go to the man in her name, or to write again for her; she declares that she no longer knows him, no longer loves him, and will forget him. Then, in her grief, she asks the narrator whether he could ever have abandoned a girl who had bared her whole soul to him — and that question breaks his restraint.', '', NULL, NULL, NULL, NULL, 'white nights the book in brief', 'but on the following night she is at the canal at nine and he must tell her that there is no letter and that her lover has not come it destroys her last hope she collapses into sobbing calling three days of complete silence cruel and inhuman and tormenting herself above all with the shame of it that she was the one who went to him first that she carried her bundle to his room that she begged to be loved she refuses the narrators offer to go to the man in her name or to write again for her she declares that she no longer knows him no longer loves him and will forget him then in her grief she asks the narrator whether he could ever have abandoned a girl who had bared her whole soul to him and that question breaks his restraint', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'the book in brief', 'The Book in Brief', 16, NULL, 'He confesses that he loves her. He apologizes in advance for the absurdity of it and for the wretchedness of the moment he has chosen. And he insists that his love would never be a burden to her: he would love her so completely that even if she went on loving the other man, she would feel nothing from him but warmth, and the knowledge that there was someone alive whose whole occupation was her happiness.', '', NULL, NULL, NULL, NULL, 'white nights the book in brief', 'he confesses that he loves her he apologizes in advance for the absurdity of it and for the wretchedness of the moment he has chosen and he insists that his love would never be a burden to her he would love her so completely that even if she went on loving the other man she would feel nothing from him but warmth and the knowledge that there was someone alive whose whole occupation was her happiness', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'the book in brief', 'The Book in Brief', 17, NULL, 'She accepts him. She says she will get over the other, because that man mocked her while the narrator wept beside her; that she loves the narrator now because he is the nobler of the two. She reframes the whole year of waiting as possibly a childish delusion, born of a life shut up with her grandmother, and concludes that the man was never worthy of her at all. She gives him her hand and promises that her gratitude will grow into a love worthy of his.', '', NULL, NULL, NULL, NULL, 'white nights the book in brief', 'she accepts him she says she will get over the other because that man mocked her while the narrator wept beside her that she loves the narrator now because he is the nobler of the two she reframes the whole year of waiting as possibly a childish delusion born of a life shut up with her grandmother and concludes that the man was never worthy of her at all she gives him her hand and promises that her gratitude will grow into a love worthy of his', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'the book in brief', 'The Book in Brief', 18, NULL, 'What follows is the happiest passage of the narrator''s life and the shortest. They spend the night in a delirium of practical planning. He will move the very next day into the empty room on the top floor and become Granny''s lodger; they will bring Granny, and Matrona, and Fekla; Nastenka will give lessons; they will go to the theatre. For an hour or two the dreamer has a future made of ordinary furniture and ordinary people, which is exactly what he told her, on the second night, he would exchange every dream to obtain.', '', NULL, NULL, NULL, NULL, 'white nights the book in brief', 'what follows is the happiest passage of the narrators life and the shortest they spend the night in a delirium of practical planning he will move the very next day into the empty room on the top floor and become grannys lodger they will bring granny and matrona and fekla nastenka will give lessons they will go to the theatre for an hour or two the dreamer has a future made of ordinary furniture and ordinary people which is exactly what he told her on the second night he would exchange every dream to obtain', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'the book in brief', 'The Book in Brief', 19, NULL, 'Then, as he is walking her home, a figure appears in the street and calls her name. It is the lover. Nastenka tears herself out of the narrator''s arms and runs into his. Before she goes, she comes running back once more, to throw her arms round the narrator and kiss him warmly, in gratitude; and then she takes her lover''s hand and the two of them disappear into the night, leaving him standing where he stands, frozen and hollowed out.', '', NULL, NULL, NULL, NULL, 'white nights the book in brief', 'then as he is walking her home a figure appears in the street and calls her name it is the lover nastenka tears herself out of the narrators arms and runs into his before she goes she comes running back once more to throw her arms round the narrator and kiss him warmly in gratitude and then she takes her lovers hand and the two of them disappear into the night leaving him standing where he stands frozen and hollowed out', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'the book in brief', 'The Book in Brief', 20, NULL, 'In the morning the servant Matrona brings a letter, and he knows the handwriting at once. In it Nastenka begs his forgiveness. She admits that she deceived him and deceived herself equally, and that what passed between them was a dream. She tells him that she loves him still, and that she wishes she could love them both at once — echoing what she had said before, that she wished he had been the lodger. She explains why her heart went back so instantly: because it had never truly left, because it had always belonged to that man, and there was nothing in it for her to bring back to him. She announces that she is to be married next week, and she asks the narrator to remain her friend and her brother, and to come and meet them both.', '', NULL, NULL, NULL, NULL, 'white nights the book in brief', 'in the morning the servant matrona brings a letter and he knows the handwriting at once in it nastenka begs his forgiveness she admits that she deceived him and deceived herself equally and that what passed between them was a dream she tells him that she loves him still and that she wishes she could love them both at once echoing what she had said before that she wished he had been the lodger she explains why her heart went back so instantly because it had never truly left because it had always belonged to that man and there was nothing in it for her to bring back to him she announces that she is to be married next week and she asks the narrator to remain her friend and her brother and to come and meet them both', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'the book in brief', 'The Book in Brief', 21, NULL, 'Alone in his room, he has a vision of the years: Matrona grown old, the room and the house across the street darkened and decayed, the wallpaper faded — and himself, fifteen years on, unchanged and just as lonely as he is now. The dream of the top-floor room, of Granny and Fekla and the lessons and the theatre, is closed off, and what remains is precisely the fate he had described to Nastenka on the second night, when he confessed that he feared arriving at old age with nothing real behind him.', '', NULL, NULL, NULL, NULL, 'white nights the book in brief', 'alone in his room he has a vision of the years matrona grown old the room and the house across the street darkened and decayed the wallpaper faded and himself fifteen years on unchanged and just as lonely as he is now the dream of the top floor room of granny and fekla and the lessons and the theatre is closed off and what remains is precisely the fate he had described to nastenka on the second night when he confessed that he feared arriving at old age with nothing real behind him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'the book in brief', 'The Book in Brief', 22, NULL, 'And yet the ending does not fall where bitterness would put it. He refuses to blame her. He will not darken her happiness with reproach, or lay any weight of guilt upon her, or let a single bitter thought cross her sky; he wishes her clear skies and an untroubled joy, and he wishes it sincerely, without irony and without the concealed hope that she may one day regret. The story closes on the question he puts to himself instead: whether one whole moment of pure happiness is not enough for the entire life of a man. He does not argue the point. He simply leaves it standing, and the shape of his answer is plain — that it is enough, that it must be made enough, because for him it is all there is.', '', NULL, NULL, NULL, NULL, 'white nights the book in brief', 'and yet the ending does not fall where bitterness would put it he refuses to blame her he will not darken her happiness with reproach or lay any weight of guilt upon her or let a single bitter thought cross her sky he wishes her clear skies and an untroubled joy and he wishes it sincerely without irony and without the concealed hope that she may one day regret the story closes on the question he puts to himself instead whether one whole moment of pure happiness is not enough for the entire life of a man he does not argue the point he simply leaves it standing and the shape of his answer is plain that it is enough that it must be made enough because for him it is all there is', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'the book in brief', 'The Book in Brief', 23, NULL, 'What the story is built to carry is contained in that last exchange between wish and fact. The dreamer''s disease is that he has substituted imagination for living, and has grown rich inside and destitute outside; his cure, when it arrives, arrives in the person of a girl who is herself half a dreamer, made so by being pinned to an old woman''s dress. For four nights he is given the thing he had told her he would trade every fantasy to possess: a real person, imperfect, in real time, who needs him. But the reality is not his. Every warmth he receives is overflow, every service he performs — the dictated letter, the delivered envelope, the promise to go at daybreak for an answer — hastens the return of the man who will take her away. He is, throughout, the instrument of his own dispossession, and he acts as that instrument knowingly, out of kindness, which is the only thing in him that is not fantasy.', '', NULL, NULL, NULL, NULL, 'white nights the book in brief', 'what the story is built to carry is contained in that last exchange between wish and fact the dreamers disease is that he has substituted imagination for living and has grown rich inside and destitute outside his cure when it arrives arrives in the person of a girl who is herself half a dreamer made so by being pinned to an old womans dress for four nights he is given the thing he had told her he would trade every fantasy to possess a real person imperfect in real time who needs him but the reality is not his every warmth he receives is overflow every service he performs the dictated letter the delivered envelope the promise to go at daybreak for an answer hastens the return of the man who will take her away he is throughout the instrument of his own dispossession and he acts as that instrument knowingly out of kindness which is the only thing in him that is not fantasy', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'the book in brief', 'The Book in Brief', 24, NULL, 'Nastenka does not betray him in any ordinary sense. She says nothing untrue at the moment she says it. She sets her condition honestly at the start, that he must not fall in love with her; she warns him fairly that she likes him because he has not; and when she accepts him it is in good faith, and she is undone by her own heart rather than by any calculation. That is what makes the ending land as it does. There is no villain to blame, and therefore no consolation of blame. There is only the fact that a heart that has always belonged elsewhere will return there the instant it is called, and a man left standing in a street at night with the taste of a grateful kiss and a future dissolved.', '', NULL, NULL, NULL, NULL, 'white nights the book in brief', 'nastenka does not betray him in any ordinary sense she says nothing untrue at the moment she says it she sets her condition honestly at the start that he must not fall in love with her she warns him fairly that she likes him because he has not and when she accepts him it is in good faith and she is undone by her own heart rather than by any calculation that is what makes the ending land as it does there is no villain to blame and therefore no consolation of blame there is only the fact that a heart that has always belonged elsewhere will return there the instant it is called and a man left standing in a street at night with the taste of a grateful kiss and a future dissolved', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'the book in brief', 'The Book in Brief', 25, NULL, 'He had said, after two minutes of her company on the first night, that she had made him happy forever and had perhaps reconciled him with himself. The last page tests that sentence and, in its way, upholds it. He is not reconciled to his life, which he foresees will decay around him unchanged. But he is reconciled to her, and to the fact of having once been alive for a few nights, and he declines to spoil that fact by resenting it. A whole moment of happiness, offered against a lifetime — the dreamer, who has spent his years counting anniversaries of things that never happened, has finally acquired one that did.', '', NULL, NULL, NULL, NULL, 'white nights the book in brief', 'he had said after two minutes of her company on the first night that she had made him happy forever and had perhaps reconciled him with himself the last page tests that sentence and in its way upholds it he is not reconciled to his life which he foresees will decay around him unchanged but he is reconciled to her and to the fact of having once been alive for a few nights and he declines to spoil that fact by resenting it a whole moment of happiness offered against a lifetime the dreamer who has spent his years counting anniversaries of things that never happened has finally acquired one that did', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'introduction', 'Introduction', 1, NULL, 'White Nights is one of Fyodor Dostoyevsky''s most lyrical and tender works, a short story that captures the fragile beauty of human connection and the aching poignancy of solitude. First published in 1848, early in Dostoyevsky''s career, it belongs to a period before his more mature philosophical and psychological novels such as Crime and Punishment or The Brothers Karamazov. Yet, despite its brevity and relative simplicity, White Nights contains emotional and thematic depths that have made it one of his most beloved and enduring stories.', '', NULL, NULL, NULL, NULL, 'white nights introduction', 'white nights is one of fyodor dostoyevskys most lyrical and tender works a short story that captures the fragile beauty of human connection and the aching poignancy of solitude first published in 1848 early in dostoyevskys career it belongs to a period before his more mature philosophical and psychological novels such as crime and punishment or the brothers karamazov yet despite its brevity and relative simplicity white nights contains emotional and thematic depths that have made it one of his most beloved and enduring stories', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'introduction', 'Introduction', 2, NULL, 'Set in the magical twilight of a St. Petersburg summer, when the sun never fully sets and the nights are awash in a surreal silvery light, the story follows a solitary, unnamed narrator, a dreamer who wanders the empty streets at night. He lives more in his imagination than in the real world, finding comfort in fantasies and silent buildings, in poetry and ideas. But his quiet, repetitive life is interrupted when he meets Nastenka, a young woman weeping on a bench.', '', NULL, NULL, NULL, NULL, 'white nights introduction', 'set in the magical twilight of a st petersburg summer when the sun never fully sets and the nights are awash in a surreal silvery light the story follows a solitary unnamed narrator a dreamer who wanders the empty streets at night he lives more in his imagination than in the real world finding comfort in fantasies and silent buildings in poetry and ideas but his quiet repetitive life is interrupted when he meets nastenka a young woman weeping on a bench', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'introduction', 'Introduction', 3, NULL, 'Over the course of four nights and one morning, they share a brief, intense intimacy that changes them both. The story is not just a romantic interlude. It is an exploration of the human need to be seen, to be heard, to be loved. It is about the yearning for connection in a world that often feels cold and distant. Dostoyevsky, who himself was prone to melancholy and isolation, gives voice here to a character who longs not for glory or wealth, but simply for a moment of understanding.', '', NULL, NULL, NULL, NULL, 'white nights introduction', 'over the course of four nights and one morning they share a brief intense intimacy that changes them both the story is not just a romantic interlude it is an exploration of the human need to be seen to be heard to be loved it is about the yearning for connection in a world that often feels cold and distant dostoyevsky who himself was prone to melancholy and isolation gives voice here to a character who longs not for glory or wealth but simply for a moment of understanding', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'introduction', 'Introduction', 4, NULL, 'Through the dreamer''s confession, the reader is drawn into a soul that feels deeply and asks for very little, but finds that even a little can be everything. Unlike many of Dostoyevsky''s later characters, who are torn by guilt, ideology, and inner chaos, the narrator of White Nights is gentle, kind, and almost painfully innocent. He is a man untouched by cruelty, yet marked by the pain of being invisible.', '', NULL, NULL, NULL, NULL, 'white nights introduction', 'through the dreamers confession the reader is drawn into a soul that feels deeply and asks for very little but finds that even a little can be everything unlike many of dostoyevskys later characters who are torn by guilt ideology and inner chaos the narrator of white nights is gentle kind and almost painfully innocent he is a man untouched by cruelty yet marked by the pain of being invisible', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'introduction', 'Introduction', 5, NULL, 'His love for Nastenka is pure and unselfish, rooted not in desire but in a deep emotional bond. And that is what makes the story so moving. It is not about possession or fulfillment. It is about giving without expecting, loving without demanding, hoping even in the face of certain loss.', '', NULL, NULL, NULL, NULL, 'white nights introduction', 'his love for nastenka is pure and unselfish rooted not in desire but in a deep emotional bond and that is what makes the story so moving it is not about possession or fulfillment it is about giving without expecting loving without demanding hoping even in the face of certain loss', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'introduction', 'Introduction', 7, NULL, 'The setting of White Nights is more than just a backdrop.', '', NULL, NULL, NULL, NULL, 'white nights introduction', 'the setting of white nights is more than just a backdrop', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'introduction', 'Introduction', 8, NULL, 'It is a vital part of the story''s emotional atmosphere. The White Nights of St. Petersburg. Petersburg, those luminous summer evenings where night never fully arrives, mirror the dreamer''s emotional state, a space between darkness and light, between sleep and waking, between fantasy and reality. It is a time when ordinary life is suspended and something otherworldly seems possible. This luminous unreality is what makes the dreamer''s encounter with Nastenka feel so enchanted.', '', NULL, NULL, NULL, NULL, 'white nights introduction', 'it is a vital part of the storys emotional atmosphere the white nights of st petersburg petersburg those luminous summer evenings where night never fully arrives mirror the dreamers emotional state a space between darkness and light between sleep and waking between fantasy and reality it is a time when ordinary life is suspended and something otherworldly seems possible this luminous unreality is what makes the dreamers encounter with nastenka feel so enchanted', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'introduction', 'Introduction', 9, NULL, 'They meet not in daylight, where the world imposes its rules and expectations, but in this in-between space where hearts speak more freely. For four nights, they walk and talk, sharing their hopes and sorrows. The dreamer opens up in ways he never has before. He is not trying to impress or manipulate. He simply wants to be close to someone. Nastenka, too, is lonely and vulnerable. She tells him of her strict grandmother, her confined life, and the man she loves who promised to return but has not.', '', NULL, NULL, NULL, NULL, 'white nights introduction', 'they meet not in daylight where the world imposes its rules and expectations but in this in between space where hearts speak more freely for four nights they walk and talk sharing their hopes and sorrows the dreamer opens up in ways he never has before he is not trying to impress or manipulate he simply wants to be close to someone nastenka too is lonely and vulnerable she tells him of her strict grandmother her confined life and the man she loves who promised to return but has not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'introduction', 'Introduction', 10, NULL, 'Their connection is real, but fragile. They understand one another, yet they are not meant to last. The dreamer falls in love with Nastenka, but she is still in love with someone else. When her former lover returns, she goes to him, and the dreamer is left alone once more. But Dostoyevsky does not present this as a tragedy. There is sadness, yes, but also beauty. The dreamer has had his moment.', '', NULL, NULL, NULL, NULL, 'white nights introduction', 'their connection is real but fragile they understand one another yet they are not meant to last the dreamer falls in love with nastenka but she is still in love with someone else when her former lover returns she goes to him and the dreamer is left alone once more but dostoyevsky does not present this as a tragedy there is sadness yes but also beauty the dreamer has had his moment', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'introduction', 'Introduction', 11, NULL, 'He was seen. He was needed. He was loved, even if briefly. And for someone who has lived in the shadows, that is no small thing. His final words are not bitter, but full of gratitude. A whole moment of happiness. Is that too little for the whole of a man''s life? This line captures the spirit of White Nights. It is a story about fleeting joy, not because it is destined to vanish, but because its very ephemerality gives it meaning.', '', NULL, NULL, NULL, NULL, 'white nights introduction', 'he was seen he was needed he was loved even if briefly and for someone who has lived in the shadows that is no small thing his final words are not bitter but full of gratitude a whole moment of happiness is that too little for the whole of a mans life this line captures the spirit of white nights it is a story about fleeting joy not because it is destined to vanish but because its very ephemerality gives it meaning', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'introduction', 'Introduction', 12, NULL, 'The dreamer is not destroyed by disappointment. He returns to his solitude, but something in him has changed. He has touched another soul. He has known the light. This emotional nuance is part of what makes White Nights resonate so powerfully. In a world where love is often portrayed as dramatic, possessive, or transactional, Dostoyevsky offers a vision of love that is quiet, selfless, and tender. A love that expects nothing and gives everything.', '', NULL, NULL, NULL, NULL, 'white nights introduction', 'the dreamer is not destroyed by disappointment he returns to his solitude but something in him has changed he has touched another soul he has known the light this emotional nuance is part of what makes white nights resonate so powerfully in a world where love is often portrayed as dramatic possessive or transactional dostoyevsky offers a vision of love that is quiet selfless and tender a love that expects nothing and gives everything', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'introduction', 'Introduction', 13, NULL, 'A love that, though brief, illuminates a life.', '', NULL, NULL, NULL, NULL, 'white nights introduction', 'a love that though brief illuminates a life', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'introduction', 'Introduction', 15, NULL, 'White Nights is not just a love story. It is a portrait of the dreamer as an outsider. The narrator lives on the margins of life, observing others, constructing imaginary relationships, and yearning for a reality he cannot enter. He is not mentally ill, nor is he a social rebel. He is simply alone, painfully aware of his isolation, and yet he maintains a hopeful, even childlike heart.', '', NULL, NULL, NULL, NULL, 'white nights introduction', 'white nights is not just a love story it is a portrait of the dreamer as an outsider the narrator lives on the margins of life observing others constructing imaginary relationships and yearning for a reality he cannot enter he is not mentally ill nor is he a social rebel he is simply alone painfully aware of his isolation and yet he maintains a hopeful even childlike heart', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'introduction', 'Introduction', 16, NULL, 'This figure of the dreamer would evolve in Dostoyevsky''s later works into more complex, conflicted characters. Raskolnikov, the underground man, Prince Mishkin, Ivan Karamazov, all share with the dreamer a sense of dislocation, a struggle between inner vision and outer reality. But in White Nights, the dreamer is still innocent. He has not yet been hardened by suffering or drawn into philosophical rebellion. He still believes in the possibility of love, kindness, and simple human connection.', '', NULL, NULL, NULL, NULL, 'white nights introduction', 'this figure of the dreamer would evolve in dostoyevskys later works into more complex conflicted characters raskolnikov the underground man prince mishkin ivan karamazov all share with the dreamer a sense of dislocation a struggle between inner vision and outer reality but in white nights the dreamer is still innocent he has not yet been hardened by suffering or drawn into philosophical rebellion he still believes in the possibility of love kindness and simple human connection', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'introduction', 'Introduction', 17, NULL, 'What makes this story so valuable, especially within Dostoyevsky''s larger body of work, is its emotional purity. It shows the author in a more tender mode, unburdened by religious or political weight. There is no murder, no confession, no courtroom, no philosophical duel, just two people walking through twilight, trying to make sense of their hearts. And yet, the themes that would come to define Dostoyevsky''s writing are already present.', '', NULL, NULL, NULL, NULL, 'white nights introduction', 'what makes this story so valuable especially within dostoyevskys larger body of work is its emotional purity it shows the author in a more tender mode unburdened by religious or political weight there is no murder no confession no courtroom no philosophical duel just two people walking through twilight trying to make sense of their hearts and yet the themes that would come to define dostoyevskys writing are already present', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'introduction', 'Introduction', 18, NULL, 'The search for meaning, the pain of being unseen, the dignity of suffering, the paradox of joy and sadness coexisting. Even the idea of redemption, not through ideology or punishment, but through human connection, is here in its earliest, gentlest form. The form of the story, first-person narration, framed as a confession or letter to the reader, also anticipates Dostoyevsky''s later narrative techniques. The reader becomes a witness, not just to events, but to emotion.', '', NULL, NULL, NULL, NULL, 'white nights introduction', 'the search for meaning the pain of being unseen the dignity of suffering the paradox of joy and sadness coexisting even the idea of redemption not through ideology or punishment but through human connection is here in its earliest gentlest form the form of the story first person narration framed as a confession or letter to the reader also anticipates dostoyevskys later narrative techniques the reader becomes a witness not just to events but to emotion', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'introduction', 'Introduction', 19, NULL, 'We are not told what to think or feel. We are invited to listen, to empathize, to imagine ourselves in the dreamer''s shoes. White Nights also has a universal quality that transcends time and culture. Anyone who has ever felt invisible, who has longed for connection, who has experienced a brief, unforgettable love, will find themselves in these pages. It is a story about moments, about how the smallest encounter can echo through a lifetime, about how the heart, even when broken, can remain soft.', '', NULL, NULL, NULL, NULL, 'white nights introduction', 'we are not told what to think or feel we are invited to listen to empathize to imagine ourselves in the dreamers shoes white nights also has a universal quality that transcends time and culture anyone who has ever felt invisible who has longed for connection who has experienced a brief unforgettable love will find themselves in these pages it is a story about moments about how the smallest encounter can echo through a lifetime about how the heart even when broken can remain soft', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'introduction', 'Introduction', 20, NULL, 'As you begin reading White Nights, let yourself be drawn into its quiet world. Feel the stillness of the city, the glow of the sky, the hesitations and confessions of the characters. Let the story move slowly. It is not meant to shock or thrill. It is meant to make you feel gently, honestly, deeply. Welcome to White Nights, a tale for the lonely, the hopeful, the dreamers. A soft whisper in a sleepless night, a reminder that even the briefest connection can light up the soul.', '', NULL, NULL, NULL, NULL, 'white nights introduction', 'as you begin reading white nights let yourself be drawn into its quiet world feel the stillness of the city the glow of the sky the hesitations and confessions of the characters let the story move slowly it is not meant to shock or thrill it is meant to make you feel gently honestly deeply welcome to white nights a tale for the lonely the hopeful the dreamers a soft whisper in a sleepless night a reminder that even the briefest connection can light up the soul', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'first night', 'First Night', 0, NULL, 'It was a beautiful night, the kind of night that only feels possible when we are young, dear reader. The sky was full of stars, so bright and endless that, as I looked at it, I couldn''t help but wonder how grumpy or moody people could live under such a sky. That''s a very youthful thought too, dear reader, so youthful. But may God grant that such thoughts enter your heart more often.', '', NULL, NULL, NULL, NULL, 'white nights first night', 'it was a beautiful night the kind of night that only feels possible when we are young dear reader the sky was full of stars so bright and endless that as i looked at it i couldnt help but wonder how grumpy or moody people could live under such a sky thats a very youthful thought too dear reader so youthful but may god grant that such thoughts enter your heart more often', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'first night', 'First Night', 1, NULL, 'Speaking of grumpy and moody people, I can''t help but think about how I felt all day. From the moment I woke up a strange sadness weighed on me. I couldn''t shake the feeling that I was completely alone, that everyone was leaving me behind. Of course, you might ask, who is this everyone you''re talking about? After all, I had lived in Petersburg for almost eight years and barely knew anyone.', '', NULL, NULL, NULL, NULL, 'white nights first night', 'speaking of grumpy and moody people i cant help but think about how i felt all day from the moment i woke up a strange sadness weighed on me i couldnt shake the feeling that i was completely alone that everyone was leaving me behind of course you might ask who is this everyone youre talking about after all i had lived in petersburg for almost eight years and barely knew anyone', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'first night', 'First Night', 2, NULL, 'But what did I need acquaintances for? I already felt like I knew all of Petersburg. That''s why, when everyone in Petersburg seemed to pack their things and move to their summer homes, it felt like they were all leaving me. The thought of being left behind scared me, and for three whole days I wandered the city feeling down, unsure of what to do with myself. Whether I walked along Nevsky Prospekt, visited the gardens, or strolled by the river bank, I didn''t see a single familiar face.', '', NULL, NULL, NULL, NULL, 'white nights first night', 'but what did i need acquaintances for i already felt like i knew all of petersburg thats why when everyone in petersburg seemed to pack their things and move to their summer homes it felt like they were all leaving me the thought of being left behind scared me and for three whole days i wandered the city feeling down unsure of what to do with myself whether i walked along nevsky prospekt visited the gardens or strolled by the river bank i didnt see a single familiar face', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'first night', 'First Night', 3, NULL, 'Those people didn''t know me, of course, but I knew them. I knew them so well that it felt like I had studied their faces. Their happiness made me happy, and their gloom brought me down. I even felt as though I had formed a sort of bond with one old man I saw every single day at the same time on Fontanka. He had a serious, thoughtful expression, and he always mumbled to himself while waving his left hand.', '', NULL, NULL, NULL, NULL, 'white nights first night', 'those people didnt know me of course but i knew them i knew them so well that it felt like i had studied their faces their happiness made me happy and their gloom brought me down i even felt as though i had formed a sort of bond with one old man i saw every single day at the same time on fontanka he had a serious thoughtful expression and he always mumbled to himself while waving his left hand', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'first night', 'First Night', 4, NULL, 'In his right hand he carried a long, knobby stick with a gold handle. He even seemed to notice me and care about me in his own way. If I wasn''t at my usual spot on Fontanka, I was sure he felt disappointed. Over time we almost started nodding to each other in greeting, especially when we were both in good spirits. Just the other day, after missing each other for two days, we nearly tipped our hats as we passed, but we caught ourselves just in time and simply exchanged curious glances.', '', NULL, NULL, NULL, NULL, 'white nights first night', 'in his right hand he carried a long knobby stick with a gold handle he even seemed to notice me and care about me in his own way if i wasnt at my usual spot on fontanka i was sure he felt disappointed over time we almost started nodding to each other in greeting especially when we were both in good spirits just the other day after missing each other for two days we nearly tipped our hats as we passed but we caught ourselves just in time and simply exchanged curious glances', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'first night', 'First Night', 5, NULL, 'I know the buildings in Petersburg too. As I walk down the streets, it feels like the buildings lean forward, peeking out their windows to greet me. Some of them seem to say, Good morning. How are you? I''m doing well, thank you, and I''ll be getting a new floor added in May. Others might say, I''m being repainted tomorrow, or I narrowly escaped a fire and was so frightened.', '', NULL, NULL, NULL, NULL, 'white nights first night', 'i know the buildings in petersburg too as i walk down the streets it feels like the buildings lean forward peeking out their windows to greet me some of them seem to say good morning how are you im doing well thank you and ill be getting a new floor added in may others might say im being repainted tomorrow or i narrowly escaped a fire and was so frightened', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'first night', 'First Night', 6, NULL, 'I even have favorites among the buildings. Some of them feel like old friends. One building plans to undergo some renovations by the architect this summer, and I''ll make a point of visiting daily to ensure the work goes well. Heaven forbid anything goes wrong. But I''ll never forget what happened with a small, charming house that used to be a lovely shade of pink. It was such a delightful little brick house.', '', NULL, NULL, NULL, NULL, 'white nights first night', 'i even have favorites among the buildings some of them feel like old friends one building plans to undergo some renovations by the architect this summer and ill make a point of visiting daily to ensure the work goes well heaven forbid anything goes wrong but ill never forget what happened with a small charming house that used to be a lovely shade of pink it was such a delightful little brick house', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'first night', 'First Night', 7, NULL, 'It stood proudly among its plain neighbors, and seeing it always lifted my spirits. Then one day last week I passed by, and it seemed to cry out to me, They''re painting me yellow! I was horrified. Those barbarians! They didn''t spare a single detail, not the columns, not the cornices. My poor little friend was as yellow as a canary. It made me feel sick. Even now I can''t bring myself to visit that house, now ruined by its awful new color.', '', NULL, NULL, NULL, NULL, 'white nights first night', 'it stood proudly among its plain neighbors and seeing it always lifted my spirits then one day last week i passed by and it seemed to cry out to me theyre painting me yellow i was horrified those barbarians they didnt spare a single detail not the columns not the cornices my poor little friend was as yellow as a canary it made me feel sick even now i cant bring myself to visit that house now ruined by its awful new color', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'first night', 'First Night', 8, NULL, 'So now you understand, dear reader, how I feel connected to all of Petersburg. I already mentioned that I had been feeling uneasy for three whole days before I finally realized what was bothering me. I felt restless on the streets. This person was gone. That one was gone. And what had happened to the other? Even at home I didn''t feel like myself. For two nights I racked my brain trying to figure out what was wrong in my little corner.', '', NULL, NULL, NULL, NULL, 'white nights first night', 'so now you understand dear reader how i feel connected to all of petersburg i already mentioned that i had been feeling uneasy for three whole days before i finally realized what was bothering me i felt restless on the streets this person was gone that one was gone and what had happened to the other even at home i didnt feel like myself for two nights i racked my brain trying to figure out what was wrong in my little corner', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'first night', 'First Night', 9, NULL, 'Why was it so uncomfortable all of a sudden? In my confusion I carefully inspected the dingy green walls, the ceiling covered in cobwebs that Matrona had allowed to flourish, and all my furniture. I checked every chair, wondering if the issue was with them, because if even one chair isn''t in the same spot as the day before, I feel unsettled. I even studied the window, but none of it helped.', '', NULL, NULL, NULL, NULL, 'white nights first night', 'why was it so uncomfortable all of a sudden in my confusion i carefully inspected the dingy green walls the ceiling covered in cobwebs that matrona had allowed to flourish and all my furniture i checked every chair wondering if the issue was with them because if even one chair isnt in the same spot as the day before i feel unsettled i even studied the window but none of it helped', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'first night', 'First Night', 10, NULL, 'Nothing felt better. I thought about calling Matrona to talk about the cobwebs and her general carelessness, but when I finally did, she just stared at me in silence, clearly baffled, and left without saying a word. The cobwebs, of course, are still hanging there, undisturbed. It wasn''t until this morning that I finally figured it out. Ah, everyone is leaving for their summer homes. Excuse the simplicity of my words, but I''m not in the mood for fancy language right now.', '', NULL, NULL, NULL, NULL, 'white nights first night', 'nothing felt better i thought about calling matrona to talk about the cobwebs and her general carelessness but when i finally did she just stared at me in silence clearly baffled and left without saying a word the cobwebs of course are still hanging there undisturbed it wasnt until this morning that i finally figured it out ah everyone is leaving for their summer homes excuse the simplicity of my words but im not in the mood for fancy language right now', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'first night', 'First Night', 11, NULL, 'Everything and everyone in Petersburg had either left or was preparing to leave for the holidays. Every respectable-looking gentleman I saw taking a cab seemed to transform in my mind into a devoted head of the household on his way to join his family at a summer villa. Every passerby seemed to carry an air of transition, as if to say to the world, I''m only here for a little while longer, and soon I''ll be off to the summer villa.', '', NULL, NULL, NULL, NULL, 'white nights first night', 'everything and everyone in petersburg had either left or was preparing to leave for the holidays every respectable looking gentleman i saw taking a cab seemed to transform in my mind into a devoted head of the household on his way to join his family at a summer villa every passerby seemed to carry an air of transition as if to say to the world im only here for a little while longer and soon ill be off to the summer villa', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'first night', 'First Night', 12, NULL, 'If a window opened and a pair of delicate snow-white fingers tapped on the glass, before a pretty young woman leaned out to call to a flower-seller, I immediately imagined the flowers weren''t for her stuffy apartment, but for the countryside, where she would soon be moving. I became so caught up in my new obsession that I began to feel I could tell, just by looking at people, which summer villa they were heading to.', '', NULL, NULL, NULL, NULL, 'white nights first night', 'if a window opened and a pair of delicate snow white fingers tapped on the glass before a pretty young woman leaned out to call to a flower seller i immediately imagined the flowers werent for her stuffy apartment but for the countryside where she would soon be moving i became so caught up in my new obsession that i began to feel i could tell just by looking at people which summer villa they were heading to', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'first night', 'First Night', 13, NULL, 'Those going to Kameny or Aptokarsky Islands or the Peterhof Road stood out with their polished manners, stylish summer outfits, and elegant carriages. Those bound for Pargolovo or more distant places had a calm and dignified air. Meanwhile, people heading to Krestovsky Island were unmistakable with their carefree, lively energy. If I happened to see a long line of carts carrying heaps of furniture—tables, chairs, sofas, and all sorts of household items—often with an old cook perched on top of it all, fiercely guarding her employer''s belongings, or boats loaded with goods slowly gliding along the Neva or Fontanka on their way to the Black River or the Islands, it felt as though these scenes were everywhere.', '', NULL, NULL, NULL, NULL, 'white nights first night', 'those going to kameny or aptokarsky islands or the peterhof road stood out with their polished manners stylish summer outfits and elegant carriages those bound for pargolovo or more distant places had a calm and dignified air meanwhile people heading to krestovsky island were unmistakable with their carefree lively energy if i happened to see a long line of carts carrying heaps of furniture tables chairs sofas and all sorts of household items often with an old cook perched on top of it all fiercely guarding her employers belongings or boats loaded with goods slowly gliding along the neva or fontanka on their way to the black river or the islands it felt as though these scenes were everywhere', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'first night', 'First Night', 14, NULL, 'In my mind I multiplied these wagons and boats tenfold, a hundredfold. It seemed like the whole city was moving in caravans to summer villas. It felt as if Petersburg was on the verge of becoming a ghost town. I started to feel embarrassed, frustrated, and deeply sad that I had no place to go for the holidays and no reason to leave the city. I wanted to join every wagon, ride off with every dignified gentleman in a cab, but no one, not a single person, invited me.', '', NULL, NULL, NULL, NULL, 'white nights first night', 'in my mind i multiplied these wagons and boats tenfold a hundredfold it seemed like the whole city was moving in caravans to summer villas it felt as if petersburg was on the verge of becoming a ghost town i started to feel embarrassed frustrated and deeply sad that i had no place to go for the holidays and no reason to leave the city i wanted to join every wagon ride off with every dignified gentleman in a cab but no one not a single person invited me', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'first night', 'First Night', 15, NULL, 'It was as if they had all forgotten about me entirely, as if I didn''t belong to their world at all. I went on long walks, often so lost in thought that I forgot where I was until I suddenly found myself at the city gates. As soon as I realized where I was, I felt a wave of relief. I crossed the boundary and walked through fields and meadows.', '', NULL, NULL, NULL, NULL, 'white nights first night', 'it was as if they had all forgotten about me entirely as if i didnt belong to their world at all i went on long walks often so lost in thought that i forgot where i was until i suddenly found myself at the city gates as soon as i realized where i was i felt a wave of relief i crossed the boundary and walked through fields and meadows', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'first night', 'First Night', 16, NULL, 'I didn''t feel tired at all, only as though a heavy weight had been lifted from my heart. Everyone I passed looked at me with such kind expressions that it felt like they were silently greeting me. They all seemed so cheerful, as if something wonderful had just happened, and nearly all of them were smoking cigars. Their happiness made me feel a joy I hadn''t known before. It felt almost as if I had been transported to Italy.', '', NULL, NULL, NULL, NULL, 'white nights first night', 'i didnt feel tired at all only as though a heavy weight had been lifted from my heart everyone i passed looked at me with such kind expressions that it felt like they were silently greeting me they all seemed so cheerful as if something wonderful had just happened and nearly all of them were smoking cigars their happiness made me feel a joy i hadnt known before it felt almost as if i had been transported to italy', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'first night', 'First Night', 17, NULL, 'So powerful was the effect of nature on someone like me, a half-sick city dweller, suffocating within the walls of the town. There is something incredibly moving about the nature around Petersburg. Especially in early spring, when it seems to use every ounce of strength it has. It bursts into bloom, covers itself in green leaves, and sprinkles itself with flowers, as if putting on its finest attire. It reminds me of a delicate, sickly girl, the kind you might look at with pity or tenderness, or perhaps not notice at all.', '', NULL, NULL, NULL, NULL, 'white nights first night', 'so powerful was the effect of nature on someone like me a half sick city dweller suffocating within the walls of the town there is something incredibly moving about the nature around petersburg especially in early spring when it seems to use every ounce of strength it has it bursts into bloom covers itself in green leaves and sprinkles itself with flowers as if putting on its finest attire it reminds me of a delicate sickly girl the kind you might look at with pity or tenderness or perhaps not notice at all', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'first night', 'First Night', 18, NULL, 'Then, out of nowhere, she becomes breathtakingly beautiful, almost as if by accident. Her sad, thoughtful eyes suddenly glow with fire, her pale cheeks flush with color, her features soften, and her face fills with passion and life. Her smile becomes radiant, her laughter sparkles, and her beauty overwhelms you. It''s impossible not to wonder what caused this transformation. What gave her such vitality, such life? What brought that glow to her face and made her movements so full of grace?', '', NULL, NULL, NULL, NULL, 'white nights first night', 'then out of nowhere she becomes breathtakingly beautiful almost as if by accident her sad thoughtful eyes suddenly glow with fire her pale cheeks flush with color her features soften and her face fills with passion and life her smile becomes radiant her laughter sparkles and her beauty overwhelms you its impossible not to wonder what caused this transformation what gave her such vitality such life what brought that glow to her face and made her movements so full of grace', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'first night', 'First Night', 19, NULL, 'But then the moment vanishes. The next day you might see her again, but she''s back to the way she was before, quiet, pale, and distant, with a look of sorrow in her eyes. You can even sense regret or anguish in her expression, as if she''s mourning the brief, fleeting moment of beauty she allowed herself. And you feel sad too, heartbroken that her beauty disappeared so quickly, that it came and went like a passing dream.', '', NULL, NULL, NULL, NULL, 'white nights first night', 'but then the moment vanishes the next day you might see her again but shes back to the way she was before quiet pale and distant with a look of sorrow in her eyes you can even sense regret or anguish in her expression as if shes mourning the brief fleeting moment of beauty she allowed herself and you feel sad too heartbroken that her beauty disappeared so quickly that it came and went like a passing dream', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'first night', 'First Night', 20, NULL, 'You grieve because it felt like you didn''t even have enough time to fully appreciate it, to truly love her. And yet, as beautiful as that day was, the night that followed was even better. Here''s what happened. I returned to the city very late, and it was already ten o''clock by the time I was heading back to my lodging. My path took me along the canal embankment, a place where, at that hour, you never see a single person.', '', NULL, NULL, NULL, NULL, 'white nights first night', 'you grieve because it felt like you didnt even have enough time to fully appreciate it to truly love her and yet as beautiful as that day was the night that followed was even better heres what happened i returned to the city very late and it was already ten oclock by the time i was heading back to my lodging my path took me along the canal embankment a place where at that hour you never see a single person', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'first night', 'First Night', 21, NULL, 'To be fair, I live in a very isolated part of the city. I walked along, humming a song. When I''m happy, I always hum to myself, like anyone who''s joyful but has no one to share that happiness with. Then, out of nowhere, something completely unexpected happened. Leaning against the canal railing stood a woman, her elbows resting on the rail, as she stared intently at the murky water below.', '', NULL, NULL, NULL, NULL, 'white nights first night', 'to be fair i live in a very isolated part of the city i walked along humming a song when im happy i always hum to myself like anyone whos joyful but has no one to share that happiness with then out of nowhere something completely unexpected happened leaning against the canal railing stood a woman her elbows resting on the rail as she stared intently at the murky water below', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'first night', 'First Night', 22, NULL, 'She wore a lovely yellow hat and a stylish black shawl. She''s young, and I bet she has dark hair, I thought. She didn''t seem to notice the sound of my footsteps or react in any way as I walked past her, my heart pounding loudly in my chest. How odd, I thought. She must be lost in her thoughts. Then, suddenly, I stopped in my tracks, frozen. I heard a soft, muffled sob.', '', NULL, NULL, NULL, NULL, 'white nights first night', 'she wore a lovely yellow hat and a stylish black shawl shes young and i bet she has dark hair i thought she didnt seem to notice the sound of my footsteps or react in any way as i walked past her my heart pounding loudly in my chest how odd i thought she must be lost in her thoughts then suddenly i stopped in my tracks frozen i heard a soft muffled sob', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'first night', 'First Night', 23, NULL, 'Yes, there was no mistaking it. The woman was crying. A moment later, the quiet sobs became louder, one after another. My heart sank. Though I was usually nervous around women, this was different. It felt like an extraordinary moment. I turned back, took a step toward her, and was just about to say, Miss, but stopped myself, realizing how cliche it sounded, like something out of every Russian novel I''d ever read.', '', NULL, NULL, NULL, NULL, 'white nights first night', 'yes there was no mistaking it the woman was crying a moment later the quiet sobs became louder one after another my heart sank though i was usually nervous around women this was different it felt like an extraordinary moment i turned back took a step toward her and was just about to say miss but stopped myself realizing how cliche it sounded like something out of every russian novel id ever read', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'first night', 'First Night', 24, NULL, 'That thought alone made me hesitate. As I fumbled for the right words, she seemed to collect herself. She turned her head slightly, noticed me, started, and quickly looked down. Without a word, she moved past me and began walking along the embankment. Instinctively, I followed her. She must have realized it because she veered off the embankment, crossed the street, and continued along the pavement. I didn''t dare cross after her, my heart beating wildly like a trapped bird.', '', NULL, NULL, NULL, NULL, 'white nights first night', 'that thought alone made me hesitate as i fumbled for the right words she seemed to collect herself she turned her head slightly noticed me started and quickly looked down without a word she moved past me and began walking along the embankment instinctively i followed her she must have realized it because she veered off the embankment crossed the street and continued along the pavement i didnt dare cross after her my heart beating wildly like a trapped bird', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'first night', 'First Night', 25, NULL, 'Then fate seemed to step in and offer me a chance. On the same side of the pavement where she was walking, a man suddenly appeared. He was wearing evening clothes and looked to be middle-aged, though his unsteady gait and the way he leaned against the wall made him seem less than dignified. The woman quickened her pace, walking with the nervous urgency you see in women who want to avoid being approached at night.', '', NULL, NULL, NULL, NULL, 'white nights first night', 'then fate seemed to step in and offer me a chance on the same side of the pavement where she was walking a man suddenly appeared he was wearing evening clothes and looked to be middle aged though his unsteady gait and the way he leaned against the wall made him seem less than dignified the woman quickened her pace walking with the nervous urgency you see in women who want to avoid being approached at night', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'first night', 'First Night', 26, NULL, 'It seemed likely the staggering man wouldn''t follow her, except, unfortunately, he did. Without any warning, the man sprang forward and began chasing her at full speed. She ran like the wind, but he was catching up, getting closer and closer. She let out a sharp scream, and in that instant I silently thanked the sturdy walking stick I happened to be carrying in my right hand. In a heartbeat I crossed the street, and in another the drunken man seemed to understand the situation.', '', NULL, NULL, NULL, NULL, 'white nights first night', 'it seemed likely the staggering man wouldnt follow her except unfortunately he did without any warning the man sprang forward and began chasing her at full speed she ran like the wind but he was catching up getting closer and closer she let out a sharp scream and in that instant i silently thanked the sturdy walking stick i happened to be carrying in my right hand in a heartbeat i crossed the street and in another the drunken man seemed to understand the situation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'first night', 'First Night', 27, NULL, 'He noticed my stick, recognized the unspoken thread it carried, and immediately backed off without saying a word. Only when we were far down the road did I hear him muttering curses in our direction, but his voice was too faint to make out. Take my arm, I said to the woman. He won''t bother us any more. She hesitated for only a moment before linking her trembling arm with mine.', '', NULL, NULL, NULL, NULL, 'white nights first night', 'he noticed my stick recognized the unspoken thread it carried and immediately backed off without saying a word only when we were far down the road did i hear him muttering curses in our direction but his voice was too faint to make out take my arm i said to the woman he wont bother us any more she hesitated for only a moment before linking her trembling arm with mine', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'first night', 'First Night', 28, NULL, 'She was still shaking, overwhelmed by fear and excitement. Oh, drunken stranger, how I silently thanked you in that moment! I glanced at her out of the corner of my eye and saw that she was even more beautiful than I had guessed, dark-haired, just as I''d imagined. Her long, dark lashes were still wet with tears, though I couldn''t tell if they were from the terror she had just experienced or from whatever had made her cry earlier.', '', NULL, NULL, NULL, NULL, 'white nights first night', 'she was still shaking overwhelmed by fear and excitement oh drunken stranger how i silently thanked you in that moment i glanced at her out of the corner of my eye and saw that she was even more beautiful than i had guessed dark haired just as id imagined her long dark lashes were still wet with tears though i couldnt tell if they were from the terror she had just experienced or from whatever had made her cry earlier', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'first night', 'First Night', 29, NULL, 'Yet a faint smile was beginning to form on her lips. She, too, stole a quick glance at me, her cheeks turning a soft pink before she lowered her gaze again. You see, I said gently, why did you push me away earlier? If I''d been there, this never would have happened. But I didn''t know you, she replied quietly. I thought you might have been like him. And now?', '', NULL, NULL, NULL, NULL, 'white nights first night', 'yet a faint smile was beginning to form on her lips she too stole a quick glance at me her cheeks turning a soft pink before she lowered her gaze again you see i said gently why did you push me away earlier if id been there this never would have happened but i didnt know you she replied quietly i thought you might have been like him and now', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'first night', 'First Night', 30, NULL, 'Do you think you know me better? Maybe a little, she said, still looking down. But why are you shaking? Oh, you''ve guessed it right away, I replied, thrilled that this girl was so clever. Intelligence always goes so well with beauty. Yes, from the very first look you figured me out completely. You''re right, I''m shy around women. I get nervous just like you did a moment ago when that man scared you.', '', NULL, NULL, NULL, NULL, 'white nights first night', 'do you think you know me better maybe a little she said still looking down but why are you shaking oh youve guessed it right away i replied thrilled that this girl was so clever intelligence always goes so well with beauty yes from the very first look you figured me out completely youre right im shy around women i get nervous just like you did a moment ago when that man scared you', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'first night', 'First Night', 31, NULL, 'To be honest, I''m a little nervous now. This feels like a dream. And I never imagined, even in my wildest dreams, that I''d ever have a real conversation with a woman. What? Really? Yes, really. If my arm is trembling, it''s because it has never been held by a small, lovely hand like yours before. I''ve never had much to do with women. You see, I''m always alone. I don''t even know how to talk to them properly.', '', NULL, NULL, NULL, NULL, 'white nights first night', 'to be honest im a little nervous now this feels like a dream and i never imagined even in my wildest dreams that id ever have a real conversation with a woman what really yes really if my arm is trembling its because it has never been held by a small lovely hand like yours before ive never had much to do with women you see im always alone i dont even know how to talk to them properly', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'first night', 'First Night', 32, NULL, 'In fact, I''m not sure if I''ve already said something foolish to you. Be honest with me. Please tell me if I have. I promise I won''t be offended. No, no, not at all. Quite the opposite. And if you really want me to be honest, I''ll tell you that women actually like that kind of nervousness. And to be even more honest, I like it too. I won''t send you away until I''ve made it home safely.', '', NULL, NULL, NULL, NULL, 'white nights first night', 'in fact im not sure if ive already said something foolish to you be honest with me please tell me if i have i promise i wont be offended no no not at all quite the opposite and if you really want me to be honest ill tell you that women actually like that kind of nervousness and to be even more honest i like it too i wont send you away until ive made it home safely', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'first night', 'First Night', 33, NULL, 'You''re going to make me lose all my shyness, I said, almost breathless with happiness. And once that happens, all my chances will be gone. Chances? What chances? That''s not a very nice thing to say. I''m sorry it just slipped out, but how can anyone not want to make a good impression at a moment like this? You mean to be liked, right? Yes, exactly. But please be kind to me.', '', NULL, NULL, NULL, NULL, 'white nights first night', 'youre going to make me lose all my shyness i said almost breathless with happiness and once that happens all my chances will be gone chances what chances thats not a very nice thing to say im sorry it just slipped out but how can anyone not want to make a good impression at a moment like this you mean to be liked right yes exactly but please be kind to me', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'first night', 'First Night', 34, NULL, 'Think about who I am. I''m twenty-six years old, and I''ve never known anyone like you. How can I possibly say the right things or be smooth and confident? Maybe you''ll understand better if I just tell you everything. I don''t know how to keep quiet when my heart is speaking, but never mind all that. Believe me, I''ve never been with a woman, not even once. No friendships, no relationships, nothing.', '', NULL, NULL, NULL, NULL, 'white nights first night', 'think about who i am im twenty six years old and ive never known anyone like you how can i possibly say the right things or be smooth and confident maybe youll understand better if i just tell you everything i dont know how to keep quiet when my heart is speaking but never mind all that believe me ive never been with a woman not even once no friendships no relationships nothing', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'first night', 'First Night', 35, NULL, 'Every day I just dream about finally meeting someone. Oh, if only you knew how many times I''ve fallen in love in my dreams. Really? With who? With no one in particular, with an ideal, with a person I imagine in my dreams. I make up entire stories in my head. You don''t know me at all. Of course, I''ve met a few women before, but what kind of women were they?', '', NULL, NULL, NULL, NULL, 'white nights first night', 'every day i just dream about finally meeting someone oh if only you knew how many times ive fallen in love in my dreams really with who with no one in particular with an ideal with a person i imagine in my dreams i make up entire stories in my head you dont know me at all of course ive met a few women before but what kind of women were they', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'first night', 'First Night', 36, NULL, 'They were all landladies, people like that, but I''m sure you''ll laugh if I tell you this. I''ve even thought about speaking to some elegant woman on the street a few times. Of course, only if she was alone. I imagined myself approaching her timidly and respectfully, explaining how lonely I am, begging her not to turn me away. I''d tell her that I don''t have any opportunities to meet women, and that it''s almost a moral duty for her not to reject such a desperate request.', '', NULL, NULL, NULL, NULL, 'white nights first night', 'they were all landladies people like that but im sure youll laugh if i tell you this ive even thought about speaking to some elegant woman on the street a few times of course only if she was alone i imagined myself approaching her timidly and respectfully explaining how lonely i am begging her not to turn me away id tell her that i dont have any opportunities to meet women and that its almost a moral duty for her not to reject such a desperate request', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'first night', 'First Night', 37, NULL, 'I''d ask her to say just a few kind words to me, as if she were my sister. I wouldn''t ask for much, just two or three words of sympathy. She could laugh at me if she wanted to, but I''d hope she wouldn''t reject me outright. Even if we never saw each other again, just those few words would mean so much. But you''re laughing now, and that''s exactly why I''m telling you all this.', '', NULL, NULL, NULL, NULL, 'white nights first night', 'id ask her to say just a few kind words to me as if she were my sister i wouldnt ask for much just two or three words of sympathy she could laugh at me if she wanted to but id hope she wouldnt reject me outright even if we never saw each other again just those few words would mean so much but youre laughing now and thats exactly why im telling you all this', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'first night', 'First Night', 38, NULL, 'Don''t be upset. I''m only laughing at how you''re your own worst enemy. If you had tried, you might have succeeded, even if it had been on the street. Simplicity is best. No kind-hearted woman, unless she were either foolish or in a bad mood at the time, could turn you away without those two little words you''re so shy to ask for. But wait, what am I saying? Of course, she might think you''re crazy.', '', NULL, NULL, NULL, NULL, 'white nights first night', 'dont be upset im only laughing at how youre your own worst enemy if you had tried you might have succeeded even if it had been on the street simplicity is best no kind hearted woman unless she were either foolish or in a bad mood at the time could turn you away without those two little words youre so shy to ask for but wait what am i saying of course she might think youre crazy', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'first night', 'First Night', 39, NULL, 'I was judging by myself. I know quite a bit about other people''s lives. Oh, thank you, I exclaimed. You don''t know what you''ve just done for me? I''m glad, I''m so glad. But tell me, how did you know I was the kind of woman who—well, someone you''d think worthy—of your attention and friendship? Not just a landlady, as you say? What made you decide to approach me? What made me?', '', NULL, NULL, NULL, NULL, 'white nights first night', 'i was judging by myself i know quite a bit about other peoples lives oh thank you i exclaimed you dont know what youve just done for me im glad im so glad but tell me how did you know i was the kind of woman who well someone youd think worthy of your attention and friendship not just a landlady as you say what made you decide to approach me what made me', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'first night', 'First Night', 40, NULL, 'Well, you were alone. That man was being far too rude. And it was night-time. You have to admit, it felt like my duty. No, no, I mean before, when you were on the other side of the canal. You know you were planning to come up to me. The other side? Honestly, I don''t know how to answer. I''m afraid to say. Do you know I''ve been happy today?', '', NULL, NULL, NULL, NULL, 'white nights first night', 'well you were alone that man was being far too rude and it was night time you have to admit it felt like my duty no no i mean before when you were on the other side of the canal you know you were planning to come up to me the other side honestly i dont know how to answer im afraid to say do you know ive been happy today', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'first night', 'First Night', 41, NULL, 'I walked around singing. I went out into the countryside. I''ve never felt moments like that before. You—perhaps I imagined it. Forgive me for saying this, but I thought you were crying, and I couldn''t bear it. It hurt my heart. Surely it''s okay that I was concerned for you. Surely there''s no harm in feeling a kind of brotherly compassion for someone? I''m sorry, I said compassion. But really, is it wrong for me to have felt such a strong urge to approach you?', '', NULL, NULL, NULL, NULL, 'white nights first night', 'i walked around singing i went out into the countryside ive never felt moments like that before you perhaps i imagined it forgive me for saying this but i thought you were crying and i couldnt bear it it hurt my heart surely its okay that i was concerned for you surely theres no harm in feeling a kind of brotherly compassion for someone im sorry i said compassion but really is it wrong for me to have felt such a strong urge to approach you', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'first night', 'First Night', 42, NULL, 'Stop, that''s enough. Don''t say any more, she said, looking down and pressing my hand. It''s my fault for bringing it up. But I''m glad I wasn''t wrong about you. And now, here I am at home. I must turn down this street. It''s just a few steps from here. Goodbye, and thank you. Surely, surely you don''t mean that we''ll never see each other again? This can''t be the end, can it?', '', NULL, NULL, NULL, NULL, 'white nights first night', 'stop thats enough dont say any more she said looking down and pressing my hand its my fault for bringing it up but im glad i wasnt wrong about you and now here i am at home i must turn down this street its just a few steps from here goodbye and thank you surely surely you dont mean that well never see each other again this cant be the end can it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'first night', 'First Night', 43, NULL, 'You see, she said, laughing. At first, you only wanted two words. And now—well, I won''t say anything. Maybe we''ll meet again. I''ll come here tomorrow, I said. Oh, forgive me. I''m already making demands. Yes, you''re not very patient. You''re almost insisting. Listen, please, listen, I interrupted her. Forgive me for saying this, but I have to tell you something else. I can''t stop myself from coming back here tomorrow.', '', NULL, NULL, NULL, NULL, 'white nights first night', 'you see she said laughing at first you only wanted two words and now well i wont say anything maybe well meet again ill come here tomorrow i said oh forgive me im already making demands yes youre not very patient youre almost insisting listen please listen i interrupted her forgive me for saying this but i have to tell you something else i cant stop myself from coming back here tomorrow', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'first night', 'First Night', 44, NULL, 'I''m a dreamer. My real life is so empty that moments like this are rare treasures for me. I hold on to them and relive them in my dreams. I''ll be dreaming of you all night, all week, maybe all year. I''ll definitely come back here tomorrow, to this very spot, at the same time. And I''ll feel happy just remembering today. This place is already special to me. I have two or three places like this in Petersburg.', '', NULL, NULL, NULL, NULL, 'white nights first night', 'im a dreamer my real life is so empty that moments like this are rare treasures for me i hold on to them and relive them in my dreams ill be dreaming of you all night all week maybe all year ill definitely come back here tomorrow to this very spot at the same time and ill feel happy just remembering today this place is already special to me i have two or three places like this in petersburg', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'first night', 'First Night', 45, NULL, 'Once I even cried over memories in one of those places. Just like you. Who knows, maybe ten minutes ago you were crying over a memory, too. But forgive me. I''ve let myself ramble again. Perhaps you''ve been especially happy here once before. Very good, said the girl. Perhaps I will come here tomorrow, too, at ten o''clock. I see that I can''t forbid you. The fact is, I have to be here.', '', NULL, NULL, NULL, NULL, 'white nights first night', 'once i even cried over memories in one of those places just like you who knows maybe ten minutes ago you were crying over a memory too but forgive me ive let myself ramble again perhaps youve been especially happy here once before very good said the girl perhaps i will come here tomorrow too at ten oclock i see that i cant forbid you the fact is i have to be here', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'first night', 'First Night', 46, NULL, 'Don''t imagine that I''m making an appointment with you. I tell you beforehand that I have to be here on my own account. But— Well, I tell you straight out, I don''t mind if you do come. To begin with, something unpleasant might happen as it did today, but never mind that. In short, I should simply like to see you. To say two words to you. Only mind you must not think the worse of me now.', '', NULL, NULL, NULL, NULL, 'white nights first night', 'dont imagine that im making an appointment with you i tell you beforehand that i have to be here on my own account but well i tell you straight out i dont mind if you do come to begin with something unpleasant might happen as it did today but never mind that in short i should simply like to see you to say two words to you only mind you must not think the worse of me now', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'first night', 'First Night', 47, NULL, 'Don''t think I make appointments so lightly. I shouldn''t make it except that. But let that be my secret, only a compact beforehand. A compact? Speak, tell me, tell me all beforehand. I agree to anything. I am ready for anything, I cry delighted. I answer for myself. I will be obedient, respectful. You know me. It''s just because I do know you that I ask you to come tomorrow, said the girl, laughing.', '', NULL, NULL, NULL, NULL, 'white nights first night', 'dont think i make appointments so lightly i shouldnt make it except that but let that be my secret only a compact beforehand a compact speak tell me tell me all beforehand i agree to anything i am ready for anything i cry delighted i answer for myself i will be obedient respectful you know me its just because i do know you that i ask you to come tomorrow said the girl laughing', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'first night', 'First Night', 48, NULL, 'I know you perfectly. But mind you will come on the condition in the first place. Only be good, do what I ask. You see, I speak frankly. You won''t fall in love with me. That''s impossible, I assure you. I am ready for friendship. Here''s my hand. But you mustn''t fall in love with me, I beg you. I swear, I cried, gripping her hand. Hush, don''t swear. I know you are ready to flare up like gunpowder.', '', NULL, NULL, NULL, NULL, 'white nights first night', 'i know you perfectly but mind you will come on the condition in the first place only be good do what i ask you see i speak frankly you wont fall in love with me thats impossible i assure you i am ready for friendship heres my hand but you mustnt fall in love with me i beg you i swear i cried gripping her hand hush dont swear i know you are ready to flare up like gunpowder', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'first night', 'First Night', 49, NULL, 'Don''t think ill of me for saying so. If only you knew, I too have no one to whom I can say a word, whose advice I can ask. Of course, one does not look for an advisor in the street, but you are an exception. I know you as though we had been friends for twenty years. You won''t deceive me, will you? You will see. The only thing is, I don''t know how I am going to survive the next twenty-four hours.', '', NULL, NULL, NULL, NULL, 'white nights first night', 'dont think ill of me for saying so if only you knew i too have no one to whom i can say a word whose advice i can ask of course one does not look for an advisor in the street but you are an exception i know you as though we had been friends for twenty years you wont deceive me will you you will see the only thing is i dont know how i am going to survive the next twenty four hours', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'first night', 'First Night', 50, NULL, 'Sleep soundly, good night, and remember that I have trusted you already. But you exclaimed so nicely just now, surely one can''t be held responsible for every feeling, even for brotherly sympathy. Do you know that was so nicely said, that the idea struck me at once, that I might confide in you? For God''s sake do, but about what? What is it? Wait till tomorrow. Meanwhile, let that be a secret.', '', NULL, NULL, NULL, NULL, 'white nights first night', 'sleep soundly good night and remember that i have trusted you already but you exclaimed so nicely just now surely one cant be held responsible for every feeling even for brotherly sympathy do you know that was so nicely said that the idea struck me at once that i might confide in you for gods sake do but about what what is it wait till tomorrow meanwhile let that be a secret', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'first night', 'First Night', 51, NULL, 'So much the better for you. It will give it a faint flavor of romance. Perhaps I will tell you tomorrow, and perhaps not. I will talk to you a little more beforehand. We will get to know each other better. Oh, yes, I will tell you all about myself tomorrow. But what has happened? It is as though a miracle had befallen me. My God, where am I? Come tell me, aren''t you glad that you were not angry and did not drive me away at the first moment as any other woman would have done?', '', NULL, NULL, NULL, NULL, 'white nights first night', 'so much the better for you it will give it a faint flavor of romance perhaps i will tell you tomorrow and perhaps not i will talk to you a little more beforehand we will get to know each other better oh yes i will tell you all about myself tomorrow but what has happened it is as though a miracle had befallen me my god where am i come tell me arent you glad that you were not angry and did not drive me away at the first moment as any other woman would have done', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'first night', 'First Night', 52, NULL, 'In two minutes you have made me happy forever. Yes, happy. Who knows, perhaps, you have reconciled me with myself, solved my doubts. Perhaps such moments come upon me. But there I will tell you all about it tomorrow. You shall know everything, everything. Very well, I consent. You shall begin. Agreed. Goodbye till tomorrow. Till tomorrow. And we parted. I walked about all night. I could not make up my mind to go home.', '', NULL, NULL, NULL, NULL, 'white nights first night', 'in two minutes you have made me happy forever yes happy who knows perhaps you have reconciled me with myself solved my doubts perhaps such moments come upon me but there i will tell you all about it tomorrow you shall know everything everything very well i consent you shall begin agreed goodbye till tomorrow till tomorrow and we parted i walked about all night i could not make up my mind to go home', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'first night', 'First Night', 53, NULL, 'I was so happy. Tomorrow.', '', NULL, NULL, NULL, NULL, 'white nights first night', 'i was so happy tomorrow', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'second night', 'Second Night', 0, NULL, 'Well, you''ve made it through, she said, holding both my hands tightly. I''ve been here for the past two hours. You have no idea what a state I''ve been in all day. I know, I know. But let''s get down to business. Do you know why I came? Not to talk nonsense like yesterday. Here''s the thing. We need to act more sensibly from now on. I thought a lot about this last night.', '', NULL, NULL, NULL, NULL, 'white nights second night', 'well youve made it through she said holding both my hands tightly ive been here for the past two hours you have no idea what a state ive been in all day i know i know but lets get down to business do you know why i came not to talk nonsense like yesterday heres the thing we need to act more sensibly from now on i thought a lot about this last night', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'second night', 'Second Night', 1, NULL, 'In what way? What do you mean by more sensibly? I''m ready to do my part, but honestly, nothing has ever seemed more sensible to me than this. What''s happening right now? Really? Well, first of all, please don''t squeeze my hand so hard. Secondly, I have to tell you, I spent a lot of time thinking about you today, and I wasn''t sure what to make of it. And?', '', NULL, NULL, NULL, NULL, 'white nights second night', 'in what way what do you mean by more sensibly im ready to do my part but honestly nothing has ever seemed more sensible to me than this whats happening right now really well first of all please dont squeeze my hand so hard secondly i have to tell you i spent a lot of time thinking about you today and i wasnt sure what to make of it and', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'second night', 'Second Night', 2, NULL, 'How did it end? How did it end? Well, I realized that we have to start fresh, because after thinking it over, I concluded that I don''t know you at all. Last night, I acted like a child, like a silly little girl. I''ve decided it''s my soft heart that''s to blame. That''s what we always do, isn''t it? We analyze our actions and end up excusing ourselves. But to fix my mistake, I''ve decided I need to learn everything about you.', '', NULL, NULL, NULL, NULL, 'white nights second night', 'how did it end how did it end well i realized that we have to start fresh because after thinking it over i concluded that i dont know you at all last night i acted like a child like a silly little girl ive decided its my soft heart thats to blame thats what we always do isnt it we analyze our actions and end up excusing ourselves but to fix my mistake ive decided i need to learn everything about you', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'second night', 'Second Night', 3, NULL, 'Since there''s no one I can ask, you''ll have to tell me yourself. So what kind of person are you? Come on, start from the beginning. Tell me your whole story. My story? I repeated nervously. My story? But who said I have a story? I don''t have one. Then how have you lived if you don''t have a story? She asked, laughing. I''ve lived without any story at all.', '', NULL, NULL, NULL, NULL, 'white nights second night', 'since theres no one i can ask youll have to tell me yourself so what kind of person are you come on start from the beginning tell me your whole story my story i repeated nervously my story but who said i have a story i dont have one then how have you lived if you dont have a story she asked laughing ive lived without any story at all', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'second night', 'Second Night', 4, NULL, 'I''ve lived keeping to myself, completely alone, utterly alone. Do you know what it means to be alone? Alone? What do you mean? Do you never see anyone? Oh, I see people, of course. But even so, I''m alone. What? Do you mean you never talk to anyone? Not really, not in any meaningful way. Then who are you? Explain yourself. Wait, I think I know. You must be like me.', '', NULL, NULL, NULL, NULL, 'white nights second night', 'ive lived keeping to myself completely alone utterly alone do you know what it means to be alone alone what do you mean do you never see anyone oh i see people of course but even so im alone what do you mean you never talk to anyone not really not in any meaningful way then who are you explain yourself wait i think i know you must be like me', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'second night', 'Second Night', 5, NULL, 'Do you have a grandmother? Mine is blind, and she never lets me go anywhere. I''ve almost forgotten how to talk to people. Two years ago, when I got into trouble and couldn''t be controlled, she made me sit with her. She even pinned my dress to hers, and now we sit like that every day. She knits stockings, even though she''s blind, and I sit next to her, sewing or reading aloud.', '', NULL, NULL, NULL, NULL, 'white nights second night', 'do you have a grandmother mine is blind and she never lets me go anywhere ive almost forgotten how to talk to people two years ago when i got into trouble and couldnt be controlled she made me sit with her she even pinned my dress to hers and now we sit like that every day she knits stockings even though shes blind and i sit next to her sewing or reading aloud', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'second night', 'Second Night', 6, NULL, 'For two years now, we''ve been stuck like that. It''s such a strange habit. My God, how awful! No, I don''t have a grandmother like that. Well, then, if you don''t, why do you stay home all the time? Do you really want to know what kind of person I am? Yes, I do. In the strict sense of the word? In the very strictest sense of the word. Very well, I am a type.', '', NULL, NULL, NULL, NULL, 'white nights second night', 'for two years now weve been stuck like that its such a strange habit my god how awful no i dont have a grandmother like that well then if you dont why do you stay home all the time do you really want to know what kind of person i am yes i do in the strict sense of the word in the very strictest sense of the word very well i am a type', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'second night', 'Second Night', 7, NULL, 'A type? A type? What sort of type? the girl exclaimed, laughing as though she hadn''t had the chance to laugh in a whole year. Yes, it''s so amusing talking to you. Look, here''s a bench. Let''s sit down. No one will walk by here. No one will overhear us. Now tell me your story. Don''t try to deny it. I know you have a story. You''re just hiding it.', '', NULL, NULL, NULL, NULL, 'white nights second night', 'a type a type what sort of type the girl exclaimed laughing as though she hadnt had the chance to laugh in a whole year yes its so amusing talking to you look heres a bench lets sit down no one will walk by here no one will overhear us now tell me your story dont try to deny it i know you have a story youre just hiding it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'second night', 'Second Night', 8, NULL, 'To start with, what is a type? A type? A type is someone original. It''s a ridiculous person, I replied, catching her contagious, childlike laughter. It''s a character. Listen, do you know what it means to be a dreamer? A dreamer? Of course I do. I''m a dreamer myself. Sometimes when I sit with my grandmother, all sorts of things fill my head. Why, when I start dreaming, my imagination runs wild.', '', NULL, NULL, NULL, NULL, 'white nights second night', 'to start with what is a type a type a type is someone original its a ridiculous person i replied catching her contagious childlike laughter its a character listen do you know what it means to be a dreamer a dreamer of course i do im a dreamer myself sometimes when i sit with my grandmother all sorts of things fill my head why when i start dreaming my imagination runs wild', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'second night', 'Second Night', 9, NULL, 'I''ve even married a Chinese prince in my dreams. But sometimes dreaming is a good thing. Though goodness knows it''s better when you have something real to think about instead, she added, her tone suddenly more serious. Wonderful. If you''ve been married to a Chinese emperor, then you''ll understand me perfectly. Come, listen. Oh, but wait a moment. I don''t even know your name yet. Finally! You sure took your time thinking of that.', '', NULL, NULL, NULL, NULL, 'white nights second night', 'ive even married a chinese prince in my dreams but sometimes dreaming is a good thing though goodness knows its better when you have something real to think about instead she added her tone suddenly more serious wonderful if youve been married to a chinese emperor then youll understand me perfectly come listen oh but wait a moment i dont even know your name yet finally you sure took your time thinking of that', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'second night', 'Second Night', 10, NULL, 'My goodness, it never even occurred to me before. I felt perfectly happy without knowing. My name is Nastenka. Nastenka. And that''s it? Nothing more? Nothing more? Why, isn''t that enough for you, you insatiable person? Not enough? On the contrary, it''s more than enough. A great deal, actually. Nastenka, you kind girl. If you''re Nastenka to me from the start, that''s all I need. Exactly, well. Well, listen, Nastenka.', '', NULL, NULL, NULL, NULL, 'white nights second night', 'my goodness it never even occurred to me before i felt perfectly happy without knowing my name is nastenka nastenka and thats it nothing more nothing more why isnt that enough for you you insatiable person not enough on the contrary its more than enough a great deal actually nastenka you kind girl if youre nastenka to me from the start thats all i need exactly well well listen nastenka', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'second night', 'Second Night', 11, NULL, 'Here''s my ridiculous story. I sat beside her, put on a mockingly serious expression, and began speaking as though reading from a book. There are, Nastenka, though you might not realize it, strange little corners in Petersburg. It''s as if the same sun that shines on the rest of Petersburg doesn''t reach these spots. Instead, they seem to have a different sun, one made just for them, casting a unique light on everything.', '', NULL, NULL, NULL, NULL, 'white nights second night', 'heres my ridiculous story i sat beside her put on a mockingly serious expression and began speaking as though reading from a book there are nastenka though you might not realize it strange little corners in petersburg its as if the same sun that shines on the rest of petersburg doesnt reach these spots instead they seem to have a different sun one made just for them casting a unique light on everything', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'second night', 'Second Night', 12, NULL, 'In these hidden corners, my dear Nastenka, life is very different from the bustling world around us. It''s a life that seems to belong to some far-off, unknown place, not to our overly serious times. This life is a mix of the wildly imaginative and passionately idealistic, combined, unfortunately, with something drab and dull, plainly ordinary, if not downright vulgar. Wow, good heavens, what an introduction! What am I hearing?', '', NULL, NULL, NULL, NULL, 'white nights second night', 'in these hidden corners my dear nastenka life is very different from the bustling world around us its a life that seems to belong to some far off unknown place not to our overly serious times this life is a mix of the wildly imaginative and passionately idealistic combined unfortunately with something drab and dull plainly ordinary if not downright vulgar wow good heavens what an introduction what am i hearing', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'second night', 'Second Night', 13, NULL, 'Listen, Nastenka. I feel like I''ll never get tired of calling you Nastenka. Let me tell you that in these little corners strange people live, dreamers. A dreamer, if you want an exact definition, isn''t really a regular person. There''s something in between. Most of the time they settle into some hidden, unreachable corner, as if they''re trying to escape the daylight. Once they find their little spot, they stick to it like a snail, or maybe more like a tortoise, that odd creature which is both an animal and its own house.', '', NULL, NULL, NULL, NULL, 'white nights second night', 'listen nastenka i feel like ill never get tired of calling you nastenka let me tell you that in these little corners strange people live dreamers a dreamer if you want an exact definition isnt really a regular person theres something in between most of the time they settle into some hidden unreachable corner as if theyre trying to escape the daylight once they find their little spot they stick to it like a snail or maybe more like a tortoise that odd creature which is both an animal and its own house', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'second night', 'Second Night', 14, NULL, 'Now why do you think they''re so attached to their four walls, which are always painted some dull green, dirty, gloomy, and always smelling horribly of tobacco smoke? And why, when one of their rare acquaintances visits them, because eventually they manage to drive away all their friends, why does this strange person greet them with such awkwardness? They seem embarrassed, their face changes, and they look like they''ve just committed some crime within those four walls, like they''ve been forging fake money or writing poems to send to a magazine, pretending the real poet has passed away, and they feel obligated to get the work published.', '', NULL, NULL, NULL, NULL, 'white nights second night', 'now why do you think theyre so attached to their four walls which are always painted some dull green dirty gloomy and always smelling horribly of tobacco smoke and why when one of their rare acquaintances visits them because eventually they manage to drive away all their friends why does this strange person greet them with such awkwardness they seem embarrassed their face changes and they look like theyve just committed some crime within those four walls like theyve been forging fake money or writing poems to send to a magazine pretending the real poet has passed away and they feel obligated to get the work published', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'second night', 'Second Night', 15, NULL, 'Why tell me, Nastenka, is it so hard for these two to have a normal conversation? Why is there no laughter? Why does the visitor, who might otherwise love to joke around and chat about light-hearted things, like women or other fun topics, suddenly fall silent? And why does this visitor, who is probably new and making their first visit—because, trust me, there won''t be a second—why does even this friend become so uncomfortable and tongue-tied, even if they''re normally witty?', '', NULL, NULL, NULL, NULL, 'white nights second night', 'why tell me nastenka is it so hard for these two to have a normal conversation why is there no laughter why does the visitor who might otherwise love to joke around and chat about light hearted things like women or other fun topics suddenly fall silent and why does this visitor who is probably new and making their first visit because trust me there wont be a second why does even this friend become so uncomfortable and tongue tied even if theyre normally witty', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'second night', 'Second Night', 16, NULL, 'It''s as if they''re trapped by the gloomy expression on their host''s face. And why does the host, in turn, seem completely lost, desperately trying to liven things up, show some charm, and talk about cheerful things like women to make the visit enjoyable? And why does this visitor, suddenly remembering some urgent task that doesn''t really exist, grab their hat and hurry to leave? They pull their hand away from their host''s overly warm handshake, as the host tries their best to express regret and salvage the failed meeting.', '', NULL, NULL, NULL, NULL, 'white nights second night', 'its as if theyre trapped by the gloomy expression on their hosts face and why does the host in turn seem completely lost desperately trying to liven things up show some charm and talk about cheerful things like women to make the visit enjoyable and why does this visitor suddenly remembering some urgent task that doesnt really exist grab their hat and hurry to leave they pull their hand away from their hosts overly warm handshake as the host tries their best to express regret and salvage the failed meeting', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'second night', 'Second Night', 17, NULL, 'Why does the visitor chuckle on their way out, promising themselves never to visit this odd person again? And yet, at the same time, they can''t help but imagine that the host''s face, during their conversation, looked exactly like a poor kitten, caught by some mischievous children, roughly handled, scared, and teased until, utterly humiliated, it hides under a chair in the dark. There it bristles up, hisses, and washes its face with its little paws, sulking over its ordeal and glaring at the world, even at the scraps of food the kind housekeeper left for it.', '', NULL, NULL, NULL, NULL, 'white nights second night', 'why does the visitor chuckle on their way out promising themselves never to visit this odd person again and yet at the same time they cant help but imagine that the hosts face during their conversation looked exactly like a poor kitten caught by some mischievous children roughly handled scared and teased until utterly humiliated it hides under a chair in the dark there it bristles up hisses and washes its face with its little paws sulking over its ordeal and glaring at the world even at the scraps of food the kind housekeeper left for it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'second night', 'Second Night', 18, NULL, 'Wait, Nastenka interrupted, her eyes wide and her little mouth open in surprise as she listened to me. Wait. I don''t know why all that happened, or why you''re asking me such ridiculous questions. All I know is, this must have happened to you exactly like that. Doubtless, I replied with the most serious expression. Well, since there''s no doubt about it, go on, said Nastenka, because I really want to know how it all ends.', '', NULL, NULL, NULL, NULL, 'white nights second night', 'wait nastenka interrupted her eyes wide and her little mouth open in surprise as she listened to me wait i dont know why all that happened or why youre asking me such ridiculous questions all i know is this must have happened to you exactly like that doubtless i replied with the most serious expression well since theres no doubt about it go on said nastenka because i really want to know how it all ends', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'second night', 'Second Night', 19, NULL, 'You want to know, Nastenka, what our hero, that is, me, since I was the hero of the whole affair, was doing in his little corner? You want to know why the unexpected visit of a friend left me so flustered, why I felt upset the entire day? You want to know why I completely lost my composure, why I blushed when the door opened, why I was so incapable of hosting my visitor, and why I crumbled under the weight of my own hospitality?', '', NULL, NULL, NULL, NULL, 'white nights second night', 'you want to know nastenka what our hero that is me since i was the hero of the whole affair was doing in his little corner you want to know why the unexpected visit of a friend left me so flustered why i felt upset the entire day you want to know why i completely lost my composure why i blushed when the door opened why i was so incapable of hosting my visitor and why i crumbled under the weight of my own hospitality', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'second night', 'Second Night', 20, NULL, 'Yes, yes, Nastenka responded eagerly. That''s exactly it. You''re describing it all so wonderfully, but couldn''t you maybe tone it down just a little? You sound like you''re reading a story straight out of a book. Nastenka, I said in a mock serious tone, trying not to laugh. Dear Nastenka, I know I describe things splendidly, but forgive me, I don''t know how else to do it. Right now, Nastenka, I feel like the spirit of King Solomon when, after being locked away in an urn sealed with seven seals for a thousand years, those seals were finally broken.', '', NULL, NULL, NULL, NULL, 'white nights second night', 'yes yes nastenka responded eagerly thats exactly it youre describing it all so wonderfully but couldnt you maybe tone it down just a little you sound like youre reading a story straight out of a book nastenka i said in a mock serious tone trying not to laugh dear nastenka i know i describe things splendidly but forgive me i dont know how else to do it right now nastenka i feel like the spirit of king solomon when after being locked away in an urn sealed with seven seals for a thousand years those seals were finally broken', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'second night', 'Second Night', 21, NULL, 'At this moment, after we''ve met, after such a long separation because I feel I''ve known you forever, Nastenka, right now, it feels as if a thousand valves have opened in my head. Words are pouring out of me like a river, and if I don''t let them flow, I think I might burst. So I beg you, Nastenka, don''t interrupt me, just listen patiently, or else I''ll have to stop.', '', NULL, NULL, NULL, NULL, 'white nights second night', 'at this moment after weve met after such a long separation because i feel ive known you forever nastenka right now it feels as if a thousand valves have opened in my head words are pouring out of me like a river and if i dont let them flow i think i might burst so i beg you nastenka dont interrupt me just listen patiently or else ill have to stop', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'second night', 'Second Night', 22, NULL, 'No, no, no, please, don''t stop, go on, I won''t say a word. All right, then, I''ll continue. There is, Nastenka, a certain hour of the day that I love more than any other. It''s the hour when most people have finished their work or errands, when they''re hurrying home for dinner, to relax, to rest, or to think about the pleasant moments their free time might bring. At that hour, our hero—yes, allow me to speak about myself—in the third person, since it feels too embarrassing to tell it in the first person, would join the others heading home, but on his face, pale and a bit crumpled, there was a strange expression of happiness.', '', NULL, NULL, NULL, NULL, 'white nights second night', 'no no no please dont stop go on i wont say a word all right then ill continue there is nastenka a certain hour of the day that i love more than any other its the hour when most people have finished their work or errands when theyre hurrying home for dinner to relax to rest or to think about the pleasant moments their free time might bring at that hour our hero yes allow me to speak about myself in the third person since it feels too embarrassing to tell it in the first person would join the others heading home but on his face pale and a bit crumpled there was a strange expression of happiness', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'second night', 'Second Night', 23, NULL, 'He wasn''t indifferent to the fading glow of the sunset over the cold Petersburg sky, though he didn''t consciously notice it, either. It was more like he saw it without realizing, as though he were distracted by something far more interesting. He was happy because until the next day he was free from the tedious responsibilities that weighed on him. He felt as joyful as a schoolboy let loose after class, ready to dive into games and harmless mischief.', '', NULL, NULL, NULL, NULL, 'white nights second night', 'he wasnt indifferent to the fading glow of the sunset over the cold petersburg sky though he didnt consciously notice it either it was more like he saw it without realizing as though he were distracted by something far more interesting he was happy because until the next day he was free from the tedious responsibilities that weighed on him he felt as joyful as a schoolboy let loose after class ready to dive into games and harmless mischief', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'second night', 'Second Night', 24, NULL, 'If you had seen him then, Nastenka, you would have noticed how joy flickered across his face, already affecting his sensitive nerves and overly vivid imagination. He wasn''t thinking about dinner or the evening ahead. No, he was lost in his own private world. Look at him, Nastenka. He''s rich now, rich with his inner life. The golden light of the setting sun warms his heart and stirs a swarm of impressions.', '', NULL, NULL, NULL, NULL, 'white nights second night', 'if you had seen him then nastenka you would have noticed how joy flickered across his face already affecting his sensitive nerves and overly vivid imagination he wasnt thinking about dinner or the evening ahead no he was lost in his own private world look at him nastenka hes rich now rich with his inner life the golden light of the setting sun warms his heart and stirs a swarm of impressions', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'second night', 'Second Night', 25, NULL, 'He barely notices the road beneath his feet or the little details that might usually catch his attention. The goddess of fancy, if you''ve read Zhukovsky, Nastenka, has already begun spinning her threads, weaving patterns of magical, enchanting life. Who knows? Perhaps she has carried him far away, to some shimmering dreamland, leaving the ordinary world behind. Stop him now, ask him where he''s going, and he wouldn''t know. He''d probably blush with embarrassment and make up an excuse, anything to avoid admitting he was lost in his thoughts.', '', NULL, NULL, NULL, NULL, 'white nights second night', 'he barely notices the road beneath his feet or the little details that might usually catch his attention the goddess of fancy if youve read zhukovsky nastenka has already begun spinning her threads weaving patterns of magical enchanting life who knows perhaps she has carried him far away to some shimmering dreamland leaving the ordinary world behind stop him now ask him where hes going and he wouldnt know hed probably blush with embarrassment and make up an excuse anything to avoid admitting he was lost in his thoughts', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'second night', 'Second Night', 26, NULL, 'That''s why he jumps in surprise when a kind old lady stops him on the street to ask for directions. Irritated at being pulled back to reality, he strides off again, barely noticing how passers-by glance curiously at him. A little girl stepping aside to avoid him, giggles at his distracted smile and odd gestures. But even these interruptions, Nastenka, are caught by his imagination and spun into the whimsical tapestry of his thoughts.', '', NULL, NULL, NULL, NULL, 'white nights second night', 'thats why he jumps in surprise when a kind old lady stops him on the street to ask for directions irritated at being pulled back to reality he strides off again barely noticing how passers by glance curiously at him a little girl stepping aside to avoid him giggles at his distracted smile and odd gestures but even these interruptions nastenka are caught by his imagination and spun into the whimsical tapestry of his thoughts', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'second night', 'Second Night', 27, NULL, 'When he finally returns to his quiet little den, his mind is overflowing with new impressions. Matrona, his sombre and dutiful housekeeper, clears away his dinner, which he barely remembers eating. The room grows dark. The colourful kingdom of his fantasies crumbles into silence, like a fading dream he can''t quite recall. Yet his heart aches with a strange, tender longing. Something stirs within him, teasing his imagination to build new dreams.', '', NULL, NULL, NULL, NULL, 'white nights second night', 'when he finally returns to his quiet little den his mind is overflowing with new impressions matrona his sombre and dutiful housekeeper clears away his dinner which he barely remembers eating the room grows dark the colourful kingdom of his fantasies crumbles into silence like a fading dream he cant quite recall yet his heart aches with a strange tender longing something stirs within him teasing his imagination to build new dreams', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'second night', 'Second Night', 28, NULL, 'As the house grows still, his solitude feeds his thoughts. A book lies abandoned in his lap, forgotten after just a few pages. His mind has already begun crafting a new world, filled with fresh adventures and delicate emotions. What does he care about real life, Nastenka? To him it seems dull, lifeless, slow—nothing like the vivid, enchanting world of his dreams. And yet, Nastenka, even as he loses himself in these dreams, a day may come when he''d trade all of them for just one moment of real, imperfect life.', '', NULL, NULL, NULL, NULL, 'white nights second night', 'as the house grows still his solitude feeds his thoughts a book lies abandoned in his lap forgotten after just a few pages his mind has already begun crafting a new world filled with fresh adventures and delicate emotions what does he care about real life nastenka to him it seems dull lifeless slow nothing like the vivid enchanting world of his dreams and yet nastenka even as he loses himself in these dreams a day may come when hed trade all of them for just one moment of real imperfect life', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'second night', 'Second Night', 29, NULL, 'Perhaps he doesn''t foresee it yet, but one day the hour may strike when he would give anything to escape his illusions and grasp something real. But for now, he''s content to live as the artist of his own existence, creating a new life for himself, every hour. When I finished my heartfelt appeal, I paused, letting my words hang in the air, feeling as though my emotions had poured out too pathetically.', '', NULL, NULL, NULL, NULL, 'white nights second night', 'perhaps he doesnt foresee it yet but one day the hour may strike when he would give anything to escape his illusions and grasp something real but for now hes content to live as the artist of his own existence creating a new life for himself every hour when i finished my heartfelt appeal i paused letting my words hang in the air feeling as though my emotions had poured out too pathetically', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'second night', 'Second Night', 30, NULL, 'At that moment I had an intense urge to force myself to laugh, to brush it all off as a joke, but I couldn''t. I could feel something deep and painful stirring within me, a malignant demon of self-awareness. There was a lump forming in my throat, my chin was beginning to quiver, and my eyes were slowly welling with tears that I struggled to hold back. I glanced at Nastenka, who had been listening intently, her clever eyes wide with curiosity.', '', NULL, NULL, NULL, NULL, 'white nights second night', 'at that moment i had an intense urge to force myself to laugh to brush it all off as a joke but i couldnt i could feel something deep and painful stirring within me a malignant demon of self awareness there was a lump forming in my throat my chin was beginning to quiver and my eyes were slowly welling with tears that i struggled to hold back i glanced at nastenka who had been listening intently her clever eyes wide with curiosity', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'second night', 'Second Night', 31, NULL, 'I expected her to break into one of her innocent, irrepressible laughs, the kind that could bring lightness to even the heaviest moment. I braced myself for it, even regretting how far I had let my confession go. Why had I opened myself up so completely? Why had I poured out what had been simmering in my heart for so long? These were thoughts I had turned over endlessly in my mind, passed judgment on long ago, and here I was reliving them as though reading from a well-rehearsed script.', '', NULL, NULL, NULL, NULL, 'white nights second night', 'i expected her to break into one of her innocent irrepressible laughs the kind that could bring lightness to even the heaviest moment i braced myself for it even regretting how far i had let my confession go why had i opened myself up so completely why had i poured out what had been simmering in my heart for so long these were thoughts i had turned over endlessly in my mind passed judgment on long ago and here i was reliving them as though reading from a well rehearsed script', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'second night', 'Second Night', 32, NULL, 'I had made my confession, not expecting understanding, but simply unable to keep it inside any longer. But to my surprise, Nastenka didn''t laugh. Instead, she remained silent, her expression softening with something far more meaningful. She waited a moment, as if searching for the right words, and then faintly pressed my hand. Her touch was light, filled with timid sympathy. Finally, in a voice that trembled with concern, she asked, Surely, you haven''t lived like that all your life?', '', NULL, NULL, NULL, NULL, 'white nights second night', 'i had made my confession not expecting understanding but simply unable to keep it inside any longer but to my surprise nastenka didnt laugh instead she remained silent her expression softening with something far more meaningful she waited a moment as if searching for the right words and then faintly pressed my hand her touch was light filled with timid sympathy finally in a voice that trembled with concern she asked surely you havent lived like that all your life', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'second night', 'Second Night', 33, NULL, 'All my life, Nastenka, I replied, my voice heavy with resignation. All my life. And it feels as though I''m destined to live that way until the very end. No, that won''t do, she said quickly, her uneasiness plain. That must not be. And if I think about it, maybe I''ll spend my whole life beside my grandmother, too. But do you know? It''s not right to live like that.', '', NULL, NULL, NULL, NULL, 'white nights second night', 'all my life nastenka i replied my voice heavy with resignation all my life and it feels as though im destined to live that way until the very end no that wont do she said quickly her uneasiness plain that must not be and if i think about it maybe ill spend my whole life beside my grandmother too but do you know its not right to live like that', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'second night', 'Second Night', 34, NULL, 'It''s not good. I know, Nastenka, I know, I cried, no longer able to restrain my emotions. And now I realize it more than ever. I see it so clearly, so painfully. I''ve wasted my best years, thrown them away, and now, sitting here beside you, I feel it with an ache I can hardly bear. It''s as if God himself sent you to me, my good angel, to tell me the truth, to show me what I''ve lost.', '', NULL, NULL, NULL, NULL, 'white nights second night', 'its not good i know nastenka i know i cried no longer able to restrain my emotions and now i realize it more than ever i see it so clearly so painfully ive wasted my best years thrown them away and now sitting here beside you i feel it with an ache i can hardly bear its as if god himself sent you to me my good angel to tell me the truth to show me what ive lost', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'second night', 'Second Night', 35, NULL, 'Here I am, talking with you, and it feels strange, even impossible, to think about the future. Because when I think of the future, I see nothing but loneliness again. I see the same stale, useless life waiting for me, and it horrifies me. What will I have to dream of, then, when for these two evenings I''ve known real happiness? Sitting beside you, talking with you, this has been real.', '', NULL, NULL, NULL, NULL, 'white nights second night', 'here i am talking with you and it feels strange even impossible to think about the future because when i think of the future i see nothing but loneliness again i see the same stale useless life waiting for me and it horrifies me what will i have to dream of then when for these two evenings ive known real happiness sitting beside you talking with you this has been real', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'second night', 'Second Night', 36, NULL, 'What will become of me when this is gone? I paused, overwhelmed by my own words, and for a moment I feared they might have been too much. But Nastenka''s reaction was immediate and sincere. Tears sparkled in her eyes as she shook her head vehemently. Oh, no, no, she cried, her voice filled with emotion. It can''t be like that anymore. It mustn''t be. We can''t just part like this.', '', NULL, NULL, NULL, NULL, 'white nights second night', 'what will become of me when this is gone i paused overwhelmed by my own words and for a moment i feared they might have been too much but nastenkas reaction was immediate and sincere tears sparkled in her eyes as she shook her head vehemently oh no no she cried her voice filled with emotion it cant be like that anymore it mustnt be we cant just part like this', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'second night', 'Second Night', 37, NULL, 'What are two evenings? Two evenings are nothing. Oh, Nastenka, Nastenka, do you realize how much you''ve helped me make peace with myself? Do you understand that because of you I might finally stop looking at myself with such disdain during those dark moments when I loathe everything about my life? Do you know that you may even help me let go of the weight of guilt I''ve carried for so long, the feeling that my life itself has been a crime and a sin?', '', NULL, NULL, NULL, NULL, 'white nights second night', 'what are two evenings two evenings are nothing oh nastenka nastenka do you realize how much youve helped me make peace with myself do you understand that because of you i might finally stop looking at myself with such disdain during those dark moments when i loathe everything about my life do you know that you may even help me let go of the weight of guilt ive carried for so long the feeling that my life itself has been a crime and a sin', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'second night', 'Second Night', 38, NULL, 'And don''t think for a second, Nastenka, don''t think I''m exaggerating. I''m telling you the plain truth. At times, a misery so deep takes hold of me, a misery I can hardly explain to anyone, a misery that feels endless. It''s during those times, Nastenka, that I begin to believe I''m incapable of starting a real life, of living in the world as it is. It feels as if I''ve lost all connection to the actual, the tangible, the real.', '', NULL, NULL, NULL, NULL, 'white nights second night', 'and dont think for a second nastenka dont think im exaggerating im telling you the plain truth at times a misery so deep takes hold of me a misery i can hardly explain to anyone a misery that feels endless its during those times nastenka that i begin to believe im incapable of starting a real life of living in the world as it is it feels as if ive lost all connection to the actual the tangible the real', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'second night', 'Second Night', 39, NULL, 'I''ve cursed myself for it over and over again. After my long nights of fantasy, I wake to moments of clarity so brutal, so sobering, that they are almost unbearable. It''s then that the world of life around me becomes deafening, the sounds of people living real lives, moving forward, creating meaning. I hear them, I see them, and I realize their lives aren''t slipping away like dreams or fleeting visions.', '', NULL, NULL, NULL, NULL, 'white nights second night', 'ive cursed myself for it over and over again after my long nights of fantasy i wake to moments of clarity so brutal so sobering that they are almost unbearable its then that the world of life around me becomes deafening the sounds of people living real lives moving forward creating meaning i hear them i see them and i realize their lives arent slipping away like dreams or fleeting visions', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'second night', 'Second Night', 40, NULL, 'Their days aren''t hollow, they''re full of purpose, ever-changing, eternally renewing themselves, each hour different from the last. And then there''s me, with my imagination, which feels so lifeless, so repetitive, so uninspired. My fancy is a slave to shadows and fleeting ideas, shackled to the smallest cloud that dims the sun. And you know how a Petersburg heart yearns for sunlight, don''t you, Nastenka? But when that sun disappears, imagination becomes powerless, crushed under the weight of its own dullness.', '', NULL, NULL, NULL, NULL, 'white nights second night', 'their days arent hollow theyre full of purpose ever changing eternally renewing themselves each hour different from the last and then theres me with my imagination which feels so lifeless so repetitive so uninspired my fancy is a slave to shadows and fleeting ideas shackled to the smallest cloud that dims the sun and you know how a petersburg heart yearns for sunlight dont you nastenka but when that sun disappears imagination becomes powerless crushed under the weight of its own dullness', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'second night', 'Second Night', 41, NULL, 'Fancy, which once seemed boundless, becomes tired, exhausted even, as if it''s been worn out from too much use. And then you realize, Nastenka, that you''ve outgrown your dreams, that the ideals you once cherished are crumbling, shattering into dust. And yet what else can you do but try to build something new from the broken pieces? All the while your soul craves something else, something real, something it cannot name.', '', NULL, NULL, NULL, NULL, 'white nights second night', 'fancy which once seemed boundless becomes tired exhausted even as if its been worn out from too much use and then you realize nastenka that youve outgrown your dreams that the ideals you once cherished are crumbling shattering into dust and yet what else can you do but try to build something new from the broken pieces all the while your soul craves something else something real something it cannot name', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'second night', 'Second Night', 42, NULL, 'And yet in vain the dreamer searches through his old dreams, hoping to find a spark among the ashes, just one ember to reignite the fire, to warm his cold heart once more. He tries to revive that sweet, intoxicating feeling that once made his blood race and his eyes fill with tears, that once deceived him so beautifully. But it''s all for nothing. Do you understand, Nastenka, what I''ve come to?', '', NULL, NULL, NULL, NULL, 'white nights second night', 'and yet in vain the dreamer searches through his old dreams hoping to find a spark among the ashes just one ember to reignite the fire to warm his cold heart once more he tries to revive that sweet intoxicating feeling that once made his blood race and his eyes fill with tears that once deceived him so beautifully but its all for nothing do you understand nastenka what ive come to', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'second night', 'Second Night', 43, NULL, 'Do you know what I do now, out of sheer desperation? I celebrate the anniversaries of my feelings, yes, anniversaries of things that never truly happened. I mark the dates of those foolish, shadowy dreams that I once believed in, dreams that no longer exist because I''ve lost the power to create them. Even dreams, you see, require effort. They don''t come for free. And now I find myself revisiting the places where I once felt happy in my own way.', '', NULL, NULL, NULL, NULL, 'white nights second night', 'do you know what i do now out of sheer desperation i celebrate the anniversaries of my feelings yes anniversaries of things that never truly happened i mark the dates of those foolish shadowy dreams that i once believed in dreams that no longer exist because ive lost the power to create them even dreams you see require effort they dont come for free and now i find myself revisiting the places where i once felt happy in my own way', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'second night', 'Second Night', 44, NULL, 'I try to piece together my present life from the fragments of an unchangeable past. Like a ghost, I wander the streets and alleys of Petersburg, aimless and sad, searching for memories. Do you know what it''s like, Nastenka, to stand on a familiar street and remember that a year ago to the day you were there, just as lonely, just as lost? And yet, somehow, it feels as though things were better then, even though they weren''t.', '', NULL, NULL, NULL, NULL, 'white nights second night', 'i try to piece together my present life from the fragments of an unchangeable past like a ghost i wander the streets and alleys of petersburg aimless and sad searching for memories do you know what its like nastenka to stand on a familiar street and remember that a year ago to the day you were there just as lonely just as lost and yet somehow it feels as though things were better then even though they werent', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'second night', 'Second Night', 45, NULL, 'Back then, your dreams might have been sad, but they weren''t haunted by the black thoughts that torment you now. You didn''t feel the relentless gnawing of conscience, that gloomy, unyielding guilt that eats away at you day and night. And you ask yourself, where have all my dreams gone? You shake your head and think about how quickly the years have flown by. And then comes the awful question.', '', NULL, NULL, NULL, NULL, 'white nights second night', 'back then your dreams might have been sad but they werent haunted by the black thoughts that torment you now you didnt feel the relentless gnawing of conscience that gloomy unyielding guilt that eats away at you day and night and you ask yourself where have all my dreams gone you shake your head and think about how quickly the years have flown by and then comes the awful question', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'second night', 'Second Night', 46, NULL, 'What have you done with your time? Where have you buried your best days? Have you even truly lived? And so you look around and see how cold the world has become. You think about how, in just a few more years, solitude will close in completely. Then will come old age, creeping in with its trembling hands, and after that misery, desolation. Your imagined world will fade. Your dreams will die and fall like autumn leaves from the trees, leaving you utterly alone.', '', NULL, NULL, NULL, NULL, 'white nights second night', 'what have you done with your time where have you buried your best days have you even truly lived and so you look around and see how cold the world has become you think about how in just a few more years solitude will close in completely then will come old age creeping in with its trembling hands and after that misery desolation your imagined world will fade your dreams will die and fall like autumn leaves from the trees leaving you utterly alone', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'second night', 'Second Night', 47, NULL, 'Oh, Nastenka, can you imagine what it will feel like to reach that point, to look back and find you have nothing, absolutely nothing, to regret because everything you''ve lost was never real in the first place? Can you imagine realizing that all you''ve ever had were dreams, foolish, empty dreams? Come now, don''t stir up my feelings anymore, said Nastenka, brushing away a tear that had slipped down her cheek.', '', NULL, NULL, NULL, NULL, 'white nights second night', 'oh nastenka can you imagine what it will feel like to reach that point to look back and find you have nothing absolutely nothing to regret because everything youve lost was never real in the first place can you imagine realizing that all youve ever had were dreams foolish empty dreams come now dont stir up my feelings anymore said nastenka brushing away a tear that had slipped down her cheek', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'second night', 'Second Night', 48, NULL, 'It''s enough, it''s all over now. From this moment we''re together, two of us. Whatever happens to me, we won''t be separated. Do you hear me? We''ll never part. Listen, she continued, her voice soft but filled with resolve. I''m just a simple girl. I haven''t had much education, though Grandmother did hire a teacher for me for a while, but I do understand you, truly, I do. Everything you''ve just described, I felt it too.', '', NULL, NULL, NULL, NULL, 'white nights second night', 'its enough its all over now from this moment were together two of us whatever happens to me we wont be separated do you hear me well never part listen she continued her voice soft but filled with resolve im just a simple girl i havent had much education though grandmother did hire a teacher for me for a while but i do understand you truly i do everything youve just described i felt it too', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'second night', 'Second Night', 49, NULL, 'I went through the same thing when Grandmother pinned me to her dress to keep me by her side. Of course, she added shyly, a faint blush coloring her cheeks. I couldn''t have described it the way you did. You''ve said it so beautifully. I''m not educated enough to speak like that, she admitted timidly, her voice carrying a note of respect for what she called my pathetic eloquence and lofty style.', '', NULL, NULL, NULL, NULL, 'white nights second night', 'i went through the same thing when grandmother pinned me to her dress to keep me by her side of course she added shyly a faint blush coloring her cheeks i couldnt have described it the way you did youve said it so beautifully im not educated enough to speak like that she admitted timidly her voice carrying a note of respect for what she called my pathetic eloquence and lofty style', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'second night', 'Second Night', 50, NULL, 'But still, I''m glad, so very glad that you''ve been so open with me. Now I feel like I know you completely, every part of you. She paused, her dark eyes studying me closely, as if seeing me for the first time in a new light. And do you know what, she said, her tone shifting to one of quiet determination. I want to tell you my story too, everything with no secrets.', '', NULL, NULL, NULL, NULL, 'white nights second night', 'but still im glad so very glad that youve been so open with me now i feel like i know you completely every part of you she paused her dark eyes studying me closely as if seeing me for the first time in a new light and do you know what she said her tone shifting to one of quiet determination i want to tell you my story too everything with no secrets', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'second night', 'Second Night', 51, NULL, 'After that, you must promise to give me advice. You''re so clever. Will you promise to help me figure things out? Ah, Nastenka, I exclaimed, feeling a surge of emotion at her trust. I''ve never been much good at giving advice, sensible advice, least of all. But seeing us here now, like this, I feel as though, if we always stay this way, together, we''ll both end up giving each other plenty of good advice, sensible or not.', '', NULL, NULL, NULL, NULL, 'white nights second night', 'after that you must promise to give me advice youre so clever will you promise to help me figure things out ah nastenka i exclaimed feeling a surge of emotion at her trust ive never been much good at giving advice sensible advice least of all but seeing us here now like this i feel as though if we always stay this way together well both end up giving each other plenty of good advice sensible or not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'second night', 'Second Night', 52, NULL, 'Tell me, my dear Nastenka, what kind of advice do you need? Speak openly. Right now I''m so happy, so light-hearted, so bold and clear-headed that I feel like I could find the right words for anything. No, no, Nastenka interrupted, laughing warmly, her earlier tears already forgotten. I don''t just want sensible advice, I want advice that''s warm and kind, advice that feels like it''s coming from an older brother who has cared about me my whole life.', '', NULL, NULL, NULL, NULL, 'white nights second night', 'tell me my dear nastenka what kind of advice do you need speak openly right now im so happy so light hearted so bold and clear headed that i feel like i could find the right words for anything no no nastenka interrupted laughing warmly her earlier tears already forgotten i dont just want sensible advice i want advice thats warm and kind advice that feels like its coming from an older brother who has cared about me my whole life', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'second night', 'Second Night', 53, NULL, 'That''s the kind of advice I need? Agreed, Nastenka, agreed, I cried, delighted by her request. And let me tell you this, if I had known you all my life, if I had cared about you for twenty years, I still couldn''t feel any fonder of you than I do now. Give me your hand, said Nastenka, her voice steady and filled with meaning. Here it is, I replied, placing my hand in hers without hesitation.', '', NULL, NULL, NULL, NULL, 'white nights second night', 'thats the kind of advice i need agreed nastenka agreed i cried delighted by her request and let me tell you this if i had known you all my life if i had cared about you for twenty years i still couldnt feel any fonder of you than i do now give me your hand said nastenka her voice steady and filled with meaning here it is i replied placing my hand in hers without hesitation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'second night', 'Second Night', 54, NULL, 'She held it for a moment, her fingers gripping mine firmly, as if to seal some unspoken promise between us. Then she smiled, a smile so full of hope and trust that it seemed to light up the dim, quiet street around us. And now, she said, her voice soft but filled with anticipation, Let''s begin my story.', '', NULL, NULL, NULL, NULL, 'white nights second night', 'she held it for a moment her fingers gripping mine firmly as if to seal some unspoken promise between us then she smiled a smile so full of hope and trust that it seemed to light up the dim quiet street around us and now she said her voice soft but filled with anticipation lets begin my story', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 0, NULL, 'Half my story you know already, that is, you know I have an old grandmother. If the other half is as brief as that, I interrupted laughing, be quiet and listen. First of all, you must promise not to interrupt me, or else I might lose track of what I''m saying and end up all muddled, so listen quietly, will you? I have an old grandmother. She''s been my guardian ever since I was a little girl, because my father and mother both passed away when I was very young.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'half my story you know already that is you know i have an old grandmother if the other half is as brief as that i interrupted laughing be quiet and listen first of all you must promise not to interrupt me or else i might lose track of what im saying and end up all muddled so listen quietly will you i have an old grandmother shes been my guardian ever since i was a little girl because my father and mother both passed away when i was very young', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 1, NULL, 'Grandmother must have been better off financially in the past, for she often recalls the good old days. She''s fond of talking about how things were when she was younger, about the elegance of society, the way people behaved, and how different everything is now. She taught me French herself at first, then hired a teacher for me when I got a little older. When I was fifteen, and now I''m seventeen, so it wasn''t so long ago, we stopped the lessons altogether.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'grandmother must have been better off financially in the past for she often recalls the good old days shes fond of talking about how things were when she was younger about the elegance of society the way people behaved and how different everything is now she taught me french herself at first then hired a teacher for me when i got a little older when i was fifteen and now im seventeen so it wasnt so long ago we stopped the lessons altogether', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 2, NULL, 'That was around the time when I began getting into mischief. I won''t tell you exactly what I did, because really it wasn''t anything serious, but it was enough to upset grandmother. One morning she called me to her side and said that because she was blind and couldn''t keep an eye on me, she had to take drastic measures. She took a pin, yes, a real pin, and fastened my dress to hers.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'that was around the time when i began getting into mischief i wont tell you exactly what i did because really it wasnt anything serious but it was enough to upset grandmother one morning she called me to her side and said that because she was blind and couldnt keep an eye on me she had to take drastic measures she took a pin yes a real pin and fastened my dress to hers', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 3, NULL, 'Then she declared that we would sit like that for the rest of our lives unless I started behaving better. Can you imagine? Sitting there, tied to her, day after day? At first there was no escaping her. I had to work, read, and study right beside her. I wasn''t even allowed to take a step away without her permission. I did try to outsmart her once. I persuaded Fekla, our charwoman, to sit in my place while grandmother was napping.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'then she declared that we would sit like that for the rest of our lives unless i started behaving better can you imagine sitting there tied to her day after day at first there was no escaping her i had to work read and study right beside her i wasnt even allowed to take a step away without her permission i did try to outsmart her once i persuaded fekla our charwoman to sit in my place while grandmother was napping', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 4, NULL, 'Fekla is deaf and doesn''t hear much of anything. Grandmother was dozing in her armchair, so I thought everything would be fine. I slipped away to visit a friend who lived nearby, thinking I''d be back before she even noticed. But of course it didn''t go as planned. Grandmother woke up while I was gone and started asking questions. She thought I was still sitting there quietly next to her.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'fekla is deaf and doesnt hear much of anything grandmother was dozing in her armchair so i thought everything would be fine i slipped away to visit a friend who lived nearby thinking id be back before she even noticed but of course it didnt go as planned grandmother woke up while i was gone and started asking questions she thought i was still sitting there quietly next to her', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 5, NULL, 'Poor Fekla didn''t know what to do. She couldn''t understand what grandmother was saying and panicked. In her confusion, she undid the pin and ran off. At this point, Nastenka burst out laughing, the memory clearly amusing her. Her laughter was infectious and I couldn''t help but laugh with her, but she stopped almost immediately and gave me a warning look. I''m serious. Don''t you dare laugh at grandmother. I''m only laughing because it was funny and—well, what can I do?', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'poor fekla didnt know what to do she couldnt understand what grandmother was saying and panicked in her confusion she undid the pin and ran off at this point nastenka burst out laughing the memory clearly amusing her her laughter was infectious and i couldnt help but laugh with her but she stopped almost immediately and gave me a warning look im serious dont you dare laugh at grandmother im only laughing because it was funny and well what can i do', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 6, NULL, 'That''s just how grandmother is. But I''m fond of her in my own way. Oh, how I caught it that time, though. As soon as I came back, she pinned me right back in place, and after that there was no sneaking off again. I wasn''t allowed to stir an inch. Oh, I almost forgot to tell you. Our house belongs to us, or, rather, it belongs to grandmother. It''s a small wooden house with three windows, as old as grandmother herself.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'thats just how grandmother is but im fond of her in my own way oh how i caught it that time though as soon as i came back she pinned me right back in place and after that there was no sneaking off again i wasnt allowed to stir an inch oh i almost forgot to tell you our house belongs to us or rather it belongs to grandmother its a small wooden house with three windows as old as grandmother herself', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 7, NULL, 'There''s also a tiny upper story. Recently a new lodger moved into the upstairs rooms. Then you must have had an old lodger before, I commented casually. Of course we did, Nastenka replied with a hint of exasperation, and let me tell you, he knew how to keep quiet better than you do. In fact, he hardly spoke at all. He was a frail, dried-up little old man, deaf, blind, and lame.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'theres also a tiny upper story recently a new lodger moved into the upstairs rooms then you must have had an old lodger before i commented casually of course we did nastenka replied with a hint of exasperation and let me tell you he knew how to keep quiet better than you do in fact he hardly spoke at all he was a frail dried up little old man deaf blind and lame', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 8, NULL, 'He was so feeble that eventually he just couldn''t go on living anymore. He passed away, and after that we had to find someone new to rent the room. We can''t manage without a lodger. The rent, along with grandmother''s pension, is nearly all we have to live on. But this time the new lodger wasn''t an old man. He was young, a stranger, not from around here. Grandmother took him in because he didn''t haggle over the rent.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'he was so feeble that eventually he just couldnt go on living anymore he passed away and after that we had to find someone new to rent the room we cant manage without a lodger the rent along with grandmothers pension is nearly all we have to live on but this time the new lodger wasnt an old man he was young a stranger not from around here grandmother took him in because he didnt haggle over the rent', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 9, NULL, 'It was only after he moved in that she asked me, Nastenka, tell me, what''s this lodger of ours like? Is he young or old? I didn''t want to lie to her, so I told her the truth. Well, grandmother, I said, he isn''t exactly young, but he''s not old either. And is he pleasant-looking, she asked? I didn''t see any point in lying about that either. Yes, grandmother, I said, he''s pleasant-looking.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'it was only after he moved in that she asked me nastenka tell me whats this lodger of ours like is he young or old i didnt want to lie to her so i told her the truth well grandmother i said he isnt exactly young but hes not old either and is he pleasant looking she asked i didnt see any point in lying about that either yes grandmother i said hes pleasant looking', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 10, NULL, 'Oh, what a nuisance, grandmother exclaimed. What a nuisance! I tell you, Nastenka, you''d better not get any ideas about him. Times are so different now. Why even a lodger like this? And he has to be pleasant-looking, too. It wasn''t like this in the old days. Grandmother was always reminiscing about the old days, how everything was better back then. In the old days, she would say, she was young and full of energy, the sun was warmer, the flowers bloomed more brightly, and even the cream didn''t turn sour so quickly.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'oh what a nuisance grandmother exclaimed what a nuisance i tell you nastenka youd better not get any ideas about him times are so different now why even a lodger like this and he has to be pleasant looking too it wasnt like this in the old days grandmother was always reminiscing about the old days how everything was better back then in the old days she would say she was young and full of energy the sun was warmer the flowers bloomed more brightly and even the cream didnt turn sour so quickly', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 11, NULL, 'Everything, it seemed, was perfect in the old days. Whenever she started talking like this, I would sit quietly, holding my tongue, listening patiently while she lamented the present and glorified the past. But in my mind I couldn''t help but wonder why she had even brought up the lodger''s looks in the first place. Why did she suggest it to me? Why did she ask whether he was young and good-looking?', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'everything it seemed was perfect in the old days whenever she started talking like this i would sit quietly holding my tongue listening patiently while she lamented the present and glorified the past but in my mind i couldnt help but wonder why she had even brought up the lodgers looks in the first place why did she suggest it to me why did she ask whether he was young and good looking', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 12, NULL, 'But that was all I did. I wondered for a moment, then I put the thought out of my mind. I counted the stitches on my knitting, focused on my work, and forgot about the lodger entirely. Life carried on as usual. One morning, however, the lodger came into our room. He had come to ask Grandmother about her promise to have his rooms repapered. The conversation started about wallpaper, but soon drifted to other topics.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'but that was all i did i wondered for a moment then i put the thought out of my mind i counted the stitches on my knitting focused on my work and forgot about the lodger entirely life carried on as usual one morning however the lodger came into our room he had come to ask grandmother about her promise to have his rooms repapered the conversation started about wallpaper but soon drifted to other topics', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 13, NULL, 'Grandmother, being naturally talkative, kept the conversation going. At one point she said, "Nastenka, go into my bedroom and bring me my reckoner." I jumped up immediately, eager to fetch it for her, but in my hurry I completely forgot that my dress was still pinned to hers. I blushed furiously, not knowing why, and instead of quietly undoing the pin so that the lodger wouldn''t notice, I leapt up so quickly that Grandmother''s chair shifted.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'grandmother being naturally talkative kept the conversation going at one point she said nastenka go into my bedroom and bring me my reckoner i jumped up immediately eager to fetch it for her but in my hurry i completely forgot that my dress was still pinned to hers i blushed furiously not knowing why and instead of quietly undoing the pin so that the lodger wouldnt notice i leapt up so quickly that grandmothers chair shifted', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 14, NULL, 'The lodger''s eyes widened slightly, and in that instant he realized the full extent of my predicament. When it dawned on me that he now knew everything, that he understood the ridiculous situation I was in, I froze. I stood as still as a statue, unable to move, my face burning with embarrassment. And then, to my utter horror, I felt tears welling up in my eyes. I didn''t know where to look, didn''t know what to do.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'the lodgers eyes widened slightly and in that instant he realized the full extent of my predicament when it dawned on me that he now knew everything that he understood the ridiculous situation i was in i froze i stood as still as a statue unable to move my face burning with embarrassment and then to my utter horror i felt tears welling up in my eyes i didnt know where to look didnt know what to do', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 15, NULL, 'Grandmother, unaware of what was happening, called out again, "What are you waiting for?" But her words only made things worse. The tears began falling freely, and I was completely overcome with shame and misery. I felt as though I would sink into the floor if I could. The lodger, seeing how distraught I was, must have felt sorry for me. Without a word he gave a polite bow and left the room quietly.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'grandmother unaware of what was happening called out again what are you waiting for but her words only made things worse the tears began falling freely and i was completely overcome with shame and misery i felt as though i would sink into the floor if i could the lodger seeing how distraught i was must have felt sorry for me without a word he gave a polite bow and left the room quietly', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 16, NULL, 'His kindness only deepened my embarrassment. After that, I became terrified of hearing the slightest sound in the hallway. Every creak or shuffle of footsteps made my heart race, and I would immediately think, "It''s him, the lodger!" I would frantically undo the pin, just in case I needed to escape quickly, but it never was him. Day after day passed, and he didn''t come back. A whole fortnight went by without any sign of him.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'his kindness only deepened my embarrassment after that i became terrified of hearing the slightest sound in the hallway every creak or shuffle of footsteps made my heart race and i would immediately think its him the lodger i would frantically undo the pin just in case i needed to escape quickly but it never was him day after day passed and he didnt come back a whole fortnight went by without any sign of him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 17, NULL, 'Then one day he sent a message through Fekla. He told her he had a large collection of French books, good, worthwhile books, and that I might like to borrow them so I wouldn''t get bored. He added that Grandmother might approve of this, and he hoped it would help pass the time. When Fekla delivered the message, Grandmother, as always, was cautious. She accepted his kind offer with gratitude, but immediately began asking questions.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'then one day he sent a message through fekla he told her he had a large collection of french books good worthwhile books and that i might like to borrow them so i wouldnt get bored he added that grandmother might approve of this and he hoped it would help pass the time when fekla delivered the message grandmother as always was cautious she accepted his kind offer with gratitude but immediately began asking questions', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 18, NULL, '"Are the books moral?" she asked. "Because if they''re not moral, then it''s out of the question. You mustn''t read anything improper, Nastenka. People learn terrible things from such books." "What terrible things, Grandmother?" I asked. "What could possibly be in them?" "Oh, plenty," Grandmother said gravely. "These books are full of stories about how young men seduce innocent, virtuous girls. They pretend to love them, promise to marry them, and then whisk them away from their parents'' homes, but once they''ve ruined the poor girls'' reputations, they abandon them, leaving them to suffer the most pitiful fates." "I''ve read many books like that myself," she added, almost as an afterthought, "and I must say, they''re written so vividly that you can''t help but stay up all night reading them.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'are the books moral she asked because if theyre not moral then its out of the question you mustnt read anything improper nastenka people learn terrible things from such books what terrible things grandmother i asked what could possibly be in them oh plenty grandmother said gravely these books are full of stories about how young men seduce innocent virtuous girls they pretend to love them promise to marry them and then whisk them away from their parents homes but once theyve ruined the poor girls reputations they abandon them leaving them to suffer the most pitiful fates ive read many books like that myself she added almost as an afterthought and i must say theyre written so vividly that you cant help but stay up all night reading them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 19, NULL, 'Of course, I read them on the sly," she admitted with a sly little smile. "But you, Nastenka, mustn''t read such things. What books has he sent you, anyway?" "They''re all Walter Scott novels, Grandmother," I replied. "Walter Scott''s novels?" she repeated thoughtfully. "Well, those sound proper enough. But wait, are you sure he hasn''t hidden anything inside them? These young men can be crafty. Have you checked to see if there''s a love letter tucked inside the pages?" "No, Grandmother, there''s no love letter," I assured her.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'of course i read them on the sly she admitted with a sly little smile but you nastenka mustnt read such things what books has he sent you anyway theyre all walter scott novels grandmother i replied walter scotts novels she repeated thoughtfully well those sound proper enough but wait are you sure he hasnt hidden anything inside them these young men can be crafty have you checked to see if theres a love letter tucked inside the pages no grandmother theres no love letter i assured her', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 20, NULL, '"Hmm," she said, unconvinced, "have you looked under the binding? Sometimes they slip things under the binding, those rascals." "No, Grandmother," I said again, "there''s nothing under the binding." "Well, then," she finally conceded, "if you''re sure, that''s all right." So we began reading Walter Scott, and within a month or so we had made our way through almost half of the novels he''d sent us. Then more books began to arrive.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'hmm she said unconvinced have you looked under the binding sometimes they slip things under the binding those rascals no grandmother i said again theres nothing under the binding well then she finally conceded if youre sure thats all right so we began reading walter scott and within a month or so we had made our way through almost half of the novels hed sent us then more books began to arrive', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 21, NULL, 'He sent us Pushkin as well, and soon enough I couldn''t imagine my days without a book. I left behind my childish daydreams of marrying a Chinese prince, for now the stories I read filled my mind with far richer and more vivid fantasies. That''s how things were when one day, quite by chance, I encountered our lodger on the stairs. Grandmother had sent me to fetch something, and I was hurrying down when I saw him coming up.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'he sent us pushkin as well and soon enough i couldnt imagine my days without a book i left behind my childish daydreams of marrying a chinese prince for now the stories i read filled my mind with far richer and more vivid fantasies thats how things were when one day quite by chance i encountered our lodger on the stairs grandmother had sent me to fetch something and i was hurrying down when i saw him coming up', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 22, NULL, 'As we passed, he stopped, and for a moment neither of us spoke. I blushed, he blushed. Then he broke the silence with a friendly laugh, greeted me with a cheerful, "Good morning," and asked how Grandmother was doing. "Well," he added, "have you been reading the books I sent?" I nodded and said that I had. "Which ones did you like best?" he asked. "Ivanhoe," I answered, "and Pushkin, most of all." That was the extent of our conversation that time.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'as we passed he stopped and for a moment neither of us spoke i blushed he blushed then he broke the silence with a friendly laugh greeted me with a cheerful good morning and asked how grandmother was doing well he added have you been reading the books i sent i nodded and said that i had which ones did you like best he asked ivanhoe i answered and pushkin most of all that was the extent of our conversation that time', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 23, NULL, 'I hurried away, feeling both shy and strangely pleased, while he continued on his way upstairs. A week later I ran into him again, this time in much the same place. Only this time Grandmother hadn''t sent me on an errand. I had gone downstairs of my own accord to fetch something. It was just past two, and I knew from habit that this was the hour he usually returned home.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'i hurried away feeling both shy and strangely pleased while he continued on his way upstairs a week later i ran into him again this time in much the same place only this time grandmother hadnt sent me on an errand i had gone downstairs of my own accord to fetch something it was just past two and i knew from habit that this was the hour he usually returned home', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 24, NULL, '"Good afternoon," he said, as he stopped on the stairs. "Good afternoon," I replied, trying to keep my voice steady. "Aren''t you bored?" he asked, "sitting with your Grandmother all day long?" When he said this, I felt an immediate rush of embarrassment. I didn''t know why. Perhaps it was because I felt as though he had touched on a sensitive subject, one that others had already whispered about. It wasn''t the first time someone had hinted that my life was dull or limited, and though I didn''t like hearing it, I couldn''t deny there was truth in the question.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'good afternoon he said as he stopped on the stairs good afternoon i replied trying to keep my voice steady arent you bored he asked sitting with your grandmother all day long when he said this i felt an immediate rush of embarrassment i didnt know why perhaps it was because i felt as though he had touched on a sensitive subject one that others had already whispered about it wasnt the first time someone had hinted that my life was dull or limited and though i didnt like hearing it i couldnt deny there was truth in the question', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 25, NULL, 'I felt both ashamed and offended, but I also found myself rooted to the spot, unable to walk away. "Listen," he said gently, "you''re a good girl. Forgive me for speaking so directly, but I truly want what''s best for you, just as much as your Grandmother does. Don''t you have any friends you could visit, someone to talk to or spend time with?" I told him the truth.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'i felt both ashamed and offended but i also found myself rooted to the spot unable to walk away listen he said gently youre a good girl forgive me for speaking so directly but i truly want whats best for you just as much as your grandmother does dont you have any friends you could visit someone to talk to or spend time with i told him the truth', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 26, NULL, '"I don''t have any friends now," I said. "I used to have one, Mashenka, but she moved away to Pskov." "I see," he said thoughtfully. Then, after a pause, he added, "Would you like to go to the theatre with me sometime?" "The theatre?" I repeated, startled. "But what about Grandmother?" "You''d have to go without telling her," he said with a quiet smile. "No," I said firmly, "I don''t want to deceive Grandmother.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'i dont have any friends now i said i used to have one mashenka but she moved away to pskov i see he said thoughtfully then after a pause he added would you like to go to the theatre with me sometime the theatre i repeated startled but what about grandmother youd have to go without telling her he said with a quiet smile no i said firmly i dont want to deceive grandmother', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 27, NULL, 'Good-bye." "Good-bye," he replied, and though he said nothing more, there was something in his voice that lingered with me, even after he was gone. Later that day, after dinner, he came to see us in our little sitting room. He stayed for quite a while talking to Grandmother about this and that, asking her questions about her life and habits. At one point he casually asked if she ever went out, if she had acquaintances or places she liked to visit.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'good bye good bye he replied and though he said nothing more there was something in his voice that lingered with me even after he was gone later that day after dinner he came to see us in our little sitting room he stayed for quite a while talking to grandmother about this and that asking her questions about her life and habits at one point he casually asked if she ever went out if she had acquaintances or places she liked to visit', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 28, NULL, 'Grandmother shook her head, laughing, and said she was too old for such things now. Then, quite suddenly, he said, "I''ve taken a box at the opera for tonight. They''re performing The Barber of Seville. My friends were supposed to join me, but they''ve cancelled, and now the ticket is going to waste." "The Barber of Seville!" Grandmother exclaimed, her face lighting up with interest. "Why, that''s the very same one they performed in the old days." "Yes," he said with a smile, glancing briefly at me.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'grandmother shook her head laughing and said she was too old for such things now then quite suddenly he said ive taken a box at the opera for tonight theyre performing the barber of seville my friends were supposed to join me but theyve cancelled and now the ticket is going to waste the barber of seville grandmother exclaimed her face lighting up with interest why thats the very same one they performed in the old days yes he said with a smile glancing briefly at me', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 29, NULL, '"It''s the same barber." I could feel my face burning. I knew what he meant by that glance, and my heart began pounding in suspense. I kept my eyes on the floor, not daring to look up. But I could feel Grandmother''s excitement growing. "To think of it," she said, "I once played Rosina myself in a private performance. That was many, many years ago." "Then perhaps you''d like to go to-night," the lodger suggested.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'its the same barber i could feel my face burning i knew what he meant by that glance and my heart began pounding in suspense i kept my eyes on the floor not daring to look up but i could feel grandmothers excitement growing to think of it she said i once played rosina myself in a private performance that was many many years ago then perhaps youd like to go to night the lodger suggested', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 30, NULL, '"It would be a shame for the ticket to go unused." "By all means, let''s go," Grandmother declared with enthusiasm. "Why shouldn''t we? And besides, my Nastenka here has never been to the theatre in her life." My goodness, what joy! As soon as the plan was decided, we began getting ready, without delay. Grandmother and I put on our very best clothes. Even though she couldn''t see, she was eager to hear the music, and I could tell she was just as excited as I was, though for a different reason.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'it would be a shame for the ticket to go unused by all means lets go grandmother declared with enthusiasm why shouldnt we and besides my nastenka here has never been to the theatre in her life my goodness what joy as soon as the plan was decided we began getting ready without delay grandmother and i put on our very best clothes even though she couldnt see she was eager to hear the music and i could tell she was just as excited as i was though for a different reason', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 31, NULL, 'She was a kind and selfless soul, my Grandmother, and what mattered most to her was that I had the chance to enjoy myself. She would never have gone to the theatre on her own, but knowing it would bring me happiness she agreed without hesitation. As for me, I could hardly contain my excitement. The anticipation alone was thrilling. When we finally arrived at the theatre and took our seats, I could scarcely focus on anything around me.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'she was a kind and selfless soul my grandmother and what mattered most to her was that i had the chance to enjoy myself she would never have gone to the theatre on her own but knowing it would bring me happiness she agreed without hesitation as for me i could hardly contain my excitement the anticipation alone was thrilling when we finally arrived at the theatre and took our seats i could scarcely focus on anything around me', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 32, NULL, 'The lights, the crowd, the atmosphere, it was all so overwhelming and magical. What my impressions of the Barber of Seville were, I won''t even attempt to describe. The music, the performance, the characters, it felt like I had stepped into an entirely new world. But what stood out even more to me that evening was the way our lodger behaved. He looked at me so kindly, spoke so warmly, that it was impossible to mistake his intentions.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'the lights the crowd the atmosphere it was all so overwhelming and magical what my impressions of the barber of seville were i wont even attempt to describe the music the performance the characters it felt like i had stepped into an entirely new world but what stood out even more to me that evening was the way our lodger behaved he looked at me so kindly spoke so warmly that it was impossible to mistake his intentions', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 33, NULL, 'I realized then that his suggestion that morning, that I should go to the theatre with him alone, had been a test, a way of gauging my character, and knowing that made me feel proud, like I had passed some unspoken challenge. That night, as I lay in bed, I was brimming with happiness. My heart was beating so fast that I thought I might have a fever. I couldn''t stop thinking about the performance, replaying every moment of it in my mind.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'i realized then that his suggestion that morning that i should go to the theatre with him alone had been a test a way of gauging my character and knowing that made me feel proud like i had passed some unspoken challenge that night as i lay in bed i was brimming with happiness my heart was beating so fast that i thought i might have a fever i couldnt stop thinking about the performance replaying every moment of it in my mind', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 34, NULL, 'All night long I dreamed of the Barber of Seville, and when I woke the next morning it felt as though I were still under its spell. Naturally, I expected that after such a delightful evening, the lodger would start visiting us more often. But to my disappointment, that wasn''t what happened at all. He seemed to grow even more distant. He only came by about once a month, and even then it was only to invite us to the theatre again.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'all night long i dreamed of the barber of seville and when i woke the next morning it felt as though i were still under its spell naturally i expected that after such a delightful evening the lodger would start visiting us more often but to my disappointment that wasnt what happened at all he seemed to grow even more distant he only came by about once a month and even then it was only to invite us to the theatre again', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 35, NULL, 'We went twice more, but by then my joy had started to wane. I began to feel that he didn''t truly care for me, that his kindness was only out of pity for my situation. He saw how strictly Grandmother treated me, and that was the extent of his feelings, sympathy, nothing more. As time passed, I grew restless. I couldn''t focus on anything, not my reading, not my knitting, not even my conversations with Grandmother.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'we went twice more but by then my joy had started to wane i began to feel that he didnt truly care for me that his kindness was only out of pity for my situation he saw how strictly grandmother treated me and that was the extent of his feelings sympathy nothing more as time passed i grew restless i couldnt focus on anything not my reading not my knitting not even my conversations with grandmother', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 36, NULL, 'Some days I found myself laughing uncontrollably, doing silly things just to provoke a reaction from her. Other days I would break down in tears for no apparent reason. My emotions were all over the place, and I couldn''t make sense of them. I began to lose weight and felt constantly on edge, as though something inside me was about to break. When the opera season ended, the lodger stopped coming to see us entirely.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'some days i found myself laughing uncontrollably doing silly things just to provoke a reaction from her other days i would break down in tears for no apparent reason my emotions were all over the place and i couldnt make sense of them i began to lose weight and felt constantly on edge as though something inside me was about to break when the opera season ended the lodger stopped coming to see us entirely', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 37, NULL, 'The only times I saw him were by chance, on the stairs. Each time he would bow silently, gravely, as if trying to avoid any unnecessary interaction. He would continue on his way, and I would stand there, rooted to the spot, my face burning red with embarrassment, my heart pounding as though it might burst. Then came the end. It was exactly a year ago, in May, when the lodger came to us with the news.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'the only times i saw him were by chance on the stairs each time he would bow silently gravely as if trying to avoid any unnecessary interaction he would continue on his way and i would stand there rooted to the spot my face burning red with embarrassment my heart pounding as though it might burst then came the end it was exactly a year ago in may when the lodger came to us with the news', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 38, NULL, 'He told Grandmother that his business in Petersburg was finished, and that he would be returning to Moscow for a year. As soon as I heard those words, I felt the ground shift beneath me. My legs gave out, and I sank into a chair, barely able to breathe. Grandmother of course noticed nothing. She simply listened politely as he explained his plans, and when he finished, he bowed and left the room.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'he told grandmother that his business in petersburg was finished and that he would be returning to moscow for a year as soon as i heard those words i felt the ground shift beneath me my legs gave out and i sank into a chair barely able to breathe grandmother of course noticed nothing she simply listened politely as he explained his plans and when he finished he bowed and left the room', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 39, NULL, 'I was devastated. What was I to do? I thought and thought, turning everything over in my mind, but nothing made sense. I felt trapped, helpless, as though my world were collapsing around me. Finally, I made up my mind. The next day, he was to leave, and I resolved to take action that very evening, after Grandmother had gone to bed. So it happened. I gathered all my clothes, packed the linen I would need, and tied everything into a bundle.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'i was devastated what was i to do i thought and thought turning everything over in my mind but nothing made sense i felt trapped helpless as though my world were collapsing around me finally i made up my mind the next day he was to leave and i resolved to take action that very evening after grandmother had gone to bed so it happened i gathered all my clothes packed the linen i would need and tied everything into a bundle', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 40, NULL, 'With the parcel in hand, I climbed the stairs to his room, more dead than alive. My heart was pounding so violently that I thought I might faint. I stood outside his door for what felt like an eternity, unable to summon the courage to knock. When I finally opened the door and stepped inside, he turned to look at me. His face went pale, and he cried out in shock.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'with the parcel in hand i climbed the stairs to his room more dead than alive my heart was pounding so violently that i thought i might faint i stood outside his door for what felt like an eternity unable to summon the courage to knock when i finally opened the door and stepped inside he turned to look at me his face went pale and he cried out in shock', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 41, NULL, 'He thought I was a ghost. Rushing to my side, he fetched a glass of water, for I could barely stand. My head was spinning, and I felt as though I were about to collapse. When I finally recovered enough to speak, I placed my parcel on his bed, sat down beside it, and buried my face in my hands. Tears poured from my eyes in a torrent, and I couldn''t stop myself.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'he thought i was a ghost rushing to my side he fetched a glass of water for i could barely stand my head was spinning and i felt as though i were about to collapse when i finally recovered enough to speak i placed my parcel on his bed sat down beside it and buried my face in my hands tears poured from my eyes in a torrent and i couldnt stop myself', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 42, NULL, 'I cried as though my heart were breaking, and in a way it was. I think he understood everything in that moment. He didn''t need me to explain. He looked at me with such sadness, such quiet regret, that it tore at my heart even more. Listen, he said gently. Listen, Nastenka. I can''t do anything. I am a poor man. I have nothing, not even a proper job. How could we live if I were to marry you?', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'i cried as though my heart were breaking and in a way it was i think he understood everything in that moment he didnt need me to explain he looked at me with such sadness such quiet regret that it tore at my heart even more listen he said gently listen nastenka i cant do anything i am a poor man i have nothing not even a proper job how could we live if i were to marry you', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 43, NULL, 'We talked for a long time. I poured my heart out, telling him that I couldn''t bear living with Grandmother any longer, that I felt like I was suffocating, that I would rather run away than go on like this. I even said that I would follow him to Moscow if only he would let me. Shame, pride, and love were all swirling within me, clashing and fighting for control.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'we talked for a long time i poured my heart out telling him that i couldnt bear living with grandmother any longer that i felt like i was suffocating that i would rather run away than go on like this i even said that i would follow him to moscow if only he would let me shame pride and love were all swirling within me clashing and fighting for control', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 44, NULL, 'At last, I collapsed onto the bed, overcome with emotion, trembling with fear at the thought of his refusal. He sat in silence for several minutes. Then, at last, he stood, walked over to me, and took my hand. Listen, my dear, good Nastenka. Listen to me, he said, his voice soft yet filled with urgency. I swear to you that if I am ever in a position to marry, you will be the one to make me happy.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'at last i collapsed onto the bed overcome with emotion trembling with fear at the thought of his refusal he sat in silence for several minutes then at last he stood walked over to me and took my hand listen my dear good nastenka listen to me he said his voice soft yet filled with urgency i swear to you that if i am ever in a position to marry you will be the one to make me happy', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 45, NULL, 'I assure you truly that right now you are the only person who could bring joy into my life. But listen, Nastenka, I must go to Moscow. I''ll be there for a year, and during that time I hope to improve my circumstances, to establish myself properly. When I return, if you still love me, I swear to you that we will be happy. I will make sure of it, but right now it''s impossible.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'i assure you truly that right now you are the only person who could bring joy into my life but listen nastenka i must go to moscow ill be there for a year and during that time i hope to improve my circumstances to establish myself properly when i return if you still love me i swear to you that we will be happy i will make sure of it but right now its impossible', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 46, NULL, 'I simply can''t do it. I don''t have the means, nor do I have the right to make any promises I might not be able to keep. Still, I repeat, if it doesn''t happen within a year, it will certainly happen at some point. That is, of course, only if you don''t prefer someone else during that time. I could never ask you to bind yourself to me with any sort of promise, and I wouldn''t dare try.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'i simply cant do it i dont have the means nor do i have the right to make any promises i might not be able to keep still i repeat if it doesnt happen within a year it will certainly happen at some point that is of course only if you dont prefer someone else during that time i could never ask you to bind yourself to me with any sort of promise and i wouldnt dare try', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 47, NULL, 'I want you to be free to choose. That was what he said to me, and the very next day he left for Moscow. We agreed between us not to say a word to grandmother. That was his idea, his wish, and so the matter was left as it was. Well, she continued, her voice softening with a mixture of sadness and resignation, that''s almost the end of my story.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'i want you to be free to choose that was what he said to me and the very next day he left for moscow we agreed between us not to say a word to grandmother that was his idea his wish and so the matter was left as it was well she continued her voice softening with a mixture of sadness and resignation thats almost the end of my story', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 48, NULL, 'A whole year has passed now. He has come back. He''s been in Petersburg for three days already, and—and—and what? I interrupted eagerly, unable to contain my impatience. What happened? Has he come to see you? And up to now he hasn''t shown himself, she answered, summoning all her courage to get the words out. Her voice trembled, and it seemed as though even saying it aloud caused her pain.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'a whole year has passed now he has come back hes been in petersburg for three days already and and and what i interrupted eagerly unable to contain my impatience what happened has he come to see you and up to now he hasnt shown himself she answered summoning all her courage to get the words out her voice trembled and it seemed as though even saying it aloud caused her pain', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 49, NULL, 'There''s been no sign, no word from him. She stopped there, as though the weight of her emotions had become too much to bear. For a moment she sat still, her head bowed. Then, suddenly, she buried her face in her hands and broke into such uncontrollable sobs that it sent a pang straight through my heart. I hadn''t expected this. I had thought her story would end differently, more happily.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'theres been no sign no word from him she stopped there as though the weight of her emotions had become too much to bear for a moment she sat still her head bowed then suddenly she buried her face in her hands and broke into such uncontrollable sobs that it sent a pang straight through my heart i hadnt expected this i had thought her story would end differently more happily', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 50, NULL, 'The sight of her despair was almost too much for me to bear. Nastenka, I began timidly, trying to keep my voice gentle and soothing. Nastenka, please don''t cry. How can you be so sure? Maybe he hasn''t arrived yet. Perhaps there''s been a delay. No, no, he''s here. He''s already here, she interrupted, her voice choked with tears. I know he is. We made an agreement that evening before he left.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'the sight of her despair was almost too much for me to bear nastenka i began timidly trying to keep my voice gentle and soothing nastenka please dont cry how can you be so sure maybe he hasnt arrived yet perhaps theres been a delay no no hes here hes already here she interrupted her voice choked with tears i know he is we made an agreement that evening before he left', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 51, NULL, 'We agreed on everything. We came here, to this very embankment, after we talked that night. It was ten o''clock, and we sat on this bench. I wasn''t crying then. I felt so hopeful, so happy to hear everything he said, and he told me that as soon as he arrived back in Petersburg, he would come to see me. He said that if I didn''t refuse him, then we would tell grandmother everything.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'we agreed on everything we came here to this very embankment after we talked that night it was ten oclock and we sat on this bench i wasnt crying then i felt so hopeful so happy to hear everything he said and he told me that as soon as he arrived back in petersburg he would come to see me he said that if i didnt refuse him then we would tell grandmother everything', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 52, NULL, 'But now he''s here, and he hasn''t come, he hasn''t come, and I don''t understand why. She broke into tears again, her shoulders shaking as she tried to stifle her sobs. Good God, Nastenka! There must be something I can do to help, I exclaimed, jumping up from the bench in sheer desperation. Tell me, tell me, Nastenka, wouldn''t it be possible for me to go to him, to speak to him on your behalf?', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'but now hes here and he hasnt come he hasnt come and i dont understand why she broke into tears again her shoulders shaking as she tried to stifle her sobs good god nastenka there must be something i can do to help i exclaimed jumping up from the bench in sheer desperation tell me tell me nastenka wouldnt it be possible for me to go to him to speak to him on your behalf', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 53, NULL, 'Could you really do that, she asked suddenly, raising her head and looking at me with a glimmer of hope in her tear-filled eyes. No, no, I said, quickly pulling myself back to reality. Of course not, it''s impossible. But I''ll tell you what, you could write him a letter. A letter, she repeated, shaking her head as her hope faded. No, that''s impossible, I can''t do that. But why not, I insisted, clinging to my idea.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'could you really do that she asked suddenly raising her head and looking at me with a glimmer of hope in her tear filled eyes no no i said quickly pulling myself back to reality of course not its impossible but ill tell you what you could write him a letter a letter she repeated shaking her head as her hope faded no thats impossible i cant do that but why not i insisted clinging to my idea', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 54, NULL, 'Why can''t you write him a letter? It depends on the letter, Nastenka. There are ways to write such letters. Trust me, please, trust me, I wouldn''t give you bad advice. It can be done. You''ve already taken the first step once. Why not now? I can''t, she said firmly, lowering her head again. I just can''t. It would feel as though I were forcing myself on him. Ah, my dear, sweet Nastenka, I said, barely able to hide a small smile.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'why cant you write him a letter it depends on the letter nastenka there are ways to write such letters trust me please trust me i wouldnt give you bad advice it can be done youve already taken the first step once why not now i cant she said firmly lowering her head again i just cant it would feel as though i were forcing myself on him ah my dear sweet nastenka i said barely able to hide a small smile', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 55, NULL, 'No, no, you have every right to reach out to him. Think about it. He made you a promise. He told you that if he married anyone it would be you. He even gave you the freedom to refuse him, didn''t he? That shows he''s a man of delicate feeling, someone who cares about doing what''s right. Under the circumstances, you have every right to take the first step. In fact, you''re in a privileged position.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'no no you have every right to reach out to him think about it he made you a promise he told you that if he married anyone it would be you he even gave you the freedom to refuse him didnt he that shows hes a man of delicate feeling someone who cares about doing whats right under the circumstances you have every right to take the first step in fact youre in a privileged position', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 56, NULL, 'You can even free him from his promise if you feel it''s necessary. I paused, letting my words sink in. Don''t you see, Nastenka? You have nothing to lose and everything to gain. Listen, how would you write it? she asked suddenly, her voice trembling slightly with a mix of uncertainty and determination. Write what? I asked, though I already had an idea of what she meant. This letter, she clarified, looking at me with wide expectant eyes.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'you can even free him from his promise if you feel its necessary i paused letting my words sink in dont you see nastenka you have nothing to lose and everything to gain listen how would you write it she asked suddenly her voice trembling slightly with a mix of uncertainty and determination write what i asked though i already had an idea of what she meant this letter she clarified looking at me with wide expectant eyes', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 57, NULL, 'I hesitated for a moment, then nodded. I''ll tell you how I''d write it. Begin with, Dear Sir. Must I really start it like that? she interrupted, frowning slightly. Dear Sir? Is that how it should begin? Yes, you certainly must, I replied with confidence, though almost immediately I wavered. Though after all, I''m not entirely sure. Perhaps it depends. Maybe you could start differently if you feel it suits you better.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'i hesitated for a moment then nodded ill tell you how id write it begin with dear sir must i really start it like that she interrupted frowning slightly dear sir is that how it should begin yes you certainly must i replied with confidence though almost immediately i wavered though after all im not entirely sure perhaps it depends maybe you could start differently if you feel it suits you better', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 58, NULL, 'Well, well, go on, she urged, leaning forward eagerly. What comes next? Dear Sir, I began again, trying to compose the rest of the letter in my mind. I must apologize for—no, wait, that doesn''t seem right. There''s no need to apologize. The very fact that you''re writing justifies itself. Apologies would only weaken the point. Write simply, plainly, like this. I am writing to you, forgive me my impatience, but I have lived a whole year in hope, and that hope has sustained me.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'well well go on she urged leaning forward eagerly what comes next dear sir i began again trying to compose the rest of the letter in my mind i must apologize for no wait that doesnt seem right theres no need to apologize the very fact that youre writing justifies itself apologies would only weaken the point write simply plainly like this i am writing to you forgive me my impatience but i have lived a whole year in hope and that hope has sustained me', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 59, NULL, 'Am I to blame if I cannot bear even a single day of doubt now that you are here? If by any chance your feelings have changed, this letter is not to reproach you or to plead. It is only to tell you that I do not hold you responsible, nor do I blame you. How could I, when I have no power over your heart? Such is my fate.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'am i to blame if i cannot bear even a single day of doubt now that you are here if by any chance your feelings have changed this letter is not to reproach you or to plead it is only to tell you that i do not hold you responsible nor do i blame you how could i when i have no power over your heart such is my fate', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 60, NULL, 'I know you to be an honorable man. You will not ridicule or grow angry over these lines, written in such haste and emotion. Please remember that they come from a poor girl who is entirely alone, who has no one to guide her or advise her, and who has always struggled to control her heart. If a shadow of doubt has crept into my heart, forgive me for it.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'i know you to be an honorable man you will not ridicule or grow angry over these lines written in such haste and emotion please remember that they come from a poor girl who is entirely alone who has no one to guide her or advise her and who has always struggled to control her heart if a shadow of doubt has crept into my heart forgive me for it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 61, NULL, 'I know you are not capable of offending, even in thought, someone who has loved you so deeply and continues to love you still. I stopped and glanced at her. Nastenka''s face had lit up with joy, her eyes sparkling with excitement. She clapped her hands together and exclaimed, Yes, yes, that''s exactly what I was thinking. Oh, you''ve solved everything for me. God has truly sent you to me.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'i know you are not capable of offending even in thought someone who has loved you so deeply and continues to love you still i stopped and glanced at her nastenkas face had lit up with joy her eyes sparkling with excitement she clapped her hands together and exclaimed yes yes thats exactly what i was thinking oh youve solved everything for me god has truly sent you to me', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 62, NULL, 'Thank you, thank you. I couldn''t help but smile at her enthusiasm. Thank me? What for? For God sending me your way? I asked, half teasing, but entirely delighted by the happiness in her expression. Yes, for that too, she replied with a playful laugh, her cheeks glowing with warmth. Ah, Nastenka, I said, my voice softening. There are moments in life when one feels grateful simply for existing at the same time as someone else.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'thank you thank you i couldnt help but smile at her enthusiasm thank me what for for god sending me your way i asked half teasing but entirely delighted by the happiness in her expression yes for that too she replied with a playful laugh her cheeks glowing with warmth ah nastenka i said my voice softening there are moments in life when one feels grateful simply for existing at the same time as someone else', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 63, NULL, 'I thank you, not just for meeting me, but for giving me something I''ll remember for the rest of my life. She smiled at that, but quickly waved her hand as though brushing away my words. Enough, enough of that. Listen now. Let me tell you what we agreed upon that night before he left. We decided that as soon as he returned, he would let me know by leaving a letter with some good, trustworthy people I know, people who know nothing of the situation.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'i thank you not just for meeting me but for giving me something ill remember for the rest of my life she smiled at that but quickly waved her hand as though brushing away my words enough enough of that listen now let me tell you what we agreed upon that night before he left we decided that as soon as he returned he would let me know by leaving a letter with some good trustworthy people i know people who know nothing of the situation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 64, NULL, 'Or if writing a letter was impossible, since letters can''t always say everything, he promised to meet me here, at this very spot, at ten o''clock on the day he arrived. I know he''s already back, I feel it. But now it''s been three days and there''s still no sign of him, no letter, no message, nothing. And it''s impossible for me to leave grandmother alone in the mornings. So please, here''s what I need you to do.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'or if writing a letter was impossible since letters cant always say everything he promised to meet me here at this very spot at ten oclock on the day he arrived i know hes already back i feel it but now its been three days and theres still no sign of him no letter no message nothing and its impossible for me to leave grandmother alone in the mornings so please heres what i need you to do', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 65, NULL, 'Take my letter to those kind people I mentioned. They''ll send it on to him. If he replies, bring his answer here tomorrow at ten o''clock. I hesitated for a moment, thinking through the logistics of her request. But the letter—I said—you have to write the letter first. That might delay things, so, perhaps, everything will have to wait until the day after tomorrow. The letter—Nastenka repeated, her voice faltering slightly as a flicker of uncertainty crossed her face.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'take my letter to those kind people i mentioned theyll send it on to him if he replies bring his answer here tomorrow at ten oclock i hesitated for a moment thinking through the logistics of her request but the letter i said you have to write the letter first that might delay things so perhaps everything will have to wait until the day after tomorrow the letter nastenka repeated her voice faltering slightly as a flicker of uncertainty crossed her face', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 66, NULL, 'She looked down, fiddling nervously with her hands. The letter— But— She trailed off, leaving her thoughts unfinished. But she didn''t finish her sentence. Instead, she quickly turned her face away from me, her cheeks flushing the deepest pink, as though a rose had bloomed upon her skin. For a moment she hesitated, and then, without a word, I felt something soft pressed into my hand. Looking down, I realized it was a letter—sealed, prepared, and clearly written long before.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'she looked down fiddling nervously with her hands the letter but she trailed off leaving her thoughts unfinished but she didnt finish her sentence instead she quickly turned her face away from me her cheeks flushing the deepest pink as though a rose had bloomed upon her skin for a moment she hesitated and then without a word i felt something soft pressed into my hand looking down i realized it was a letter sealed prepared and clearly written long before', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 67, NULL, 'She must have carried it with her all this time, ready for this moment, though perhaps unsure whether she would have the courage to hand it over. As I stood there, a familiar, sweet memory swept over me. A thought that seemed as if it had sprung to life from some tender corner of my imagination surfaced unbidden. I couldn''t help myself. With a mischievous grin I began softly, R-O-R-O-S-I-C-N-A-N-A.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'she must have carried it with her all this time ready for this moment though perhaps unsure whether she would have the courage to hand it over as i stood there a familiar sweet memory swept over me a thought that seemed as if it had sprung to life from some tender corner of my imagination surfaced unbidden i couldnt help myself with a mischievous grin i began softly r o r o s i c n a n a', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 68, NULL, 'Rosina! we both burst out together, humming the name in unison. The laughter that followed seemed to fill the quiet street, mingling with the soft evening air. In my delight I came close to embracing her, swept up in the shared joy of that silly little moment. Her laughter mixed with mine, though her cheeks grew even redder and tears glistened at the corners of her eyes. They sparkled like tiny pearls against the dark curtain of her eyelashes, catching the faint light.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'rosina we both burst out together humming the name in unison the laughter that followed seemed to fill the quiet street mingling with the soft evening air in my delight i came close to embracing her swept up in the shared joy of that silly little moment her laughter mixed with mine though her cheeks grew even redder and tears glistened at the corners of her eyes they sparkled like tiny pearls against the dark curtain of her eyelashes catching the faint light', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 69, NULL, '"Enough, enough! Stop it now! she exclaimed, half laughing and half scolding, though her own voice betrayed her amusement. "Good-bye for now, she added hastily, as though trying to end the moment before her emotions got the better of her again. "Here''s the letter. Take it. And here''s the address where you''re to deliver it. Don''t forget. Good-bye, till we meet again. Till tomorrow. Her words tumbled out so quickly that I hardly had time to respond.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'enough enough stop it now she exclaimed half laughing and half scolding though her own voice betrayed her amusement good bye for now she added hastily as though trying to end the moment before her emotions got the better of her again heres the letter take it and heres the address where youre to deliver it dont forget good bye till we meet again till tomorrow her words tumbled out so quickly that i hardly had time to respond', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 70, NULL, 'Before I could say anything more, she pressed both my hands in hers with a warmth and sincerity that left me momentarily stunned. Her grip was firm, but her hands trembled slightly, as though she were both eager and afraid of what would come next. She gave me one last bright, fleeting smile, nodded her head quickly as if to reassure herself, and then turned and darted away. She moved so quickly, so gracefully, that she seemed almost to fly.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'before i could say anything more she pressed both my hands in hers with a warmth and sincerity that left me momentarily stunned her grip was firm but her hands trembled slightly as though she were both eager and afraid of what would come next she gave me one last bright fleeting smile nodded her head quickly as if to reassure herself and then turned and darted away she moved so quickly so gracefully that she seemed almost to fly', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 71, NULL, 'Like an arrow loosed from a bow, she vanished down the side street, her footsteps light and quick against the cobblestones. I stood there, rooted to the spot, unable to move, watching her retreating figure as it disappeared into the shadows. Even after she was gone, her voice lingered in my ears. "Till tomorrow. Till tomorrow. The words echoed, their warmth wrapping around me like a melody that refused to fade.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'like an arrow loosed from a bow she vanished down the side street her footsteps light and quick against the cobblestones i stood there rooted to the spot unable to move watching her retreating figure as it disappeared into the shadows even after she was gone her voice lingered in my ears till tomorrow till tomorrow the words echoed their warmth wrapping around me like a melody that refused to fade', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'nastenkas history', 'Nastenkas History', 72, NULL, 'I stood there for what felt like an eternity, staring at the empty street where she had just been, my heart full of something indescribable. And then, at last, I turned and began to make my way home, her letter clutched tightly in my hand.', '', NULL, NULL, NULL, NULL, 'white nights nastenkas history', 'i stood there for what felt like an eternity staring at the empty street where she had just been my heart full of something indescribable and then at last i turned and began to make my way home her letter clutched tightly in my hand', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'third night', 'Third Night', 0, NULL, 'Today has been a dreary, rain-soaked day, one without even the faintest trace of sunlight. It''s as though the sky itself is reflecting the gloom in my heart, the weight of thoughts pressing down on me like the clouds above. The rain feels endless like the old age that stretches out before me, colorless and joyless. My mind is restless, swarming with strange, unanswerable questions, each one darker and more oppressive than the last.', '', NULL, NULL, NULL, NULL, 'white nights third night', 'today has been a dreary rain soaked day one without even the faintest trace of sunlight its as though the sky itself is reflecting the gloom in my heart the weight of thoughts pressing down on me like the clouds above the rain feels endless like the old age that stretches out before me colorless and joyless my mind is restless swarming with strange unanswerable questions each one darker and more oppressive than the last', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'third night', 'Third Night', 1, NULL, 'These questions—so heavy, so impossible—seem to crowd my brain all at once, leaving me feeling powerless. I can''t bring myself to resolve them. Perhaps it''s not for me to settle such things. Perhaps they are meant to remain unanswered. Today we won''t meet. Yesterday, when we said good-bye, the sky was already changing. Clouds began to gather on the horizon, and a thin mist rose, veiling the city in a gray haze.', '', NULL, NULL, NULL, NULL, 'white nights third night', 'these questions so heavy so impossible seem to crowd my brain all at once leaving me feeling powerless i cant bring myself to resolve them perhaps its not for me to settle such things perhaps they are meant to remain unanswered today we wont meet yesterday when we said good bye the sky was already changing clouds began to gather on the horizon and a thin mist rose veiling the city in a gray haze', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'third night', 'Third Night', 2, NULL, 'I remember mentioning it as we parted, almost as if I could predict what was coming. Tomorrow will be a bad day, I had said. But she said nothing in return, refusing to acknowledge even the possibility of rain. For her, the world was too bright, too full of happiness to imagine otherwise. If it rains, we won''t see each other, she had said simply. I won''t come. I wanted to believe she wouldn''t notice the rain today, that her happiness would overpower any storm.', '', NULL, NULL, NULL, NULL, 'white nights third night', 'i remember mentioning it as we parted almost as if i could predict what was coming tomorrow will be a bad day i had said but she said nothing in return refusing to acknowledge even the possibility of rain for her the world was too bright too full of happiness to imagine otherwise if it rains we wont see each other she had said simply i wont come i wanted to believe she wouldnt notice the rain today that her happiness would overpower any storm', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'third night', 'Third Night', 3, NULL, 'But she hasn''t come. Yesterday was our third meeting, our third white night, a night so pure and fleeting, glowing with a light that seemed to promise eternity. And yet, here I am, alone. How radiant joy and happiness make a person, how it fills every corner of their being. Her heart was brimming yesterday, overflowing with love and excitement. You could see it in her every word, every gesture, every glance.', '', NULL, NULL, NULL, NULL, 'white nights third night', 'but she hasnt come yesterday was our third meeting our third white night a night so pure and fleeting glowing with a light that seemed to promise eternity and yet here i am alone how radiant joy and happiness make a person how it fills every corner of their being her heart was brimming yesterday overflowing with love and excitement you could see it in her every word every gesture every glance', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'third night', 'Third Night', 4, NULL, 'It was as if she wanted the whole world to share in her joy, to bask in her happiness. There was a warmth in her voice, a tenderness in her words that made me feel as though they were meant just for me. How solicitous, how kind she was yesterday. How she tried so earnestly to encourage me, to lift my spirits. Oh, the irresistible coquetry of happiness. How easily it deceives.', '', NULL, NULL, NULL, NULL, 'white nights third night', 'it was as if she wanted the whole world to share in her joy to bask in her happiness there was a warmth in her voice a tenderness in her words that made me feel as though they were meant just for me how solicitous how kind she was yesterday how she tried so earnestly to encourage me to lift my spirits oh the irresistible coquetry of happiness how easily it deceives', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'third night', 'Third Night', 5, NULL, 'While she laughed and spoke with such tenderness, I—I believed it all. I thought it was real, that it came from her heart, and that it was meant for me. But my God, how could I have been so blind? How could I have fooled myself so completely? How could I not have seen that everything I thought was mine—her kindness, her smiles, her gentle words—belonged to another? None of it was truly mine.', '', NULL, NULL, NULL, NULL, 'white nights third night', 'while she laughed and spoke with such tenderness i i believed it all i thought it was real that it came from her heart and that it was meant for me but my god how could i have been so blind how could i have fooled myself so completely how could i not have seen that everything i thought was mine her kindness her smiles her gentle words belonged to another none of it was truly mine', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'third night', 'Third Night', 6, NULL, 'Even her tenderness towards me, her attentiveness, her affectionate concern—yes, even what I dared to think of as her love for me was nothing but an extension of her own joy, a joy that didn''t originate from me, but from the thought of seeing someone else. I was nothing more than a bystander to her happiness, a piece of her world that she wished to include in her glowing anticipation of someone else.', '', NULL, NULL, NULL, NULL, 'white nights third night', 'even her tenderness towards me her attentiveness her affectionate concern yes even what i dared to think of as her love for me was nothing but an extension of her own joy a joy that didnt originate from me but from the thought of seeing someone else i was nothing more than a bystander to her happiness a piece of her world that she wished to include in her glowing anticipation of someone else', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'third night', 'Third Night', 7, NULL, 'When he didn''t come, when her hopes went unanswered, I saw her falter. The lightness in her step, the gaiety in her words—it all began to fade. Her laughter grew quieter, her movements more hesitant. And yet, strangely, she turned her attentiveness back to me, almost as if by instinct. It was as though, in the absence of her own happiness, she was trying to pass it on to me, to share what little she could still muster.', '', NULL, NULL, NULL, NULL, 'white nights third night', 'when he didnt come when her hopes went unanswered i saw her falter the lightness in her step the gaiety in her words it all began to fade her laughter grew quieter her movements more hesitant and yet strangely she turned her attentiveness back to me almost as if by instinct it was as though in the absence of her own happiness she was trying to pass it on to me to share what little she could still muster', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'third night', 'Third Night', 8, NULL, 'I saw then how deeply she was affected. My Nastenka—yes, I still dared to think of her as mine—was disheartened, dismayed, perhaps even heartbroken. I think in that moment she realized the truth—that I loved her. She saw my poor unspoken love reflected in my silence and in my eyes, and she felt sorry for me. When we are unhappy, it''s as though we become more attuned to the suffering of others, as though our own pain sharpens our ability to recognize it.', '', NULL, NULL, NULL, NULL, 'white nights third night', 'i saw then how deeply she was affected my nastenka yes i still dared to think of her as mine was disheartened dismayed perhaps even heartbroken i think in that moment she realized the truth that i loved her she saw my poor unspoken love reflected in my silence and in my eyes and she felt sorry for me when we are unhappy its as though we become more attuned to the suffering of others as though our own pain sharpens our ability to recognize it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'third night', 'Third Night', 9, NULL, 'Instead of destroying our capacity to feel, sadness concentrates it, heightens it. She must have felt my sorrow, even as she wrestled with her own. I had gone to meet her with a full heart, carrying with me all the anticipation and impatience of someone who has allowed himself to hope. I had no idea then that it would end this way, that my hopes would crumble so completely. When I arrived, she was already there, waiting for me.', '', NULL, NULL, NULL, NULL, 'white nights third night', 'instead of destroying our capacity to feel sadness concentrates it heightens it she must have felt my sorrow even as she wrestled with her own i had gone to meet her with a full heart carrying with me all the anticipation and impatience of someone who has allowed himself to hope i had no idea then that it would end this way that my hopes would crumble so completely when i arrived she was already there waiting for me', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'third night', 'Third Night', 10, NULL, 'She looked radiant, her face aglow with pleasure. She was expecting something—no, someone. She was expecting an answer, and that answer was him. She had arrived long before I did, her excitement so great that she couldn''t wait. At first she was giddy, laughing at everything I said, even when it wasn''t meant to be funny. Her laughter was infectious, but it didn''t take long for me to sense the undercurrent of tension beneath it.', '', NULL, NULL, NULL, NULL, 'white nights third night', 'she looked radiant her face aglow with pleasure she was expecting something no someone she was expecting an answer and that answer was him she had arrived long before i did her excitement so great that she couldnt wait at first she was giddy laughing at everything i said even when it wasnt meant to be funny her laughter was infectious but it didnt take long for me to sense the undercurrent of tension beneath it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'third night', 'Third Night', 11, NULL, 'I tried to talk to keep the conversation light, but soon I fell silent, unable to match her mood. I was too aware of the truth that she couldn''t yet admit to herself. Do you know why I''m so happy today? she asked suddenly, her eyes sparkling as she turned to me. Do you know why I like looking at you so much right now? Why? I asked, trying to keep my voice steady, though my heart was already pounding in my chest.', '', NULL, NULL, NULL, NULL, 'white nights third night', 'i tried to talk to keep the conversation light but soon i fell silent unable to match her mood i was too aware of the truth that she couldnt yet admit to herself do you know why im so happy today she asked suddenly her eyes sparkling as she turned to me do you know why i like looking at you so much right now why i asked trying to keep my voice steady though my heart was already pounding in my chest', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'third night', 'Third Night', 12, NULL, 'I like you, she said with a warm smile, because you haven''t fallen in love with me. You know, in your place most men would have been sighing endlessly, pestering me with their feelings, making themselves miserable and me uncomfortable. But you, you''re different. You''re so nice about everything. She laughed softly, but before I could respond, she reached out and wrung my hand with such unexpected force that I almost cried out in surprise.', '', NULL, NULL, NULL, NULL, 'white nights third night', 'i like you she said with a warm smile because you havent fallen in love with me you know in your place most men would have been sighing endlessly pestering me with their feelings making themselves miserable and me uncomfortable but you youre different youre so nice about everything she laughed softly but before i could respond she reached out and wrung my hand with such unexpected force that i almost cried out in surprise', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'third night', 'Third Night', 13, NULL, 'Her laughter grew brighter at my startled expression, and for a moment her mood seemed to lift entirely. Goodness, what a friend you are, she said, her tone shifting into something more serious, even tender as her laughter subsided. She gazed at me intently, and after a pause she added, truly, God sent you to me. I don''t know what I would have done without you, especially now. What would have happened to me if you hadn''t been here?', '', NULL, NULL, NULL, NULL, 'white nights third night', 'her laughter grew brighter at my startled expression and for a moment her mood seemed to lift entirely goodness what a friend you are she said her tone shifting into something more serious even tender as her laughter subsided she gazed at me intently and after a pause she added truly god sent you to me i dont know what i would have done without you especially now what would have happened to me if you hadnt been here', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'third night', 'Third Night', 14, NULL, 'You are so unselfish, so kind, so understanding. How could anyone be more genuinely caring than you? When I am married, you and I will be the best of friends, closer than brother and sister. I shall care for you almost as much as I do for him. Her words pierced my heart. In that moment a wave of profound sadness swept over me, though I felt something else too, an inexplicable urge to laugh.', '', NULL, NULL, NULL, NULL, 'white nights third night', 'you are so unselfish so kind so understanding how could anyone be more genuinely caring than you when i am married you and i will be the best of friends closer than brother and sister i shall care for you almost as much as i do for him her words pierced my heart in that moment a wave of profound sadness swept over me though i felt something else too an inexplicable urge to laugh', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'third night', 'Third Night', 15, NULL, 'Perhaps it was the absurdity of the situation, the strange mingling of my love for her, and the knowledge that she would never return it. You''re very upset right now, I said gently, trying to steady my voice. You''re frightened, aren''t you? You''re afraid he won''t come. Oh, how unkind you are, she exclaimed, though there was no anger in her tone, only a kind of playful reproach. If I were less happy, I believe I would cry at your lack of faith, at your doubts about him, and at the way you''re scolding me now.', '', NULL, NULL, NULL, NULL, 'white nights third night', 'perhaps it was the absurdity of the situation the strange mingling of my love for her and the knowledge that she would never return it youre very upset right now i said gently trying to steady my voice youre frightened arent you youre afraid he wont come oh how unkind you are she exclaimed though there was no anger in her tone only a kind of playful reproach if i were less happy i believe i would cry at your lack of faith at your doubts about him and at the way youre scolding me now', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'third night', 'Third Night', 16, NULL, 'But no, I won''t cry. You''ve made me think, though. Yes, you''ve given me a great deal to think about, but not now, later. For now, I must admit, you''re right. She sighed, her expression softening. Yes, I am not myself right now. I feel as though I''m floating, as though everything is unreal. My nerves are all on edge, and I can''t seem to feel things as deeply as I should.', '', NULL, NULL, NULL, NULL, 'white nights third night', 'but no i wont cry youve made me think though yes youve given me a great deal to think about but not now later for now i must admit youre right she sighed her expression softening yes i am not myself right now i feel as though im floating as though everything is unreal my nerves are all on edge and i cant seem to feel things as deeply as i should', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'third night', 'Third Night', 17, NULL, 'Everything feels too light, too fragile. But enough about feelings, she said suddenly, cutting herself off. Let''s not dwell on that. At that exact moment we heard footsteps approaching. The sound echoed faintly in the stillness of the night, growing louder as the figure drew closer. In the dim light we saw a form coming toward us. We both froze. She gasped softly, almost crying out, and I instinctively let go of her hand and took a step back, ready to walk away.', '', NULL, NULL, NULL, NULL, 'white nights third night', 'everything feels too light too fragile but enough about feelings she said suddenly cutting herself off lets not dwell on that at that exact moment we heard footsteps approaching the sound echoed faintly in the stillness of the night growing louder as the figure drew closer in the dim light we saw a form coming toward us we both froze she gasped softly almost crying out and i instinctively let go of her hand and took a step back ready to walk away', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'third night', 'Third Night', 18, NULL, 'But the figure passed by without stopping. It wasn''t him. What are you afraid of? Why did you let go of my hand, she asked, turning to me with a puzzled expression. Without waiting for an answer, she reached out and placed her hand in mine again. Come, it''s nothing. Let''s wait together. When he comes, I want him to see how fond we are of each other. How fond we are of each other, I repeated, unable to hide the bitterness in my voice.', '', NULL, NULL, NULL, NULL, 'white nights third night', 'but the figure passed by without stopping it wasnt him what are you afraid of why did you let go of my hand she asked turning to me with a puzzled expression without waiting for an answer she reached out and placed her hand in mine again come its nothing lets wait together when he comes i want him to see how fond we are of each other how fond we are of each other i repeated unable to hide the bitterness in my voice', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'third night', 'Third Night', 19, NULL, 'Inside my heart ached as I thought, oh Nastenka, Nastenka, how much you''ve just revealed to me with those words. Such fondness in moments like this makes the heart grow cold and the soul unbearably heavy. Your hand is cold in mine, while mine burns like fire. How blind you are, Nastenka, to the truth right in front of you. Oh, how unbearable a happy person can be sometimes, and yet how could I ever be angry with you?', '', NULL, NULL, NULL, NULL, 'white nights third night', 'inside my heart ached as i thought oh nastenka nastenka how much youve just revealed to me with those words such fondness in moments like this makes the heart grow cold and the soul unbearably heavy your hand is cold in mine while mine burns like fire how blind you are nastenka to the truth right in front of you oh how unbearable a happy person can be sometimes and yet how could i ever be angry with you', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'third night', 'Third Night', 20, NULL, 'The emotion swirling within me grew too intense to contain. At last my heart overflowed. Listen, Nastenka, I burst out. Do you have any idea how my day has been? Do you know what I''ve been feeling all this time? She looked at me with wide eyes, a mixture of curiosity and concern. What do you mean? How has your day been? Tell me. Tell me quickly. Why haven''t you said anything until now?', '', NULL, NULL, NULL, NULL, 'white nights third night', 'the emotion swirling within me grew too intense to contain at last my heart overflowed listen nastenka i burst out do you have any idea how my day has been do you know what ive been feeling all this time she looked at me with wide eyes a mixture of curiosity and concern what do you mean how has your day been tell me tell me quickly why havent you said anything until now', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'third night', 'Third Night', 21, NULL, 'Well, I began struggling to find the right words. To start with, after I carried out all your commissions, delivering the letter, visiting your kind friends, then—then I went home and went straight to bed. Is that all? she interrupted, breaking into laughter. Yes, almost all, I answered, trying to hold myself together as foolish, inexplicable tears threatened to well up in my eyes. I woke up an hour before our appointment, though, truth be told.', '', NULL, NULL, NULL, NULL, 'white nights third night', 'well i began struggling to find the right words to start with after i carried out all your commissions delivering the letter visiting your kind friends then then i went home and went straight to bed is that all she interrupted breaking into laughter yes almost all i answered trying to hold myself together as foolish inexplicable tears threatened to well up in my eyes i woke up an hour before our appointment though truth be told', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'third night', 'Third Night', 22, NULL, 'It felt as though I hadn''t slept at all. I can''t explain it. I don''t even know what happened to me. It was as if time had stopped entirely, as though the world itself had paused in that one fleeting moment. I came here to tell you everything, Nastenka, feeling like that single sensation, that single overwhelming feeling, had taken hold of me forever. It was as if one minute of my life had stretched out endlessly, as though it could last for all eternity, and everything else—the entire world—had come to a halt.', '', NULL, NULL, NULL, NULL, 'white nights third night', 'it felt as though i hadnt slept at all i cant explain it i dont even know what happened to me it was as if time had stopped entirely as though the world itself had paused in that one fleeting moment i came here to tell you everything nastenka feeling like that single sensation that single overwhelming feeling had taken hold of me forever it was as if one minute of my life had stretched out endlessly as though it could last for all eternity and everything else the entire world had come to a halt', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'third night', 'Third Night', 23, NULL, 'When I woke, it was as if some old forgotten melody, one I had once known so well long ago, but had since lost in the recesses of memory, had returned to me. It was a tune so sweet, so achingly familiar, that it seemed to echo deep in my heart. And I felt as though that melody had been waiting there all along, knocking at my soul, yearning to be heard.', '', NULL, NULL, NULL, NULL, 'white nights third night', 'when i woke it was as if some old forgotten melody one i had once known so well long ago but had since lost in the recesses of memory had returned to me it was a tune so sweet so achingly familiar that it seemed to echo deep in my heart and i felt as though that melody had been waiting there all along knocking at my soul yearning to be heard', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'third night', 'Third Night', 24, NULL, 'And now, at last, it had broken through. Oh, my goodness, my goodness! Nastenka interrupted, her voice cutting through my reverie. What on earth are you talking about? I don''t understand a word of it! Her bluntness startled me, and I faltered, my hopes dimming. Yet there was still a faint, lingering hope hidden in my voice as I tried to explain. Ah, Nastenka, I said plaintively, I was just trying to describe to you that strange, overwhelming impression.', '', NULL, NULL, NULL, NULL, 'white nights third night', 'and now at last it had broken through oh my goodness my goodness nastenka interrupted her voice cutting through my reverie what on earth are you talking about i dont understand a word of it her bluntness startled me and i faltered my hopes dimming yet there was still a faint lingering hope hidden in my voice as i tried to explain ah nastenka i said plaintively i was just trying to describe to you that strange overwhelming impression', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'third night', 'Third Night', 25, NULL, 'Stop it, hush! she said suddenly, and in an instant I could see that she had guessed. Her sharp intuition had uncovered what I hadn''t dared to say outright. Her mood shifted abruptly. With a mischievous smile, she became extraordinarily lively, talkative, and playful. She slipped her arm through mine, laughing with a lightness that seemed almost calculated. Every faltering, confused word I tried to speak only made her laugh more, her laughter bright and ringing.', '', NULL, NULL, NULL, NULL, 'white nights third night', 'stop it hush she said suddenly and in an instant i could see that she had guessed her sharp intuition had uncovered what i hadnt dared to say outright her mood shifted abruptly with a mischievous smile she became extraordinarily lively talkative and playful she slipped her arm through mine laughing with a lightness that seemed almost calculated every faltering confused word i tried to speak only made her laugh more her laughter bright and ringing', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'third night', 'Third Night', 26, NULL, 'Her amusement, so sudden and unrelenting, began to irritate me. It felt as though she was flirting deliberately, as though she was trying to mask or deflect something deeper. Do you know, she began suddenly, still laughing, I feel a little offended that you aren''t in love with me? Isn''t that strange? How contradictory human nature is! But then again, Mr. Unapproachable, she added teasingly, you can''t blame me for being so simple.', '', NULL, NULL, NULL, NULL, 'white nights third night', 'her amusement so sudden and unrelenting began to irritate me it felt as though she was flirting deliberately as though she was trying to mask or deflect something deeper do you know she began suddenly still laughing i feel a little offended that you arent in love with me isnt that strange how contradictory human nature is but then again mr unapproachable she added teasingly you cant blame me for being so simple', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'third night', 'Third Night', 27, NULL, 'I tell you everything, every silly, foolish thought that pops into my head. It''s just who I am. Her words stung, though I tried not to show it. I glanced away, searching for a distraction. Listen, I said, catching the faint sound of a bell ringing in the distance. That must be eleven o''clock. The slow, deliberate chimes echoed faintly through the quiet night. She stopped suddenly, her laughter fading as her expression changed.', '', NULL, NULL, NULL, NULL, 'white nights third night', 'i tell you everything every silly foolish thought that pops into my head its just who i am her words stung though i tried not to show it i glanced away searching for a distraction listen i said catching the faint sound of a bell ringing in the distance that must be eleven oclock the slow deliberate chimes echoed faintly through the quiet night she stopped suddenly her laughter fading as her expression changed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'third night', 'Third Night', 28, NULL, 'She stood still, her face tense, and began counting the strokes. I regretted saying it immediately. The look of nervous uncertainty in her eyes, the way her voice trembled as she whispered, yes, it''s eleven, filled me with a sharp pang of guilt. Why had I done that? Why had I deliberately reminded her of the time? I cursed myself for my petty impulse, for the spiteful satisfaction I had felt just a moment ago.', '', NULL, NULL, NULL, NULL, 'white nights third night', 'she stood still her face tense and began counting the strokes i regretted saying it immediately the look of nervous uncertainty in her eyes the way her voice trembled as she whispered yes its eleven filled me with a sharp pang of guilt why had i done that why had i deliberately reminded her of the time i cursed myself for my petty impulse for the spiteful satisfaction i had felt just a moment ago', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'third night', 'Third Night', 29, NULL, 'She was anxious enough already, and now I had made it worse. I wanted to take it back, to undo the fear and sadness I had just caused. Now, Nastenka, I said softly, trying to comfort her, don''t worry, please, let''s think this through rationally. There''s no reason to believe the worst yet. There are so many possible explanations for why he hasn''t come. Let me explain, and you''ll see it''s not as bad as it seems.', '', NULL, NULL, NULL, NULL, 'white nights third night', 'she was anxious enough already and now i had made it worse i wanted to take it back to undo the fear and sadness i had just caused now nastenka i said softly trying to comfort her dont worry please lets think this through rationally theres no reason to believe the worst yet there are so many possible explanations for why he hasnt come let me explain and youll see its not as bad as it seems', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'third night', 'Third Night', 30, NULL, 'She looked at me, her eyes wide and searching, desperate for reassurance. I knew she wanted to believe me, to hold on to hope, and it gave me the strength to press on. Look, I began, my voice growing steadier as I warmed to my task. It''s entirely possible that he hasn''t received your letter yet. Think about it, what if he wasn''t at home when it arrived? He might not have read it, even now, or perhaps he read it but wasn''t able to respond immediately.', '', NULL, NULL, NULL, NULL, 'white nights third night', 'she looked at me her eyes wide and searching desperate for reassurance i knew she wanted to believe me to hold on to hope and it gave me the strength to press on look i began my voice growing steadier as i warmed to my task its entirely possible that he hasnt received your letter yet think about it what if he wasnt at home when it arrived he might not have read it even now or perhaps he read it but wasnt able to respond immediately', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'third night', 'Third Night', 31, NULL, 'There are so many reasons why he might not be here yet. Suppose he''s planning to answer the letter but couldn''t come until tomorrow. Anything could have delayed him. As I spoke, I could see her tension easing, her breathing slowing. She wanted so much to believe me, and I wanted even more to make her believe, to ease her worry even for a little while. At that moment she was so vulnerable, so ready to grasp at any straw of hope.', '', NULL, NULL, NULL, NULL, 'white nights third night', 'there are so many reasons why he might not be here yet suppose hes planning to answer the letter but couldnt come until tomorrow anything could have delayed him as i spoke i could see her tension easing her breathing slowing she wanted so much to believe me and i wanted even more to make her believe to ease her worry even for a little while at that moment she was so vulnerable so ready to grasp at any straw of hope', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'third night', 'Third Night', 32, NULL, 'I continued, feeling a strange sense of responsibility, almost a duty to shield her from despair. I''ll tell you what, I said finally, feeling more confident now. As soon as it''s light tomorrow, I''ll go to check for his reply myself. If there''s an answer, I''ll bring it to you immediately. We''ll know for sure then. But until that happens, don''t let yourself think the worst. There are thousands of possibilities.', '', NULL, NULL, NULL, NULL, 'white nights third night', 'i continued feeling a strange sense of responsibility almost a duty to shield her from despair ill tell you what i said finally feeling more confident now as soon as its light tomorrow ill go to check for his reply myself if theres an answer ill bring it to you immediately well know for sure then but until that happens dont let yourself think the worst there are thousands of possibilities', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'third night', 'Third Night', 33, NULL, 'Anything could have happened. She nodded slowly, her face softening as the faintest flicker of hope returned to her eyes. For a moment it seemed as though she had found a little peace. Yes, yes, said Nastenka eagerly, as though suddenly awakened to a new possibility. I didn''t think of that. Of course anything could happen, she added, though her voice trailed off into a tone of quiet resignation. There was no real conviction behind her words, only a faint, distant echo of another thought, some vexing discord lingering in her mind, unresolved.', '', NULL, NULL, NULL, NULL, 'white nights third night', 'anything could have happened she nodded slowly her face softening as the faintest flicker of hope returned to her eyes for a moment it seemed as though she had found a little peace yes yes said nastenka eagerly as though suddenly awakened to a new possibility i didnt think of that of course anything could happen she added though her voice trailed off into a tone of quiet resignation there was no real conviction behind her words only a faint distant echo of another thought some vexing discord lingering in her mind unresolved', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'third night', 'Third Night', 34, NULL, 'I know what you must do, she said after a pause, her tone growing more certain. Go as early as you can tomorrow morning, the very first thing. If you hear anything, anything at all, let me know immediately. You know where I live, don''t you? She began to repeat her address to me, her voice hurried and yet soft, as though she needed to make sure I would remember every word.', '', NULL, NULL, NULL, NULL, 'white nights third night', 'i know what you must do she said after a pause her tone growing more certain go as early as you can tomorrow morning the very first thing if you hear anything anything at all let me know immediately you know where i live dont you she began to repeat her address to me her voice hurried and yet soft as though she needed to make sure i would remember every word', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'third night', 'Third Night', 35, NULL, 'Her insistence made me feel a strange pang of sadness, a deep longing to reassure her, to promise her more than I could. Then quite suddenly her mood shifted, she became unusually tender, almost maternal in the way she looked at me, her concern for me clear in every glance, every movement. She listened attentively as I spoke, nodding slightly as though she wanted me to believe she was truly hearing me.', '', NULL, NULL, NULL, NULL, 'white nights third night', 'her insistence made me feel a strange pang of sadness a deep longing to reassure her to promise her more than i could then quite suddenly her mood shifted she became unusually tender almost maternal in the way she looked at me her concern for me clear in every glance every movement she listened attentively as i spoke nodding slightly as though she wanted me to believe she was truly hearing me', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'third night', 'Third Night', 36, NULL, 'Yet when I asked her a question, she faltered, her silence spoke louder than any words might have. Her confusion deepened and she turned her head away, unable to meet my eyes. I leaned in slightly, trying to understand what was happening. When she finally turned back toward me, I saw it, tears glistening in her eyes. She was crying, though she was trying desperately to hide it. Nastenka, I said softly, alarmed by her sudden shift.', '', NULL, NULL, NULL, NULL, 'white nights third night', 'yet when i asked her a question she faltered her silence spoke louder than any words might have her confusion deepened and she turned her head away unable to meet my eyes i leaned in slightly trying to understand what was happening when she finally turned back toward me i saw it tears glistening in her eyes she was crying though she was trying desperately to hide it nastenka i said softly alarmed by her sudden shift', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'third night', 'Third Night', 37, NULL, 'How can you? Why are you crying? Oh, what a child you are! What childishness! Come now, don''t cry. Please don''t. She tried to smile through her tears, brushing them away quickly as though embarrassed by her display of emotion. It''s nothing, she murmured, though her chin quivered and her chest still heaved with the effort to compose herself, she was fighting to steady her breathing, to regain her usual cheerfulness.', '', NULL, NULL, NULL, NULL, 'white nights third night', 'how can you why are you crying oh what a child you are what childishness come now dont cry please dont she tried to smile through her tears brushing them away quickly as though embarrassed by her display of emotion its nothing she murmured though her chin quivered and her chest still heaved with the effort to compose herself she was fighting to steady her breathing to regain her usual cheerfulness', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'third night', 'Third Night', 38, NULL, 'But the struggle was written all over her face. After a moment of silence, she spoke again, her voice softer, more contemplative. I was thinking about you, she said, almost to herself. You''re so kind, you''re so good. I would have to be made of stone not to feel it. Do you know what I was just thinking? I was comparing you two. She hesitated, then looked directly at me, her eyes filled with strange mixture of sadness and warmth.', '', NULL, NULL, NULL, NULL, 'white nights third night', 'but the struggle was written all over her face after a moment of silence she spoke again her voice softer more contemplative i was thinking about you she said almost to herself youre so kind youre so good i would have to be made of stone not to feel it do you know what i was just thinking i was comparing you two she hesitated then looked directly at me her eyes filled with strange mixture of sadness and warmth', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'third night', 'Third Night', 39, NULL, 'Why isn''t he you? Why isn''t he like you? You are so much better than he is. He isn''t half as kind, half as thoughtful. And yet—yet I love him more than I could ever love you. Her words pierced through me, leaving me speechless. I couldn''t summon a single response. I didn''t know what to say, and for a moment neither did she. She seemed to expect something, though, a word, a look, anything.', '', NULL, NULL, NULL, NULL, 'white nights third night', 'why isnt he you why isnt he like you you are so much better than he is he isnt half as kind half as thoughtful and yet yet i love him more than i could ever love you her words pierced through me leaving me speechless i couldnt summon a single response i didnt know what to say and for a moment neither did she she seemed to expect something though a word a look anything', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'third night', 'Third Night', 40, NULL, 'But I stayed silent, struggling to contain the storm of emotions her confession had unleashed within me. Perhaps, she said after another long pause, as though trying to fill the silence herself, perhaps it''s just that I don''t understand him fully yet. You know, I''ve always been a little afraid of him. He''s so serious, so proud. At least that''s how he seems. But I know it''s only a facade, deep down I know there''s more tenderness in his heart than even in mine.', '', NULL, NULL, NULL, NULL, 'white nights third night', 'but i stayed silent struggling to contain the storm of emotions her confession had unleashed within me perhaps she said after another long pause as though trying to fill the silence herself perhaps its just that i dont understand him fully yet you know ive always been a little afraid of him hes so serious so proud at least thats how he seems but i know its only a facade deep down i know theres more tenderness in his heart than even in mine', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'third night', 'Third Night', 41, NULL, 'I remember how he looked at me that day, when I went to him with my little bundle. Do you remember? I told you about it. He seemed so kind, so sad. And yet—I feel like I respect him too much. Doesn''t that prove that we aren''t equals? No, Nastenka, I replied gently, my voice barely above a whisper. It doesn''t prove that you aren''t equals. It proves that you love him more than anything in the world.', '', NULL, NULL, NULL, NULL, 'white nights third night', 'i remember how he looked at me that day when i went to him with my little bundle do you remember i told you about it he seemed so kind so sad and yet i feel like i respect him too much doesnt that prove that we arent equals no nastenka i replied gently my voice barely above a whisper it doesnt prove that you arent equals it proves that you love him more than anything in the world', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'third night', 'Third Night', 42, NULL, 'More than yourself, even. She looked at me with wide, thoughtful eyes, as though my words had struck a chord deep within her. Yes, she said at last, her voice tinged with naive sincerity. Yes, maybe you''re right, but do you know what strikes me now? She paused, her tone growing more reflective. I''m not talking about him anymore, not about anyone in particular, just speaking generally. This is something I''ve thought about before.', '', NULL, NULL, NULL, NULL, 'white nights third night', 'more than yourself even she looked at me with wide thoughtful eyes as though my words had struck a chord deep within her yes she said at last her voice tinged with naive sincerity yes maybe youre right but do you know what strikes me now she paused her tone growing more reflective im not talking about him anymore not about anyone in particular just speaking generally this is something ive thought about before', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'third night', 'Third Night', 43, NULL, 'Why can''t we all just be like brothers to one another? Why is it that even the best people seem to hide parts of themselves from others, as if they''re keeping something back? Why can''t we simply say what''s in our hearts, openly and honestly, especially when we know our words won''t be empty or meaningless? Instead, we put up walls, we act distant, and we make ourselves seem harsher than we really are.', '', NULL, NULL, NULL, NULL, 'white nights third night', 'why cant we all just be like brothers to one another why is it that even the best people seem to hide parts of themselves from others as if theyre keeping something back why cant we simply say whats in our hearts openly and honestly especially when we know our words wont be empty or meaningless instead we put up walls we act distant and we make ourselves seem harsher than we really are', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'third night', 'Third Night', 44, NULL, 'It''s as if everyone is afraid to show their feelings, afraid to express them too quickly, as though they might somehow cheapen them by doing so. Oh, Nastenka, I said, my heart aching at her words. What you''re saying is true, painfully true, but there are so many reasons for it, so many complicated reasons. Even as I spoke, I felt myself suppressing my own feelings more than ever, struggling to keep my voice calm, to conceal the turmoil raging within me.', '', NULL, NULL, NULL, NULL, 'white nights third night', 'its as if everyone is afraid to show their feelings afraid to express them too quickly as though they might somehow cheapen them by doing so oh nastenka i said my heart aching at her words what youre saying is true painfully true but there are so many reasons for it so many complicated reasons even as i spoke i felt myself suppressing my own feelings more than ever struggling to keep my voice calm to conceal the turmoil raging within me', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'third night', 'Third Night', 45, NULL, 'No, no, she said suddenly, her voice charged with deep emotion. You, for instance, you''re not like other people. I don''t even know how to explain what I mean. She hesitated, her words faltering as though she was trying to grasp something intangible. It''s hard for me to put it into words, but it seems to me that you, right now, at this very moment, it seems to me that you''re sacrificing something for me.', '', NULL, NULL, NULL, NULL, 'white nights third night', 'no no she said suddenly her voice charged with deep emotion you for instance youre not like other people i dont even know how to explain what i mean she hesitated her words faltering as though she was trying to grasp something intangible its hard for me to put it into words but it seems to me that you right now at this very moment it seems to me that youre sacrificing something for me', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'third night', 'Third Night', 46, NULL, 'Her voice softened as she added this, and she glanced at me briefly, almost shyly, as if afraid of my reaction. Forgive me for saying so, she went on timidly, her voice trembling as she tried to keep her composure. I''m just a simple girl, I''ve seen so little of life, and sometimes I feel like I don''t even know how to say what I want to say. She smiled faintly, but there was a quiver in her lips, as though she was holding back something deeper, something she couldn''t quite articulate.', '', NULL, NULL, NULL, NULL, 'white nights third night', 'her voice softened as she added this and she glanced at me briefly almost shyly as if afraid of my reaction forgive me for saying so she went on timidly her voice trembling as she tried to keep her composure im just a simple girl ive seen so little of life and sometimes i feel like i dont even know how to say what i want to say she smiled faintly but there was a quiver in her lips as though she was holding back something deeper something she couldnt quite articulate', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'third night', 'Third Night', 47, NULL, 'I only wanted to tell you that I''m grateful. I feel it, deeply. Oh, may God bless you for it. May He grant you happiness, more than you can imagine. Her words were like a balm and a wound at the same time. She spoke with such sincerity that it was impossible to feel bitterness, even as her meaning pierced me. What you told me about your dreamer, she continued, is not true anymore.', '', NULL, NULL, NULL, NULL, 'white nights third night', 'i only wanted to tell you that im grateful i feel it deeply oh may god bless you for it may he grant you happiness more than you can imagine her words were like a balm and a wound at the same time she spoke with such sincerity that it was impossible to feel bitterness even as her meaning pierced me what you told me about your dreamer she continued is not true anymore', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'third night', 'Third Night', 48, NULL, 'Not about you, at least. You''ve changed, you''ve recovered. You''re not the same man you described to me. She looked at me with something like pride, as though she were acknowledging a transformation she herself had brought about. If you ever fall in love with someone, really fall in love, I pray that God grants you happiness with her. I don''t need to wish anything for her, though, because she will be happy.', '', NULL, NULL, NULL, NULL, 'white nights third night', 'not about you at least youve changed youve recovered youre not the same man you described to me she looked at me with something like pride as though she were acknowledging a transformation she herself had brought about if you ever fall in love with someone really fall in love i pray that god grants you happiness with her i dont need to wish anything for her though because she will be happy', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'third night', 'Third Night', 49, NULL, 'I know it. I''m a woman, after all, and I understand these things. Believe me when I tell you this. She fell silent then, her words hanging in the air between us, and for a moment neither of us could speak. She pressed my hand warmly, her grip firm yet tender, as though she wanted to convey everything she couldn''t put into words through that single gesture. I felt my throat tighten with emotion, but I couldn''t bring myself to respond.', '', NULL, NULL, NULL, NULL, 'white nights third night', 'i know it im a woman after all and i understand these things believe me when i tell you this she fell silent then her words hanging in the air between us and for a moment neither of us could speak she pressed my hand warmly her grip firm yet tender as though she wanted to convey everything she couldnt put into words through that single gesture i felt my throat tighten with emotion but i couldnt bring myself to respond', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'third night', 'Third Night', 50, NULL, 'The weight of her words, their bittersweet kindness, held me silent. Minutes passed in this quiet shared understanding. At last she lifted her head and broke the silence. It''s clear he won''t come tonight, she said softly, her voice steady but tinged with resignation. It''s late now. I forced myself to reply, summoning all the conviction I could muster. He''ll come tomorrow, I said firmly, as though by sheer will I could make it true.', '', NULL, NULL, NULL, NULL, 'white nights third night', 'the weight of her words their bittersweet kindness held me silent minutes passed in this quiet shared understanding at last she lifted her head and broke the silence its clear he wont come tonight she said softly her voice steady but tinged with resignation its late now i forced myself to reply summoning all the conviction i could muster hell come tomorrow i said firmly as though by sheer will i could make it true', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'third night', 'Third Night', 51, NULL, 'Yes, she said after a pause, and this time there was no trace of her earlier doubt. Her voice was calm, almost cheerful. I see now that it''s impossible for him to come before tomorrow. Well, good-bye then, till tomorrow. If it rains I might not come, but the day after tomorrow I''ll come for certain. Whatever happens, I''ll be here. Promise me you''ll come too. I need to see you.', '', NULL, NULL, NULL, NULL, 'white nights third night', 'yes she said after a pause and this time there was no trace of her earlier doubt her voice was calm almost cheerful i see now that its impossible for him to come before tomorrow well good bye then till tomorrow if it rains i might not come but the day after tomorrow ill come for certain whatever happens ill be here promise me youll come too i need to see you', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'third night', 'Third Night', 52, NULL, 'I''ll tell you everything. As we parted she gave me her hand again, this time holding it longer, as though she was reluctant to let go. Her eyes met mine with a rare openness, a kind of pure sincerity that took my breath away. We''ll always be together, won''t we? she asked candidly, her voice filled with quiet hope. Oh, Nastenka, Nastenka, if only you knew how lonely I am now.', '', NULL, NULL, NULL, NULL, 'white nights third night', 'ill tell you everything as we parted she gave me her hand again this time holding it longer as though she was reluctant to let go her eyes met mine with a rare openness a kind of pure sincerity that took my breath away well always be together wont we she asked candidly her voice filled with quiet hope oh nastenka nastenka if only you knew how lonely i am now', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'third night', 'Third Night', 53, NULL, 'When nine o''clock struck that evening I couldn''t bear to stay indoors. The hours seemed to stretch endlessly, and the walls of my room felt like they were closing in around me. I put on my coat and stepped outside, indifferent to the damp chill of the weather. The rain had eased, but the streets were still slick and gleaming under the faint glow of the streetlights. I walked without direction, my feet carrying me almost instinctively to the embankment.', '', NULL, NULL, NULL, NULL, 'white nights third night', 'when nine oclock struck that evening i couldnt bear to stay indoors the hours seemed to stretch endlessly and the walls of my room felt like they were closing in around me i put on my coat and stepped outside indifferent to the damp chill of the weather the rain had eased but the streets were still slick and gleaming under the faint glow of the streetlights i walked without direction my feet carrying me almost instinctively to the embankment', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'third night', 'Third Night', 54, NULL, 'There I sat on the bench we had shared, staring out into the dark, restless waters. After a while I found myself walking toward her street. My heart beat faster with every step, a strange mix of anticipation and dread building within me. But when I was only a few steps away from her door, I stopped. Shame washed over me like a cold wave. What was I doing? I couldn''t bring myself to look at her windows.', '', NULL, NULL, NULL, NULL, 'white nights third night', 'there i sat on the bench we had shared staring out into the dark restless waters after a while i found myself walking toward her street my heart beat faster with every step a strange mix of anticipation and dread building within me but when i was only a few steps away from her door i stopped shame washed over me like a cold wave what was i doing i couldnt bring myself to look at her windows', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'third night', 'Third Night', 55, NULL, 'I turned abruptly and walked away, my shoulders hunched against the damp air, my thoughts heavier than ever. I returned home feeling more dejected than I had ever been before. The dreary day seemed to reflect my own desolation, each raindrop a small echo of the ache in my heart. If the weather had been fine, perhaps I would have wandered the streets all night trying to escape my thoughts, but the rain drove me back, forcing me to sit with my loneliness.', '', NULL, NULL, NULL, NULL, 'white nights third night', 'i turned abruptly and walked away my shoulders hunched against the damp air my thoughts heavier than ever i returned home feeling more dejected than i had ever been before the dreary day seemed to reflect my own desolation each raindrop a small echo of the ache in my heart if the weather had been fine perhaps i would have wandered the streets all night trying to escape my thoughts but the rain drove me back forcing me to sit with my loneliness', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'third night', 'Third Night', 56, NULL, 'Still I clung to the promise of tomorrow. Tomorrow she would come, and she would tell me everything. Tomorrow would bring answers, resolution, perhaps even hope. The letter hadn''t arrived yet, of course, but I told myself that was to be expected. By now, I thought bitterly, they must already be together.', '', NULL, NULL, NULL, NULL, 'white nights third night', 'still i clung to the promise of tomorrow tomorrow she would come and she would tell me everything tomorrow would bring answers resolution perhaps even hope the letter hadnt arrived yet of course but i told myself that was to be expected by now i thought bitterly they must already be together', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 0, NULL, 'My God, how has it all ended? What has it all come to? I arrived promptly at nine o''clock, my heart heavy with foreboding. From a distance I saw her already there, standing as she had stood that first evening, her elbows resting on the railing, gazing out over the canal. She was so still, so lost in thought, that she didn''t hear my footsteps approaching. Nastenka! I called softly, suppressing the tremor in my voice with all the strength I could muster.', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'my god how has it all ended what has it all come to i arrived promptly at nine oclock my heart heavy with foreboding from a distance i saw her already there standing as she had stood that first evening her elbows resting on the railing gazing out over the canal she was so still so lost in thought that she didnt hear my footsteps approaching nastenka i called softly suppressing the tremor in my voice with all the strength i could muster', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 1, NULL, 'She turned quickly, her face alight with anxious expectation. Well? she said urgently. Well? Make haste! Her voice was tense, as if she couldn''t bear another second of uncertainty. I hesitated for a moment, unsure how to begin. Her eyes searched mine, brimming with hope and fear. Well, where is the letter? Have you brought the letter? she demanded, clutching at the cold metal of the railing as though it might steady her.', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'she turned quickly her face alight with anxious expectation well she said urgently well make haste her voice was tense as if she couldnt bear another second of uncertainty i hesitated for a moment unsure how to begin her eyes searched mine brimming with hope and fear well where is the letter have you brought the letter she demanded clutching at the cold metal of the railing as though it might steady her', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 2, NULL, 'I felt my throat tighten as I answered, my voice low and strained. No, there is no letter, I said at last. Hasn''t he been to you yet? As soon as the words left my mouth, I saw the colour drain from her face. She turned so pale, so ghostly, that I thought she might collapse right there before me, her wide, unblinking eyes locked on mine, and she stared at me as if I had just struck the final blow to her fragile hope.', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'i felt my throat tighten as i answered my voice low and strained no there is no letter i said at last hasnt he been to you yet as soon as the words left my mouth i saw the colour drain from her face she turned so pale so ghostly that i thought she might collapse right there before me her wide unblinking eyes locked on mine and she stared at me as if i had just struck the final blow to her fragile hope', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 3, NULL, 'I had shattered her last dream, the thread of possibility she''d been clinging to with all her strength. Well? she said finally, her voice breaking as though each word cost her unimaginable effort. God be with him. God be with him, if he leaves me like that. Her head dropped, and her gaze fell to the ground. She seemed unable to look at me, as though the weight of her humiliation was too great to bear.', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'i had shattered her last dream the thread of possibility shed been clinging to with all her strength well she said finally her voice breaking as though each word cost her unimaginable effort god be with him god be with him if he leaves me like that her head dropped and her gaze fell to the ground she seemed unable to look at me as though the weight of her humiliation was too great to bear', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 4, NULL, 'For several agonizing moments she fought with her emotions, her body trembling with the effort to hold herself together. Then all at once she turned away. Leaning her elbows against the railing again, she buried her face in her hands and broke into heart-wrenching sobs. Oh, don''t! Don''t! I began, stepping toward her. But as I looked at her crumpled figure, I felt my words falter. What could I say to her?', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'for several agonizing moments she fought with her emotions her body trembling with the effort to hold herself together then all at once she turned away leaning her elbows against the railing again she buried her face in her hands and broke into heart wrenching sobs oh dont dont i began stepping toward her but as i looked at her crumpled figure i felt my words falter what could i say to her', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 5, NULL, 'How could I possibly console her when her pain was so raw, so absolute? Don''t try to comfort me, she said through her tears, her voice trembling yet resolute. Don''t talk about him. Don''t tell me that he''ll come, that he hasn''t abandoned me so cruelly and inhumanly. What''s the point? What''s the point of false hope? She paused, struggling to steady her voice, but her sobs rose again, choking her words.', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'how could i possibly console her when her pain was so raw so absolute dont try to comfort me she said through her tears her voice trembling yet resolute dont talk about him dont tell me that hell come that he hasnt abandoned me so cruelly and inhumanly whats the point whats the point of false hope she paused struggling to steady her voice but her sobs rose again choking her words', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 6, NULL, 'Can it be—can it be that there was something in my letter? Something wrong? Something—unlucky? She couldn''t go on. Her sobs overwhelmed her once more, and my heart ached as I watched her shoulders shake with despair. Oh, how cruelly! How inhumanly cruel this is! she cried out after a moment. Her words poured out in a torrent now, fast and unrestrained, as though she could no longer contain the anguish that had been building inside her for three days.', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'can it be can it be that there was something in my letter something wrong something unlucky she couldnt go on her sobs overwhelmed her once more and my heart ached as i watched her shoulders shake with despair oh how cruelly how inhumanly cruel this is she cried out after a moment her words poured out in a torrent now fast and unrestrained as though she could no longer contain the anguish that had been building inside her for three days', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 7, NULL, 'And not a single word from him. Not one line. He could have written something, anything, even just to say that he doesn''t want me, that he rejects me. But not a single word for three whole days. How easy it must be for him to wound someone, to insult a poor defenseless girl whose only fault is that she loves him. She pressed her hands against her face, her voice breaking into a whisper.', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'and not a single word from him not one line he could have written something anything even just to say that he doesnt want me that he rejects me but not a single word for three whole days how easy it must be for him to wound someone to insult a poor defenseless girl whose only fault is that she loves him she pressed her hands against her face her voice breaking into a whisper', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 8, NULL, 'Oh, what I''ve suffered during these three days! What I''ve endured! And when I think of how I went to him first! How I humbled myself! How I cried and begged him for just a little love! She trailed off, shaking her head in disbelief. Then suddenly she turned to me, her dark eyes flashing with a mix of anger and desperation. Listen, she said, her voice rising as if trying to will her words into reality, it''s not true.', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'oh what ive suffered during these three days what ive endured and when i think of how i went to him first how i humbled myself how i cried and begged him for just a little love she trailed off shaking her head in disbelief then suddenly she turned to me her dark eyes flashing with a mix of anger and desperation listen she said her voice rising as if trying to will her words into reality its not true', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 9, NULL, 'It can''t be true. This isn''t natural. Either you''re mistaken or I am. Maybe he hasn''t received the letter. Maybe he still doesn''t know about it. How could anyone—tell me, for God''s sake, explain it to me! How could anyone behave so barbarously, so cruelly as he has to me? Not a single word. Not even the lowest creature would be treated so heartlessly! Her voice broke again, and she looked at me pleadingly, her eyes searching mine for answers.', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'it cant be true this isnt natural either youre mistaken or i am maybe he hasnt received the letter maybe he still doesnt know about it how could anyone tell me for gods sake explain it to me how could anyone behave so barbarously so cruelly as he has to me not a single word not even the lowest creature would be treated so heartlessly her voice broke again and she looked at me pleadingly her eyes searching mine for answers', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 10, NULL, 'Perhaps he''s heard something, she whispered, her tone suddenly unsure. Perhaps someone told him something about me. Something terrible. What do you think? Tell me, please. What do you think? Listen, Nastenka, I said, my voice trembling as I fought to steady it, I shall go to him tomorrow. I will go in your name. Her wide, tear-streaked eyes fixed on me, and for a moment it seemed as if hope flickered faintly in them.', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'perhaps hes heard something she whispered her tone suddenly unsure perhaps someone told him something about me something terrible what do you think tell me please what do you think listen nastenka i said my voice trembling as i fought to steady it i shall go to him tomorrow i will go in your name her wide tear streaked eyes fixed on me and for a moment it seemed as if hope flickered faintly in them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 11, NULL, 'Yes, she whispered hesitantly, her voice barely audible. I will speak to him. I will question him about everything. I will tell him everything he needs to know, everything he must understand. Yes, yes, she said again, leaning toward me, as though hanging on my every word, desperate for reassurance. You''ll write a letter, Nastenka. You must write a letter, I urged, my voice growing more earnest. Don''t refuse me this, Nastenka.', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'yes she whispered hesitantly her voice barely audible i will speak to him i will question him about everything i will tell him everything he needs to know everything he must understand yes yes she said again leaning toward me as though hanging on my every word desperate for reassurance youll write a letter nastenka you must write a letter i urged my voice growing more earnest dont refuse me this nastenka', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 12, NULL, 'Don''t say no. Let me make him understand the depth of your feelings. Let me make him respect the courage of your action. He shall hear it all, and if— No, my friend, no, she interrupted suddenly, her tone resolute yet weary. Enough. Not another word, not another line from me. Enough! She shook her head, her trembling hand brushing away a tear. I don''t know him any more. I don''t love him any more.', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'dont say no let me make him understand the depth of your feelings let me make him respect the courage of your action he shall hear it all and if no my friend no she interrupted suddenly her tone resolute yet weary enough not another word not another line from me enough she shook her head her trembling hand brushing away a tear i dont know him any more i dont love him any more', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 13, NULL, 'I will—I will forget him. Her voice broke as she spoke those final words, and for a moment it seemed as though she could say no more. The silence between us felt heavy, almost unbearable. Calm yourself, Nastenka, I said gently, guiding her to sit on the bench beside me. Please, sit here. You need to rest. You need to breathe. I am calm, she insisted, though her trembling hands and tear-filled eyes betrayed her.', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'i will i will forget him her voice broke as she spoke those final words and for a moment it seemed as though she could say no more the silence between us felt heavy almost unbearable calm yourself nastenka i said gently guiding her to sit on the bench beside me please sit here you need to rest you need to breathe i am calm she insisted though her trembling hands and tear filled eyes betrayed her', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 14, NULL, 'Don''t trouble yourself. It''s nothing, really. These are only tears, and they''ll dry soon enough. Do you think—do you think I''ll do something desperate? That I''ll throw myself into the river? Her words came out as a bitter laugh, a fragile attempt to mask the depth of her despair. My heart was too full. The weight of her sorrow pressed down on me until I could hardly bear it. I tried to speak, but my throat closed and no words would come.', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'dont trouble yourself its nothing really these are only tears and theyll dry soon enough do you think do you think ill do something desperate that ill throw myself into the river her words came out as a bitter laugh a fragile attempt to mask the depth of her despair my heart was too full the weight of her sorrow pressed down on me until i could hardly bear it i tried to speak but my throat closed and no words would come', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 15, NULL, 'She took my hand, her grip warm yet trembling. Tell me, she said softly, her voice almost pleading. You wouldn''t have done this, would you? You wouldn''t have abandoned a girl who came to you of her own will, who bared her soul, humbled herself, begged for just a little love? You wouldn''t have thrown her weakness back in her face, shamed her for the foolishness of her heart, would you?', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'she took my hand her grip warm yet trembling tell me she said softly her voice almost pleading you wouldnt have done this would you you wouldnt have abandoned a girl who came to you of her own will who bared her soul humbled herself begged for just a little love you wouldnt have thrown her weakness back in her face shamed her for the foolishness of her heart would you', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 16, NULL, 'You would have taken care of her, wouldn''t you? You would have understood that she was alone, that she didn''t know how to protect herself, that she didn''t know how to guard her heart from loving you? It wouldn''t have been her fault, would it? You wouldn''t have made her feel like it was her fault? Her voice broke again, and she trailed off into a whisper. Oh, dear! Oh, dear! Nastenka! I cried, my voice raw with emotion.', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'you would have taken care of her wouldnt you you would have understood that she was alone that she didnt know how to protect herself that she didnt know how to guard her heart from loving you it wouldnt have been her fault would it you wouldnt have made her feel like it was her fault her voice broke again and she trailed off into a whisper oh dear oh dear nastenka i cried my voice raw with emotion', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 17, NULL, 'Nastenka, you''re tearing me apart, you''re wounding my heart, killing me with your words. I can''t stay silent any longer, I can''t hold it in. I must speak, I must tell you everything that''s surging inside me. As I spoke, I rose abruptly from the bench, unable to sit still under the weight of my feelings. She looked up at me in surprise, her eyes wide with curiosity and concern.', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'nastenka youre tearing me apart youre wounding my heart killing me with your words i cant stay silent any longer i cant hold it in i must speak i must tell you everything thats surging inside me as i spoke i rose abruptly from the bench unable to sit still under the weight of my feelings she looked up at me in surprise her eyes wide with curiosity and concern', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 18, NULL, 'What is it? she asked, her voice barely above a whisper. Listen, I said, my tone resolute now, listen to me, Nastenka. What I''m about to say is impossible, ridiculous, completely absurd. I know it can never be, but I can''t keep silent any more. For the sake of all that you''re suffering, for the pain you''re feeling now, I beg you to forgive me before I even begin. What is it? she asked again, drying her tears hastily as she gazed at me intently.', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'what is it she asked her voice barely above a whisper listen i said my tone resolute now listen to me nastenka what im about to say is impossible ridiculous completely absurd i know it can never be but i cant keep silent any more for the sake of all that youre suffering for the pain youre feeling now i beg you to forgive me before i even begin what is it she asked again drying her tears hastily as she gazed at me intently', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 19, NULL, 'A strange light flickered in her eyes, a mix of astonishment, curiosity, and something I couldn''t quite define. I love you, Nastenka, I said finally, the words rushing out of me like a flood breaking through a dam. There it is. Now you know everything. Now you''ll see whether you can go on speaking to me as you did before, whether you can listen to what I have to say. I spread my arms helplessly, as if to surrender to the truth I had just confessed.', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'a strange light flickered in her eyes a mix of astonishment curiosity and something i couldnt quite define i love you nastenka i said finally the words rushing out of me like a flood breaking through a dam there it is now you know everything now youll see whether you can go on speaking to me as you did before whether you can listen to what i have to say i spread my arms helplessly as if to surrender to the truth i had just confessed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 20, NULL, 'She stared at me for a moment, her expression unreadable. Then, to my astonishment, she said, Well, what then? Her voice was calm, even thoughtful. What of it? I knew you loved me long ago. I always knew. But I thought it was just that you simply liked me very much. Oh, dear, oh, dear! She pressed a hand to her cheek, clearly flustered. At first it was just liking, I admitted, my voice trembling.', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'she stared at me for a moment her expression unreadable then to my astonishment she said well what then her voice was calm even thoughtful what of it i knew you loved me long ago i always knew but i thought it was just that you simply liked me very much oh dear oh dear she pressed a hand to her cheek clearly flustered at first it was just liking i admitted my voice trembling', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 21, NULL, 'But now, Nastenka, now. I''m just like you were when you went to him with your little bundle. Only worse, Nastenka, much worse, because he didn''t care for anyone else but you. I trailed off, unable to finish the thought. She looked at me, her face a mixture of confusion and something like pity. What are you saying? she asked, her voice soft yet trembling with emotion. I don''t understand. What''s the point of this?', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'but now nastenka now im just like you were when you went to him with your little bundle only worse nastenka much worse because he didnt care for anyone else but you i trailed off unable to finish the thought she looked at me her face a mixture of confusion and something like pity what are you saying she asked her voice soft yet trembling with emotion i dont understand whats the point of this', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 22, NULL, 'Why are you—why are you so suddenly— She broke off, her cheeks flushing a deep crimson. Her eyes dropped, and she fidgeted nervously, clearly at a loss for words. I could see that my confession had shaken her, though she was trying her best to hide it. What''s to be done, Nastenka? What am I to do now? I said, my voice trembling under the weight of my emotions. I know I''m to blame.', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'why are you why are you so suddenly she broke off her cheeks flushing a deep crimson her eyes dropped and she fidgeted nervously clearly at a loss for words i could see that my confession had shaken her though she was trying her best to hide it whats to be done nastenka what am i to do now i said my voice trembling under the weight of my emotions i know im to blame', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 23, NULL, 'I''ve overstepped. I''ve abused your trust. But no, no, I''m not to blame, Nastenka. I feel it. I know it, because my heart tells me so. I could never hurt you. I could never wound you in any way. I was your friend, and I am still your friend. I have betrayed no trust. Look at me, Nastenka. My tears are falling. Let them flow. Let them fall. They harm no one.', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'ive overstepped ive abused your trust but no no im not to blame nastenka i feel it i know it because my heart tells me so i could never hurt you i could never wound you in any way i was your friend and i am still your friend i have betrayed no trust look at me nastenka my tears are falling let them flow let them fall they harm no one', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 24, NULL, 'They will dry, Nastenka. They always dry. Sit down, sit down, she said softly, guiding me back to the seat. Her hands trembled as she moved, and her voice carried the weight of her own turmoil. Oh, my God! she murmured, almost to herself. No, Nastenka, I cannot sit down, I replied, standing again almost immediately. I can''t stay here any longer. You shouldn''t have to see me again. But before I go, I must tell you everything.', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'they will dry nastenka they always dry sit down sit down she said softly guiding me back to the seat her hands trembled as she moved and her voice carried the weight of her own turmoil oh my god she murmured almost to herself no nastenka i cannot sit down i replied standing again almost immediately i cant stay here any longer you shouldnt have to see me again but before i go i must tell you everything', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 25, NULL, 'I must unburden my heart before I leave. I want you to know that you would never have found out I loved you. I would have kept my secret hidden. I would never have troubled you with it, never let my selfishness burden you at such a moment. No, I wouldn''t have dared. But I couldn''t resist speaking now, Nastenka. You spoke of it yourself. You gave me the opening.', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'i must unburden my heart before i leave i want you to know that you would never have found out i loved you i would have kept my secret hidden i would never have troubled you with it never let my selfishness burden you at such a moment no i wouldnt have dared but i couldnt resist speaking now nastenka you spoke of it yourself you gave me the opening', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 26, NULL, 'It''s your fault, not mine. You cannot drive me away from you, not now. No, no! she said quickly, trying to conceal her confusion as best as she could, though her voice betrayed her struggle. I don''t drive you away. No, I don''t. You don''t drive me away, I said, shaking my head. No, but I meant to run from you myself. I meant to leave, to vanish, to spare you this.', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'its your fault not mine you cannot drive me away from you not now no no she said quickly trying to conceal her confusion as best as she could though her voice betrayed her struggle i dont drive you away no i dont you dont drive me away i said shaking my head no but i meant to run from you myself i meant to leave to vanish to spare you this', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 27, NULL, 'But before I go, I have to tell you everything. I have to speak. Because when I saw you crying here, when I saw you weeping, tortured by the pain of being forsaken—yes, Nastenka, I will say it—tortured by the pain of your love being rejected, I felt my own heart breaking. There was so much love in my heart for you, Nastenka, so much love. And it felt so bitter, so unbearably bitter, that I couldn''t help you with my love, that my love could not ease your pain.', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'but before i go i have to tell you everything i have to speak because when i saw you crying here when i saw you weeping tortured by the pain of being forsaken yes nastenka i will say it tortured by the pain of your love being rejected i felt my own heart breaking there was so much love in my heart for you nastenka so much love and it felt so bitter so unbearably bitter that i couldnt help you with my love that my love could not ease your pain', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 28, NULL, 'My heart was breaking, and I couldn''t stay silent. I had to speak, Nastenka, I had to speak. Yes, yes, she said urgently, her voice quivering with emotion as she made an indescribable gesture, half desperate, half tender. Tell me, talk to me. Maybe you think it''s strange that I''m speaking to you like this, but— But speak. I''ll explain everything to you afterward. I will tell you everything. You pity me, Nastenka, I said, my voice breaking.', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'my heart was breaking and i couldnt stay silent i had to speak nastenka i had to speak yes yes she said urgently her voice quivering with emotion as she made an indescribable gesture half desperate half tender tell me talk to me maybe you think its strange that im speaking to you like this but but speak ill explain everything to you afterward i will tell you everything you pity me nastenka i said my voice breaking', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 29, NULL, 'That''s all. You pity me, my dear, kind friend. What''s done is done. What''s said cannot be unsaid. Isn''t that so? Well, now you know. That''s where we stand. And now that everything is out in the open—listen to me. When you were sitting here crying, I thought to myself—oh, let me tell you what I thought, Nastenka. I thought, just for a moment, that perhaps—perhaps you, in some way, had ceased to love him.', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'thats all you pity me my dear kind friend whats done is done whats said cannot be unsaid isnt that so well now you know thats where we stand and now that everything is out in the open listen to me when you were sitting here crying i thought to myself oh let me tell you what i thought nastenka i thought just for a moment that perhaps perhaps you in some way had ceased to love him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 30, NULL, 'That maybe—maybe there was a chance for me. I thought it yesterday, and the day before yesterday. And I thought that if that were true, if you no longer loved him, then I might—just might—be able to make you love me instead. I stopped, struggling to compose myself, my words stumbling out in a confused torrent. You know, you said it yourself, Nastenka, that you almost loved me. And I thought, what if—what if I could win your heart?', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'that maybe maybe there was a chance for me i thought it yesterday and the day before yesterday and i thought that if that were true if you no longer loved him then i might just might be able to make you love me instead i stopped struggling to compose myself my words stumbling out in a confused torrent you know you said it yourself nastenka that you almost loved me and i thought what if what if i could win your heart', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 31, NULL, 'What then? That''s all I wanted to say, all I needed to say. What if, by some miracle, you could love me? Nothing more. That''s all. I paused, trying to steady my trembling hands. Listen to me, Nastenka. You are my friend. No matter what, you are my friend. I know I''m just a poor, humble man of no importance. But none of that matters. What matters is this. I would love you, Nastenka.', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'what then thats all i wanted to say all i needed to say what if by some miracle you could love me nothing more thats all i paused trying to steady my trembling hands listen to me nastenka you are my friend no matter what you are my friend i know im just a poor humble man of no importance but none of that matters what matters is this i would love you nastenka', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 32, NULL, 'I would love you so deeply, so completely, that even if you continued to love him, even if he remained in your heart forever, you would never feel my love as a burden. You would feel only warmth, only gratitude. You would feel every moment that beside you stood someone whose heart beat only for you, someone who would give anything—everything—for your happiness. My voice cracked, and I buried my face in my hands.', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'i would love you so deeply so completely that even if you continued to love him even if he remained in your heart forever you would never feel my love as a burden you would feel only warmth only gratitude you would feel every moment that beside you stood someone whose heart beat only for you someone who would give anything everything for your happiness my voice cracked and i buried my face in my hands', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 33, NULL, 'Oh, Nastenka, Nastenka, what have you done to me? Don''t cry, she said suddenly, rising quickly from the seat. Her movements were hurried, almost frantic, as if she couldn''t bear to see my tears. Don''t cry. Please don''t cry. Get up. Come with me. Let''s walk. Don''t cry anymore, she repeated, pulling a handkerchief from her pocket and wiping my tears away with a tenderness that broke my heart all over again.', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'oh nastenka nastenka what have you done to me dont cry she said suddenly rising quickly from the seat her movements were hurried almost frantic as if she couldnt bear to see my tears dont cry please dont cry get up come with me lets walk dont cry anymore she repeated pulling a handkerchief from her pocket and wiping my tears away with a tenderness that broke my heart all over again', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 34, NULL, 'As we walked, she spoke, her voice soft and hesitant. Maybe—maybe I''ll tell you something. If he has truly forsaken me, if he has forgotten me, even though I still love him—I don''t want to deceive you—I still love him. But listen, answer me this. If I were to love you, for instance, if I only—she trailed off, her voice trembling, and her hand gripped mine more tightly. Oh, my friend, my dear friend, how could I have been so blind?', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'as we walked she spoke her voice soft and hesitant maybe maybe ill tell you something if he has truly forsaken me if he has forgotten me even though i still love him i dont want to deceive you i still love him but listen answer me this if i were to love you for instance if i only she trailed off her voice trembling and her hand gripped mine more tightly oh my friend my dear friend how could i have been so blind', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 35, NULL, 'How could I have laughed at your love, praised you for not loving me? How could I not have seen this, not have foreseen this? How stupid I''ve been! But—she stopped, as though she could go no further, and then said firmly, I''ve made up my mind. I will tell you. Look, Nastenka, I said quickly, my voice barely above a whisper. Do you know what? I''ll go. I''ll leave.', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'how could i have laughed at your love praised you for not loving me how could i not have seen this not have foreseen this how stupid ive been but she stopped as though she could go no further and then said firmly ive made up my mind i will tell you look nastenka i said quickly my voice barely above a whisper do you know what ill go ill leave', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 36, NULL, 'That''s what I''ll do. I''m only tormenting you now, adding to your sorrow. You''re already remorseful for laughing at me, and I can''t stand to make it worse. I don''t want to be another burden to you. It''s my fault, Nastenka. All of it is my fault. So—good-bye. Stay, she cried, her voice filled with sudden urgency. She stopped walking and turned to face me. Stay, listen to me. Can you wait?', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'thats what ill do im only tormenting you now adding to your sorrow youre already remorseful for laughing at me and i cant stand to make it worse i dont want to be another burden to you its my fault nastenka all of it is my fault so good bye stay she cried her voice filled with sudden urgency she stopped walking and turned to face me stay listen to me can you wait', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 37, NULL, 'Wait? For what? How? I asked, my heart pounding in my chest, as I stared into her tear-filled eyes. I love him, she said, her voice trembling and full of conflict. But I shall get over it. I must get over it. I cannot fail to get over it. I''m getting over it already. I feel it deep inside me as though my heart is being reshaped. Who knows? Perhaps it will all end today, for I hate him as much as I love him.', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'wait for what how i asked my heart pounding in my chest as i stared into her tear filled eyes i love him she said her voice trembling and full of conflict but i shall get over it i must get over it i cannot fail to get over it im getting over it already i feel it deep inside me as though my heart is being reshaped who knows perhaps it will all end today for i hate him as much as i love him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 38, NULL, 'He has been laughing at me, mocking me, while you—you have been here with me, weeping with me, sharing my pain, without judgment. You haven''t turned away from me as he has. You have not repulsed me. You love me, while he—he has never loved me, not truly, not in the way I thought he did. And now, my dear friend, I love you myself. She paused, catching her breath.', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'he has been laughing at me mocking me while you you have been here with me weeping with me sharing my pain without judgment you havent turned away from me as he has you have not repulsed me you love me while he he has never loved me not truly not in the way i thought he did and now my dear friend i love you myself she paused catching her breath', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 39, NULL, 'Yes, I love you. I love you as you love me. I told you this before, and you heard it yourself. I love you because you are better than he is. You are so much nobler than he could ever be, because—because— Her voice faltered, and she could not continue. The poor girl''s emotions overwhelmed her. She could not find the words to express herself, and instead laid her head upon my shoulder, then upon my chest, trembling and crying bitterly.', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'yes i love you i love you as you love me i told you this before and you heard it yourself i love you because you are better than he is you are so much nobler than he could ever be because because her voice faltered and she could not continue the poor girls emotions overwhelmed her she could not find the words to express herself and instead laid her head upon my shoulder then upon my chest trembling and crying bitterly', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 40, NULL, 'Her sobs pierced my soul. I held her as gently as I could, comforting her, murmuring words of reassurance, but her tears would not stop. She clung to me tightly, pressing my hand as though to draw strength from it, and in between her sobs she whispered brokenly, Wait, wait. It will pass in a moment. I just need a moment. These tears, they mean nothing. It''s just weakness. Please.', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'her sobs pierced my soul i held her as gently as i could comforting her murmuring words of reassurance but her tears would not stop she clung to me tightly pressing my hand as though to draw strength from it and in between her sobs she whispered brokenly wait wait it will pass in a moment i just need a moment these tears they mean nothing its just weakness please', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 41, NULL, 'Just wait until it''s over. I waited, saying nothing, afraid to break the fragile moment. Finally her sobs quieted. She dried her eyes, took a deep breath, and we began walking again, slowly, as though every step required an immense effort of will. I wanted to speak, to offer her solace, but she shook her head, silently begging me to let her gather her strength. We walked in silence for some time, until, at last, she found the courage to speak.', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'just wait until its over i waited saying nothing afraid to break the fragile moment finally her sobs quieted she dried her eyes took a deep breath and we began walking again slowly as though every step required an immense effort of will i wanted to speak to offer her solace but she shook her head silently begging me to let her gather her strength we walked in silence for some time until at last she found the courage to speak', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 42, NULL, 'It''s like this, she began, in a weak, trembling voice, one that pierced my heart with its fragile honesty. Don''t think I''m so light, so inconstant, that I could just forget or change so quickly. I loved him for an entire year, and I swear by everything I hold sacred by God Himself that in all that time I was never unfaithful to him, not even in my thoughts, but he—he despised me, he laughed at me.', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'its like this she began in a weak trembling voice one that pierced my heart with its fragile honesty dont think im so light so inconstant that i could just forget or change so quickly i loved him for an entire year and i swear by everything i hold sacred by god himself that in all that time i was never unfaithful to him not even in my thoughts but he he despised me he laughed at me', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 43, NULL, 'God forgive him, but he insulted me so deeply, he wounded my heart in ways I cannot explain, and now—she hesitated, pressing my hand tightly as though bracing herself for the admission—now I do not love him. I can''t love him. I can only love what is noble, what is generous, what understands me, and he—he is not worthy of me, he never was. Her voice grew steadier as she continued.', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'god forgive him but he insulted me so deeply he wounded my heart in ways i cannot explain and now she hesitated pressing my hand tightly as though bracing herself for the admission now i do not love him i cant love him i can only love what is noble what is generous what understands me and he he is not worthy of me he never was her voice grew steadier as she continued', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 44, NULL, 'It''s better this way, better that he has shown me now what he truly is, rather than later, when it might have been even harder to bear. It''s over, it has to be over. She paused, took a shuddering breath, and then turned to me with tear-filled eyes. But who knows, my dear friend, perhaps my love for him was never real, perhaps it was all a mistake, a delusion, maybe it all began as some childish mischief, some foolishness born out of my strict life with Grandmother.', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'its better this way better that he has shown me now what he truly is rather than later when it might have been even harder to bear its over it has to be over she paused took a shuddering breath and then turned to me with tear filled eyes but who knows my dear friend perhaps my love for him was never real perhaps it was all a mistake a delusion maybe it all began as some childish mischief some foolishness born out of my strict life with grandmother', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 45, NULL, 'Perhaps I was never meant to love him at all, but someone else, a man who would truly care for me, who would have pity on me, and—and— Her voice trailed off, and she looked away, overwhelmed by her emotions. But let''s not talk about that any more, she said, shaking her head as if to banish the thoughts. I only wanted to tell you—I wanted to say that if, although I loved him, or rather did love him, if despite all that you still feel the way you do, if your love is so great that it could drive away this old feeling from my heart, if you would take pity on me and not leave me to face my fate alone, without hope or consolation, if you truly love me as you do now, then I swear to you, with all my heart, that my gratitude, my love, will grow until it is worthy of yours.', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'perhaps i was never meant to love him at all but someone else a man who would truly care for me who would have pity on me and and her voice trailed off and she looked away overwhelmed by her emotions but lets not talk about that any more she said shaking her head as if to banish the thoughts i only wanted to tell you i wanted to say that if although i loved him or rather did love him if despite all that you still feel the way you do if your love is so great that it could drive away this old feeling from my heart if you would take pity on me and not leave me to face my fate alone without hope or consolation if you truly love me as you do now then i swear to you with all my heart that my gratitude my love will grow until it is worthy of yours', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 46, NULL, 'Will you take my hand?" "Nastenka! I cried, overcome with emotion, my voice breaking under the weight of my feelings. "Oh, Nastenka! My dear Nastenka! "Enough, enough, she said quickly, though her own voice trembled with feeling. "Well, now it''s all been said, hasn''t it? Hasn''t it? You''re happy now, aren''t you? And I—I''m happy too. But no more of this. No more. Let''s not talk about it any more, please.', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'will you take my hand nastenka i cried overcome with emotion my voice breaking under the weight of my feelings oh nastenka my dear nastenka enough enough she said quickly though her own voice trembled with feeling well now its all been said hasnt it hasnt it youre happy now arent you and i im happy too but no more of this no more lets not talk about it any more please', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 47, NULL, 'Let''s— "Let''s talk about something else, for God''s sake. "Yes, Nastenka, yes, I said fervently, though my heart was overflowing. "Enough of that. I''m happy now, so happy, and— "And yes, Nastenka, let''s talk about other things. Let''s hurry and talk before— But we couldn''t find the words, we couldn''t think of what to say. Instead, we laughed and cried together, saying a thousand meaningless, incoherent things like children caught up in the thrill of a new game.', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'lets lets talk about something else for gods sake yes nastenka yes i said fervently though my heart was overflowing enough of that im happy now so happy and and yes nastenka lets talk about other things lets hurry and talk before but we couldnt find the words we couldnt think of what to say instead we laughed and cried together saying a thousand meaningless incoherent things like children caught up in the thrill of a new game', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 48, NULL, 'We walked along the pavement, then turned back and crossed the road, only to stop and return to the embankment. We moved without purpose, without direction, lost in the strange, joyful, bittersweet haze of that moment. We were like children, stumbling through the beginnings of something neither of us fully understood. "I am living alone now, Nastenka, I began hesitantly, my voice soft, as though afraid to disturb the dreamlike quality of our conversation.', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'we walked along the pavement then turned back and crossed the road only to stop and return to the embankment we moved without purpose without direction lost in the strange joyful bittersweet haze of that moment we were like children stumbling through the beginnings of something neither of us fully understood i am living alone now nastenka i began hesitantly my voice soft as though afraid to disturb the dreamlike quality of our conversation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 49, NULL, 'But tomorrow, everything will change. "Of course you already know, Nastenka, that I''m not a wealthy man. I only have twelve hundred roubles to my name, but that doesn''t matter, does it? "Of course it doesn''t matter, she replied earnestly, her eyes sparkling with warmth and determination. "And you know, Granny has her pension, so she won''t be a burden. We must take Granny with us, of course. "Absolutely we must take Granny, I agreed, nodding with enthusiasm.', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'but tomorrow everything will change of course you already know nastenka that im not a wealthy man i only have twelve hundred roubles to my name but that doesnt matter does it of course it doesnt matter she replied earnestly her eyes sparkling with warmth and determination and you know granny has her pension so she wont be a burden we must take granny with us of course absolutely we must take granny i agreed nodding with enthusiasm', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 50, NULL, '"But then there''s Matrona to think about as well. "Yes, Nastenka said thoughtfully, tapping her chin with her finger. "And we can''t forget about Fekla either. "Matrona is a good woman, I said, smiling as though picturing her bustling about. "But she does have one little fault. She has no imagination whatsoever, Nastenka. Absolutely none, not even a spark. But that''s all right. We''ll manage. "That''s fine. They can live together, Nastenka replied decisively, waving her hand as though brushing aside any objections.', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'but then theres matrona to think about as well yes nastenka said thoughtfully tapping her chin with her finger and we cant forget about fekla either matrona is a good woman i said smiling as though picturing her bustling about but she does have one little fault she has no imagination whatsoever nastenka absolutely none not even a spark but thats all right well manage thats fine they can live together nastenka replied decisively waving her hand as though brushing aside any objections', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 51, NULL, '"But you must move to us tomorrow. There''s no time to waste. "Move to you? I asked, feigning surprise. "How would that work? "Of course you must, she said firmly, her tone playful yet resolute. "We have a room on the top floor. It''s empty now. There was an old lady living there before, but she left a while ago. I know Granny would like the idea of having a young man in the house.', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'but you must move to us tomorrow theres no time to waste move to you i asked feigning surprise how would that work of course you must she said firmly her tone playful yet resolute we have a room on the top floor its empty now there was an old lady living there before but she left a while ago i know granny would like the idea of having a young man in the house', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 52, NULL, 'She even said to me, "Why not let a young man rent it? I asked her, "Why a young man, Granny? And do you know what she said? "Oh, because I''m old and like the company. But then she added quickly, "Only don''t you go imagining, Nastenka, that I want him as a husband for you. So of course I guessed it was exactly what she was thinking. "Oh, Nastenka! I exclaimed, unable to contain my laughter.', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'she even said to me why not let a young man rent it i asked her why a young man granny and do you know what she said oh because im old and like the company but then she added quickly only dont you go imagining nastenka that i want him as a husband for you so of course i guessed it was exactly what she was thinking oh nastenka i exclaimed unable to contain my laughter', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 53, NULL, 'We both laughed then, the kind of laughter that feels warm and uncontainable, bubbling up from the heart, as if the future were already laid out before us, gleaming with promise. "Enough of that, enough of that, she said at last, trying to compose herself but still giggling. "Now tell me, where do you live again? I''ve forgotten. "Over that way, I said, gesturing vaguely. "Near X Bridge, in Baranikov''s buildings. "Oh, that big house? she asked, her brow furrowing in thought.', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'we both laughed then the kind of laughter that feels warm and uncontainable bubbling up from the heart as if the future were already laid out before us gleaming with promise enough of that enough of that she said at last trying to compose herself but still giggling now tell me where do you live again ive forgotten over that way i said gesturing vaguely near x bridge in baranikovs buildings oh that big house she asked her brow furrowing in thought', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 54, NULL, '"Yes, that big house, I confirmed. "I know it, she said with a nod. "It''s a nice house. But you know what? You should give it up. Leave it behind and come to us as soon as possible. "Tomorrow, Nastenka, I said with enthusiasm. "Tomorrow it will be done. I owe a little on my rent there, but it doesn''t matter. I''ll pay it off soon enough when I get my salary. "And you know what? she said suddenly, her face lighting up with excitement.', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'yes that big house i confirmed i know it she said with a nod its a nice house but you know what you should give it up leave it behind and come to us as soon as possible tomorrow nastenka i said with enthusiasm tomorrow it will be done i owe a little on my rent there but it doesnt matter ill pay it off soon enough when i get my salary and you know what she said suddenly her face lighting up with excitement', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 55, NULL, '"I think I might start giving lessons. I''ll learn something new myself, and then I can teach others. "That''s a splendid idea, I exclaimed. "And I''m expecting a bonus soon, so between us will be just fine. "Perfect. Then by tomorrow you''ll officially be my lodger, she said, clapping her hands together as though sealing the deal. "And when everything''s settled, I added, "we''ll go to the theatre to see The Barber of Seville.', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'i think i might start giving lessons ill learn something new myself and then i can teach others thats a splendid idea i exclaimed and im expecting a bonus soon so between us will be just fine perfect then by tomorrow youll officially be my lodger she said clapping her hands together as though sealing the deal and when everythings settled i added well go to the theatre to see the barber of seville', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 56, NULL, 'I heard they''ll be performing it again soon. "Yes, we''ll go, she agreed, nodding eagerly. Then, after a moment''s thought, she added, "But perhaps we should see something else this time, something new, something we haven''t seen before. "Of course something else, I said quickly, realizing she was right. "That will be better. I don''t know why I didn''t think of it before. And so we planned, dreaming aloud about a future that seemed as though it might begin the very next day.', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'i heard theyll be performing it again soon yes well go she agreed nodding eagerly then after a moments thought she added but perhaps we should see something else this time something new something we havent seen before of course something else i said quickly realizing she was right that will be better i dont know why i didnt think of it before and so we planned dreaming aloud about a future that seemed as though it might begin the very next day', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 57, NULL, 'The world felt limitless, brimming with possibilities, as though nothing could ever stand in our way. As we continued talking like this, it felt as though we were moving in a dream, swept away by a kind of joyous delirium, an intoxicating rush of emotions neither of us could fully understand. We walked without purpose, as if the paths we took were chosen not by us but by some invisible force.', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'the world felt limitless brimming with possibilities as though nothing could ever stand in our way as we continued talking like this it felt as though we were moving in a dream swept away by a kind of joyous delirium an intoxicating rush of emotions neither of us could fully understand we walked without purpose as if the paths we took were chosen not by us but by some invisible force', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 58, NULL, 'At times we stopped in the middle of the street or on the embankment, forgetting ourselves completely, lost in conversation, laughing one moment, tears brimming in our eyes the next. Then almost on impulse we''d start moving again, only to realize we had wandered to some place neither of us had intended to go. It seemed as though our feet carried us of their own accord while our words spilled out in a chaotic, endless stream.', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'at times we stopped in the middle of the street or on the embankment forgetting ourselves completely lost in conversation laughing one moment tears brimming in our eyes the next then almost on impulse wed start moving again only to realize we had wandered to some place neither of us had intended to go it seemed as though our feet carried us of their own accord while our words spilled out in a chaotic endless stream', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 59, NULL, 'Occasionally Nastenka would decide it was time to go home, saying it firmly, almost as though to remind herself of a forgotten duty. Yet even then something always held her back. I couldn''t bring myself to insist, and so, despite her resolve, we found ourselves delaying again and again. I would offer to walk her home and she''d agree, but somehow, instead of heading directly to her house, we would meander back toward the embankment and end up at our seat, as though drawn there by an invisible tether.', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'occasionally nastenka would decide it was time to go home saying it firmly almost as though to remind herself of a forgotten duty yet even then something always held her back i couldnt bring myself to insist and so despite her resolve we found ourselves delaying again and again i would offer to walk her home and shed agree but somehow instead of heading directly to her house we would meander back toward the embankment and end up at our seat as though drawn there by an invisible tether', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 60, NULL, 'And every time we returned Nastenka would sigh deeply, and tears would glisten in her eyes once more. Those moments filled me with a quiet dread, as if the fragile spell we shared might break at any second. But then she would press my hand gently, reassuringly, urging me to talk, to laugh, to carry on as though nothing had changed. And so we walked on, as though the night might stretch endlessly before us.', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'and every time we returned nastenka would sigh deeply and tears would glisten in her eyes once more those moments filled me with a quiet dread as if the fragile spell we shared might break at any second but then she would press my hand gently reassuringly urging me to talk to laugh to carry on as though nothing had changed and so we walked on as though the night might stretch endlessly before us', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 61, NULL, 'At last Nastenka spoke with a mix of finality and reluctance. It really is time I went home, she said, her voice softer than usual. It must be very late by now. We have to stop being so childish. Yes, Nastenka, I replied, though my voice lacked the conviction of hers. But as for me, I won''t be going home. I know I won''t sleep tonight. I don''t think I''ll sleep either, she admitted with a faint smile.', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'at last nastenka spoke with a mix of finality and reluctance it really is time i went home she said her voice softer than usual it must be very late by now we have to stop being so childish yes nastenka i replied though my voice lacked the conviction of hers but as for me i wont be going home i know i wont sleep tonight i dont think ill sleep either she admitted with a faint smile', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 62, NULL, 'But still, you must see me home. Of course, how could I not? This time, she said with a mischievous glint in her eye, we really will make it to the house, promise me. Honor bright, I said with a laugh, raising my hand as if taking an oath. Truly, no more turning back halfway? Truly, I swear it. Well, then, come along. Come along, I echoed, but then I paused, looking upward.', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'but still you must see me home of course how could i not this time she said with a mischievous glint in her eye we really will make it to the house promise me honor bright i said with a laugh raising my hand as if taking an oath truly no more turning back halfway truly i swear it well then come along come along i echoed but then i paused looking upward', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 63, NULL, 'Nastenka, just look at the sky. Look how beautiful it is tonight. Tomorrow will be glorious. You can tell by that deep blue and the way the moon shines so brightly. Do you see that golden cloud drifting across it now? Look, look, no, it''s passed by. Isn''t it breathtaking? But Nastenka wasn''t looking at the sky. She stood silently beside me, her body unnaturally still. When I turned to her, I noticed how pale she had become, as though all the color had drained from her cheeks in an instant.', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'nastenka just look at the sky look how beautiful it is tonight tomorrow will be glorious you can tell by that deep blue and the way the moon shines so brightly do you see that golden cloud drifting across it now look look no its passed by isnt it breathtaking but nastenka wasnt looking at the sky she stood silently beside me her body unnaturally still when i turned to her i noticed how pale she had become as though all the color had drained from her cheeks in an instant', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 64, NULL, 'A moment later, she moved closer to me, pressing her trembling hand into mine. Her fingers were cold, and I felt an uneasy chill crawl up my spine. What''s wrong, Nastenka? I asked, my voice barely above a whisper. Before she could answer, a young man passed by us, walking briskly. He paused a few steps ahead, turned, and stared at us intently. My heart began to pound wildly in my chest.', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'a moment later she moved closer to me pressing her trembling hand into mine her fingers were cold and i felt an uneasy chill crawl up my spine whats wrong nastenka i asked my voice barely above a whisper before she could answer a young man passed by us walking briskly he paused a few steps ahead turned and stared at us intently my heart began to pound wildly in my chest', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 65, NULL, 'Who is it, Nastenka? I asked again, my voice unsteady now. It''s him, she whispered, her voice so faint it was almost inaudible. Her trembling intensified, and she clung to me as though seeking protection, though I could feel her pulling away even as she leaned closer, and then I heard his voice. Nastenka! Nastenka! It''s you! The sound of his voice struck me like a thunderclap. At that moment she tore herself away from me with a cry that was almost a sob, and ran toward him.', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'who is it nastenka i asked again my voice unsteady now its him she whispered her voice so faint it was almost inaudible her trembling intensified and she clung to me as though seeking protection though i could feel her pulling away even as she leaned closer and then i heard his voice nastenka nastenka its you the sound of his voice struck me like a thunderclap at that moment she tore herself away from me with a cry that was almost a sob and ran toward him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 66, NULL, 'It was as though she had been released from a spell, her movements filled with desperate joy. My heart sank as I stood frozen, watching her fling herself into his arms. But even as she embraced him, she turned back toward me, her face radiant with gratitude and something deeper, something I couldn''t name. Before I could react, she ran back to me, her arms flung wide and threw them around my neck.', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'it was as though she had been released from a spell her movements filled with desperate joy my heart sank as i stood frozen watching her fling herself into his arms but even as she embraced him she turned back toward me her face radiant with gratitude and something deeper something i couldnt name before i could react she ran back to me her arms flung wide and threw them around my neck', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 67, NULL, 'She kissed me warmly, tenderly, a gesture of profound affection and thanks. Then, as swiftly as she had come, she let go, turned back to him, and took his hand. Without a word, she led him away, her steps filled with a kind of trembling eagerness. I stood rooted to the spot, unable to move, watching them walk away together. My chest felt hollow, as though something essential had been torn from me, leaving only an aching emptiness in its place.', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'she kissed me warmly tenderly a gesture of profound affection and thanks then as swiftly as she had come she let go turned back to him and took his hand without a word she led him away her steps filled with a kind of trembling eagerness i stood rooted to the spot unable to move watching them walk away together my chest felt hollow as though something essential had been torn from me leaving only an aching emptiness in its place', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'fourth night', 'Fourth Night', 68, NULL, 'Still I couldn''t bring myself to look away. At last their figures disappeared into the distance, swallowed by the shadows of the night. I stood there for what felt like an eternity, gazing after them, unable to shake the weight that had settled over me. The world around me seemed suddenly quieter, colder, as though it too had been abandoned.', '', NULL, NULL, NULL, NULL, 'white nights fourth night', 'still i couldnt bring myself to look away at last their figures disappeared into the distance swallowed by the shadows of the night i stood there for what felt like an eternity gazing after them unable to shake the weight that had settled over me the world around me seemed suddenly quieter colder as though it too had been abandoned', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'morning', 'Morning', 0, NULL, 'My night gave way to the morning, though the new day brought no relief. The rain fell steadily, its monotonous tapping against the windowpane filling the room with a sense of dreariness. Outside the world was shrouded in grey, and inside the dim light seemed to make the walls press in closer. My head throbbed, and a faint dizziness clouded my thoughts. A dull fever seemed to creep through my limbs, draining what little strength I had left.', '', NULL, NULL, NULL, NULL, 'white nights morning', 'my night gave way to the morning though the new day brought no relief the rain fell steadily its monotonous tapping against the windowpane filling the room with a sense of dreariness outside the world was shrouded in grey and inside the dim light seemed to make the walls press in closer my head throbbed and a faint dizziness clouded my thoughts a dull fever seemed to creep through my limbs draining what little strength i had left', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'morning', 'Morning', 1, NULL, '"Sir, there''s a letter for you, Matrona said gently, bending toward me. "The postman just delivered it. "A letter? I exclaimed, the words escaping my lips before I could process them. "From whom? I asked, sitting up sharply in my chair. "I don''t know, sir, she replied calmly. "You should check. It might say who it''s from. My hands trembled as I took the letter. I stared at the envelope for a moment, recognizing the handwriting.', '', NULL, NULL, NULL, NULL, 'white nights morning', 'sir theres a letter for you matrona said gently bending toward me the postman just delivered it a letter i exclaimed the words escaping my lips before i could process them from whom i asked sitting up sharply in my chair i dont know sir she replied calmly you should check it might say who its from my hands trembled as i took the letter i stared at the envelope for a moment recognizing the handwriting', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'morning', 'Morning', 2, NULL, 'My heart leapt, then sank under the weight of anticipation. It was from her. It was from Nastenka. Breaking the seal with unsteady fingers, I unfolded the letter. For a moment the words swam before my eyes, and then I began to read. "Oh, forgive me. Please, forgive me. I am begging you on my knees to forgive me. I''ve deceived you, and I''ve deceived myself. Everything was a dream, an illusion.', '', NULL, NULL, NULL, NULL, 'white nights morning', 'my heart leapt then sank under the weight of anticipation it was from her it was from nastenka breaking the seal with unsteady fingers i unfolded the letter for a moment the words swam before my eyes and then i began to read oh forgive me please forgive me i am begging you on my knees to forgive me ive deceived you and ive deceived myself everything was a dream an illusion', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'morning', 'Morning', 3, NULL, 'My heart aches for you today. Please forgive me. Don''t blame me, because I haven''t changed how I feel about you. I told you I would love you, and I still do. I love you now more than I ever did. Oh, if only I could love you both at once! If only you were him! "Oh, if only he were you, echoed through my mind as I read. Her words stirred memories of what she had said before, cutting deeper into my heart.', '', NULL, NULL, NULL, NULL, 'white nights morning', 'my heart aches for you today please forgive me dont blame me because i havent changed how i feel about you i told you i would love you and i still do i love you now more than i ever did oh if only i could love you both at once if only you were him oh if only he were you echoed through my mind as i read her words stirred memories of what she had said before cutting deeper into my heart', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'morning', 'Morning', 4, NULL, '"God knows what I would do for you now. I know you''re sad and heartbroken, and I know I''ve hurt you. But you also know that when someone truly loves, they forgive quickly. And you love me, don''t you? Thank you, thank you for that love. It will stay with me forever, like a sweet dream that lingers even after waking. I will always remember the moment you opened your heart to me so selflessly, like a brother, and took my broken heart into your care with such tenderness and kindness.', '', NULL, NULL, NULL, NULL, 'white nights morning', 'god knows what i would do for you now i know youre sad and heartbroken and i know ive hurt you but you also know that when someone truly loves they forgive quickly and you love me dont you thank you thank you for that love it will stay with me forever like a sweet dream that lingers even after waking i will always remember the moment you opened your heart to me so selflessly like a brother and took my broken heart into your care with such tenderness and kindness', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'morning', 'Morning', 5, NULL, '"If you forgive me, I will carry the memory of your love in my heart forever, like an unshakable gratitude etched into my soul. I will honor that memory. I will stay true to it. I won''t betray it, nor will I betray my heart. It remains as constant as ever. It found its way back to him so easily, so quickly, because it always belonged to him." I paused, the letter trembling in my hands, and I swallowed hard before continuing.', '', NULL, NULL, NULL, NULL, 'white nights morning', 'if you forgive me i will carry the memory of your love in my heart forever like an unshakable gratitude etched into my soul i will honor that memory i will stay true to it i wont betray it nor will i betray my heart it remains as constant as ever it found its way back to him so easily so quickly because it always belonged to him i paused the letter trembling in my hands and i swallowed hard before continuing', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'morning', 'Morning', 6, NULL, 'The words blurred, but I pressed on. "We''ll meet again. You''ll come to us. You won''t leave us. You''ll always be my friend, my brother. And when you see me, you''ll give me your hand, won''t you? Please say you will. Tell me you''ve forgiven me. Tell me you still love me, just as you did before. Oh, don''t stop loving me. Please don''t abandon me, because I love you so much in this moment.', '', NULL, NULL, NULL, NULL, 'white nights morning', 'the words blurred but i pressed on well meet again youll come to us you wont leave us youll always be my friend my brother and when you see me youll give me your hand wont you please say you will tell me youve forgiven me tell me you still love me just as you did before oh dont stop loving me please dont abandon me because i love you so much in this moment', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'morning', 'Morning', 7, NULL, 'I want to be worthy of your love, and I promise I''ll work to deserve it. My dear, next week I''m marrying him. He has come back to me, still in love, still thinking of me. You won''t be angry that I''m writing to you about him, will you? But I want to see you again, with him. I know you''ll like him. Please say you will. Forgive me, remember me, and love me always.', '', NULL, NULL, NULL, NULL, 'white nights morning', 'i want to be worthy of your love and i promise ill work to deserve it my dear next week im marrying him he has come back to me still in love still thinking of me you wont be angry that im writing to you about him will you but i want to see you again with him i know youll like him please say you will forgive me remember me and love me always', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'morning', 'Morning', 8, NULL, 'Your, Nastenka." I read the letter again and again, unable to stop myself. Each word felt like a wave crashing over me, and tears filled my eyes until they overflowed. Finally, the letter slipped from my hands, and I covered my face, overwhelmed by emotion. "Dearie, dearie, Matrona called out from the doorway. "What is it, Matrona? I asked, my voice breaking slightly. "I''ve taken down all the cobwebs from the ceiling.', '', NULL, NULL, NULL, NULL, 'white nights morning', 'your nastenka i read the letter again and again unable to stop myself each word felt like a wave crashing over me and tears filled my eyes until they overflowed finally the letter slipped from my hands and i covered my face overwhelmed by emotion dearie dearie matrona called out from the doorway what is it matrona i asked my voice breaking slightly ive taken down all the cobwebs from the ceiling', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'morning', 'Morning', 9, NULL, 'You could have a wedding here, or even throw a party if you wanted, she said cheerfully. I turned to look at Matrona. She was still sturdy and strong for her age, a lively woman who carried herself with youthful energy, yet in that moment I suddenly saw her differently. In my mind she aged before my eyes, her gaze dull, her face deeply lined, her figure stooped and frail.', '', NULL, NULL, NULL, NULL, 'white nights morning', 'you could have a wedding here or even throw a party if you wanted she said cheerfully i turned to look at matrona she was still sturdy and strong for her age a lively woman who carried herself with youthful energy yet in that moment i suddenly saw her differently in my mind she aged before my eyes her gaze dull her face deeply lined her figure stooped and frail', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'morning', 'Morning', 10, NULL, 'I couldn''t explain why, but that vision seemed to fill the entire room. I imagined my surroundings mirroring her decay. The walls appeared to lose their colour, the floors seemed worn and faded, and the cobwebs she had proudly removed seemed to grow back thicker and heavier than before. I couldn''t shake the feeling that the room itself was growing old with her, taking on the weight of years. When I glanced out the window, even the house across the street seemed affected by time.', '', NULL, NULL, NULL, NULL, 'white nights morning', 'i couldnt explain why but that vision seemed to fill the entire room i imagined my surroundings mirroring her decay the walls appeared to lose their colour the floors seemed worn and faded and the cobwebs she had proudly removed seemed to grow back thicker and heavier than before i couldnt shake the feeling that the room itself was growing old with her taking on the weight of years when i glanced out the window even the house across the street seemed affected by time', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'morning', 'Morning', 11, NULL, 'Its once bright facade now looked dim and weathered. The stucco on the grand columns was crumbling and flaking off, the cornices showed dark cracks, and the once vivid yellow walls had turned patchy and dull. Perhaps it was the sun. It had broken briefly through the clouds, casting a golden light, only to retreat again behind the veil of rain, leaving everything looking grey and lifeless once more. Or perhaps it was my own imagination, painting my future in bleak, sombre tones.', '', NULL, NULL, NULL, NULL, 'white nights morning', 'its once bright facade now looked dim and weathered the stucco on the grand columns was crumbling and flaking off the cornices showed dark cracks and the once vivid yellow walls had turned patchy and dull perhaps it was the sun it had broken briefly through the clouds casting a golden light only to retreat again behind the veil of rain leaving everything looking grey and lifeless once more or perhaps it was my own imagination painting my future in bleak sombre tones', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'morning', 'Morning', 12, NULL, 'I saw myself in that room fifteen years from now, just as lonely, just as unchanged. The same Matrona would still be there, no wiser, no more lively than she was to-day. But to think I could ever resent you, Nastenka. How could I? That I could darken your happiness with bitterness, or weigh down your heart with guilt. That I could speak words of blame to disturb your peace, or spoil the joy you feel as you walk to the altar with him.', '', NULL, NULL, NULL, NULL, 'white nights morning', 'i saw myself in that room fifteen years from now just as lonely just as unchanged the same matrona would still be there no wiser no more lively than she was to day but to think i could ever resent you nastenka how could i that i could darken your happiness with bitterness or weigh down your heart with guilt that i could speak words of blame to disturb your peace or spoil the joy you feel as you walk to the altar with him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'morning', 'Morning', 13, NULL, 'Never, never. I could never be so cruel. Instead I wish for you the clearest skies, for your laughter to remain bright and your smiles unclouded. May you never feel regret, may your joy remain untouchable, and may you be blessed for giving even one moment of pure happiness to someone who will always be grateful. A single moment of happiness, a brief spark of light in a dark life.', '', NULL, NULL, NULL, NULL, 'white nights morning', 'never never i could never be so cruel instead i wish for you the clearest skies for your laughter to remain bright and your smiles unclouded may you never feel regret may your joy remain untouchable and may you be blessed for giving even one moment of pure happiness to someone who will always be grateful a single moment of happiness a brief spark of light in a dark life', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('white-nights', 'chapter', 'morning', 'Morning', 14, NULL, 'Isn''t that enough? Isn''t that worth an entire lifetime?', '', NULL, NULL, NULL, NULL, 'white nights morning', 'isnt that enough isnt that worth an entire lifetime', '');
